window.GDHF_AGENDA = {"sessions":[{"id":"s0","t":"Registration & Check In","d":"2026-12-01","s":"14:00","e":"18:00","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s231","t":"Tea Break","d":"2026-12-02","s":"10:15","e":"10:30","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s203","t":"World Bank Plenary: Digitally Enabled Primary Healthcare: Shaping the Future of Health Systems","d":"2026-12-02","s":"10:30","e":"11:15","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[{"n":"Matthew Hulse","a":"The World Bank","b":"Matthew Hulse (Matt) is the Program Manager for Digital Health and AI at the World Bank Group. With diverse experience in embedded devices and digital communication technologies, he bridges the worlds of public policy and technology investment. He has worked worldwide on digital health, telecommunications access issues expanding digital and economic development, equal and affordable access, and lifesaving information for humanitarian assistance. At the World Bank he advises technology investments for health service delivery; as well as serving as a coordinator and focal point for various health, data, and digital information working groups. Matt champions inclusive digital development in partnership with market-driven investment and global public goods to advance accessible, open, and safe healthcare."}]},{"id":"s204","t":"Surgical Data Science Collective Plenary: Global Surgery and Surgical Data","d":"2026-12-02","s":"11:15","e":"12:00","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s6","t":"Lightning Talk: Fondation Pierre Fabre","d":"2026-12-02","s":"12:00","e":"12:15","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s7","t":"Lunch Break (sponsored by Fondation Pierre Fabre)","d":"2026-12-02","s":"12:15","e":"13:30","tags":["In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s200","t":"Discovery Stage: Climate and community health resilience","d":"2026-12-02","s":"12:20","e":"12:50","tags":["Discovery Stage","Climate and Health","In-person"],"fmt":"Discovery Stage","theme":"Climate and Health","mode":"In-person","desc":"Three short presentations on how digital tools can help health systems respond to climate and community health risks, from heat exposure in pregnancy and hepatitis B case finding through community pharmacies in Vietnam to multisector data on climate-induced malnutrition in Sri Lanka.\n\nPresentations in this session:\n7629 - Quantifying misclassification in maternal heat exposure: Implications for heat-health alert thresholds for pregnant women (Ruvimbo Forget)\n8511 - Strengthening Health System Resilience: Enhancing Hepatitis B Case Finding through Tech-Enhanced Community Pharmacy in Vietnam (Josselyn Neukom)","sp":[{"n":"Ruvimbo Forget","a":"Wits Planetary Health","b":"Ruvimbo is a dedicated biostatistician at Wits Planetary Health Research with a strong foundation in public health and a master's in epidemiology and biostatistics from the University of Witwatersrand. Her work focuses on climate and health research, particularly the impact of heat exposure on maternal health.projects to support evidence-based interventions for climate adaptation, particularly addressing heat-related health impacts. She is passionate…"},{"n":"Josselyn Neukom","a":"SwipeRx (mClinica)","b":"Josselyn Neukom is the Senior Vice President of the Public Health Divison at SwipeRx, leading partnerships with global health partners to increase pharmacy contributions to public and community health priorities through largest digital network of pharmacies in Southeast Asia connected via SwipeRx. She is responsible for ensuring quality across a regional portfolio of digital health programs and research leveraging a suite of technology-based trade…"},{"n":"Piyumi Gamage","a":"Ministry of Health Sri Lanka","b":"A dental surgeon and a postgraduate trainee in Health Informatics at the Postgraduate Institute of Medicine, University of Colombo."}]},{"id":"s241","t":"Discovery Stage: Aligning Partners, Platforms and Priorities: AeHIN's Convergence Approach to National Digital Health Programmes","d":"2026-12-02","s":"12:50","e":"13:20","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"National digital health efforts face fragmentation across priorities, partners, platforms and funding streams. This session provides a quick overview of AeHIN's convergence approach, grounded in the GAPS framework (Governance, Architecture, Programme Management, Standards and Interoperability), showing how multi-stakeholder workshops align investments to build sustainable, interoperable, people-centered national digital health programmes.\n\nHosted by the Asia eHealth Information Network (AeHIN).","sp":[{"n":"Jai Ganesh Udayasankaran","a":"Asia eHealth Information Network (AeHIN)","b":"Jai Ganesh Udayasankaran (Jai) is the Executive Director of the Asia eHealth Information Network (AeHIN). He brings more than 20 years of experience in planning, procuring, and implementing digital health solutions, including web-based EMR, PACS, telehealth, and chronic disease management portals.\n\nJai serves on several global and national bodies. He is a Board member of the Global Digital Health Network (GDHN) and sits on the eHealth Expert Committee of the Fondation Pierre Fabre's Global South eHealth Observatory and the Technical Committee of the Global Digital Health Monitor (GDHM). He also contributes to ISO/TC 215 Health Informatics Working Group 12 on Telehealth and Virtual Care, and to the Health Informatics Sectional Committee of the Bureau of Indian Standards (BIS). Working closely with ministries of health and partners, he has led digital health convergence workshops across Asia Pacific and South Africa."},{"n":"Fazilah binti Shaik Allaudin","a":"Asia eHealth Information Network (AeHIN)","b":"Previously the Penang State Health Director responsible for all health-related matters in the State. Prior, she has been leading digital health & innovation strategies in MOH Malaysia, and led the national EMR project. She has been part of the governing committee for AeHIN for more than 10 years. She holds an M.D. and an MBA in Healthcare Administration and is certified in Enterprise Architecture (TOGAF 9.0) and in Governance & Management of Enterprise IT (COBIT 5.0)."},{"n":"Kristin Chloe Pascual","a":"Asia eHealth Information Network (AeHIN)","b":""}]},{"id":"s9","t":"Ministerial Program: Trusted Digital Health and AI Cooperation","sum":"Opening remarks by the Minister of Public Health (MoPH) of Thailand, Thai cultural show, MoPH Digital Health Awards, and a high-level policy dialogue panel on the shared digital health and AI priorities that need political leadership.","d":"2026-12-02","s":"13:30","e":"15:30","tags":["Plenary","Hybrid Livestream"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"Thailand’s Minister of Public Health opens with a ministerial address, followed by a Thai cultural traditional drumming show, and next the Ministry of Public Health Digital Health Awards recognising innovation across the Thai health system. The second hour will feature a high-level policy dialogue panel with the Minister of Public Health and other senior executive officials which will ask what governments must get right in digital health and AI, and which choices need decisions from leaders. The panel will draw on the findings of the Convergence Bangkok 2026 pre-conference workshop and helps shape a Bangkok Statement on Trusted Digital Health and AI Cooperation.","sp":[{"n":"Pattana Promphat","a":"Minister of Public Health, Thailand","b":""}]},{"id":"s12","t":"Discovery Stage Fireside Chat: Co-Designing a Closed-Loop Integrated AI-Enabled Self-Care and Primary Healthcare Framework for People-Centred Health Systems","d":"2026-12-02","s":"15:30","e":"16:00","tags":["Discovery Stage","Governance and Digital Health at Scale","In-person"],"fmt":"Discovery Stage","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"This fireside chat looks at how health systems can link AI-enabled self-care, community support and primary healthcare into one closed loop of care. It draws on mDoc's CompleteHealth platform and on perspectives from the Lagos State Primary Health Care Board, the Nigeria AI Scaling Hub at Lagos Business School and the West African Institute of Public Health. The conversation covers practical lessons from adding AI-supported self-care to routine primary care, how to build referral and feedback loops between individuals, community health workers and facilities, and the policies, partnerships and digital public infrastructure needed to sustain this approach.","sp":[{"n":"Chiagozie Abiakam","a":"mDoc Healthcare","b":"BPHARM, MSc.HS, PMP, MPH in View Manager Women’s Wellness, mDoc Health Chiagozie Abiakam is a clinical pharmacist and technical program manager with over 12 years of experience in clinical pharmacy and healthcare project management. She leverages her expertise in behavioural science, data analysis, and AI technology to co-design and implement innovative solutions that enhance maternal health outcomes and address social determinants of health. As…"}]},{"id":"s10","t":"Poster Presentations (Round 1)","d":"2026-12-02","s":"15:30","e":"17:00","tags":["Poster Presentation","In-person"],"fmt":"Poster Presentation","theme":"","mode":"In-person","desc":"The first poster round covers AI for screening and early warning, climate-sensitive disease risk, digital learning for health workers, financing, interoperability and patient registration. Presenters will be at their posters to discuss their work.\n\nPoster presentations in this session:\n7810 - Health Providers' Attitudes Towards AI-Enabled Health Innovations and Their Influence on Scaling Beyond Pilot Implementation in LMICs: A Rapid Systematic Review (Tamadur Almahdi)\n8359 - Designing a Generative AI Chatbot for Peer Support among Young Adults Living with HIV in Uganda: A Pre-Implementation Qualitative Study (Timothy Kintu)\n8498 - Local AI-Enabled Early Cataract Screening System Using Smartphone Images (Michael Tjalve, Halima Tus Sadia)\n8742 - The Emerging Role Of Artificial Intelligence in Simulation-Based Medical Education: A PubMed Narrative Literature Review (Vijaya Palaniappan)\n7718 - A Climate-Responsive Malaria Risk Index and Machine Learning Framework for Spatially Targeted Early Warning in Ethiopia (Ephrem Biruk Gashaw)\n7120 - Innovative Financing Pathways for Sustainable Digital Health Systems in Low- and Middle-Income Countries: Lessons from Partners for Health and Development in Africa (PHDA) (Evans Ongechi)\n7777 - 14,735 Women Mapped, 69% Screened in 6 Days: Digitizing Cervical Cancer Screening in Rural Kenya (Peter Otieno Owuor, Arti Sahu)\n8152 - WASHmobile: Using Mobile Messaging and E-Vouchers to Target Diarrhea Prevention in High-Risk Communities (Christine Hortinela)\n8294 - Scalable Digital Prevention Platform for Risk Assessment and Action Planning (Dr Bala Nair)\n8415 - Learning Without Borders: Scaling Blended Learning to Reach Rural, Agrarian and Pastoralist Health Workers in Ethiopia (Bezawit Mesfin Hunegnaw)\n7513 - Integrating RJ-CHIP with Nikshay for Strengthened TB Management: A Replicable Digital Health Framework (Rajeev Dhakad, Kartik Sharma, Purushotam Soni)\n8072 - Smart Data, Stronger Systems: Scaling Interoperability and Immunization in Nigeria via WHO SMART Guidelines (Olasoji Fasogbon)\n8398 - From barcode to digital identity: patient self-registration at the National Hospital of Sri Lanka and a practical path to future identity services (Prasanjith Chanaka Dissanayake, Kaushalya Wijesekara)\n7186 - Health worker motivation: The key to quality Logistics Management Information System (LMIS) Data (Olayinka Oloyede)\n8146 - From community to action: empowering community health workers through digital learning (Carlos Albrecht)\n7547 - Machine Learning–Based Identification of Brain Tumor Patients Using Real-World Routine Laboratory Data (Worachart Lert-itthiporn)","sp":[{"n":"Worachart Lert-itthiporn","a":"Faculty of Medicine, Khon Kaen University","b":"Dr. Worachart Lert-itthiporn is a physician and lecturer at the Department of Biochemistry, Faculty of Medicine, Khon Kaen University, Thailand. His research interests include artificial intelligence in healthcare, clinical data analytics, genomics, and biomarker discovery. He has conducted research using real-world hospital data and machine learning to support disease identification, risk assessment, and clinical decision-making. His work focuses on translating routinely collected health data into practical and accessible digital health solutions, particularly for resource-constrained settings. He is also involved in medical education, bioinformatics training, and multidisciplinary research collaboration."},{"n":"Harsha Jayakody","a":"Ministry of Health Sri Lanka","b":"Dr. Harsha Jayakody is a Sri Lankan MBBS medical doctor and healthcare entrepreneur best known for founding MyDoctor and several other digital health startups. He has 15 years of clinical experience in tertiary-care hospitals and a track record of applying internet technologies and artificial intelligence (AI) to improve healthcare delivery. Academically, Dr. Jayakody holds an MD in Health Informatics, a Master’s in Health Informatics, and an MBA in…"},{"n":"Tamadur Almahdi","a":"UCL","b":"I have over 5 years of experience working at the intersection of health, technology, and social impact, where I served as an executive and partner building and scaling startups and initiatives impacting the lives of thousands across Africa and beyond. I have contributed to thousands of youth's empowerment collaborating with leaders and changemakers, and founding \"Women for Women LY\", a non-profit organization dedicated to empowering women and girls in…"},{"n":"Timothy Kintu","a":"Infectious Diseases Institute"},{"n":"Michael Tjalve","a":"Spreeha Foundation","b":"Michael Tjalve draws on 25 years of experience with AI, from applied science and research to tech sector AI product development and deep expertise in AI in humanitarian action. He previously served as Chief AI Architect at Microsoft Philanthropies and as Senior Advisor to the UN on AI in humanitarian action. In 2024, he established Humanitarian AI Advisory to help humanitarian organizations and stakeholders understand how to harness the potential of AI…"},{"n":"Halima Tus Sadia","a":"Spreeha Foundation","b":"Halima Tus Sadia is an organizational growth specialist serving as Head of Growth at Spreeha. She directs the organization’s positioning narrative, communications, local fundraising, and program development across its primary healthcare and community empowerment portfolios. Over her tenure at Spreeha, Halima has served as the key bridge between field-level health innovations and external stakeholders. She articulates Spreeha’s decentralized care…"},{"n":"Vijaya Palaniappan","a":"Newcastle University Medicine Malaysia","b":"Dr. Vijaya Palaniappan holds an MBBS degree and a Master’s in Health Informatics, with over 12 years of experience spanning clinical practice, public health, and non-clinical healthcare sectors. She has contributed to the development of white papers on medical device architectures and clinical trial methodologies, reflecting her engagement in translational and applied healthcare research. Her expertise lies in health informatics, particularly in…"},{"n":"Ephrem Biruk Gashaw","a":"HABTech Solutions","b":"Ephrem Biruk Gashaw is a public health professional with over fifteen years of experience strengthening health systems in Ethiopia. He currently serves as Deputy Project Director at Habtech Solutions, leading digital health and data analytics programs funded by the Gates Foundation, the Global Fund, and Save the Children. He holds a Master of Public Health from Addis Ababa University and a master's in data science and has authored fifteen scientific…"},{"n":"Evans Ongechi","a":"Partners for Health and Development in Africa (PHDA)","b":"Evans Nyaora Ongechi is a seasoned finance officer and organizational leader with extensive experience in donor-funded project management, compliance, and institutional development. He currently serves as Finance Officer at PHDA, where he oversees financial stewardship, accountability frameworks, and sustainable resource mobilization. Evans holds a Maters Degree Business Administration from the University of the People and Bachelor's degree in Business…"},{"n":"Peter Otieno Owuor","a":"Cure Cervical Cancer","b":"Peter Otieno Owuor is a Data Lead with over six years of experience advancing digital health systems, data management, analytics, and data-driven decision-making in Kenya. At CureCervical Cancer Kenya, he leads the design and implementation of digital health solutions supporting end-to-end community-based HPV screening, including client registration, sample collection and tracking, laboratory processing, treatment, referrals, and follow-up using…"},{"n":"Arti Sahu","a":"Dimagi","b":"Arti Sahu is a Senior Manager at Dimagi with 11 years of experience in digital health, data systems, and technology for social impact. She equips new partner organizations across Africa, Europe, and Asia to harness CommCare for programs spanning health, agriculture, crisis response, and humanitarian work, helping them build the data collection ecosystems that result in stronger outcomes. She brings hands-on experience in Tableau, SQL, and Power BI, and…"},{"n":"Christine Hortinela","a":"engageSPARK, Inc","b":"Christine Hortinela is passionate about helping customers reach their goals and ensuring they can use the engageSPARK platform with confidence. Since joining engageSPARK in 2017, Christine has led customer onboarding, one-on-one and group product trainings, account management, and technical support for a wide range of clients, including NGOs, universities, and businesses. She works closely with organizations to understand their objectives, identify…"},{"n":"Dr Bala Nair","a":"Prevents-MD","b":"Dr Bala Nair is the founder and CEO of PreventS-MD, a health technology initiative focused on personalised prevention of stroke, cardiovascular disease and related chronic conditions. He is also a public health researcher and Research Manager at the National Institute for Stroke and Applied Neurosciences, Auckland University of Technology. With a background in medicine, public health and health policy, Bala has worked across research, implementation,…"},{"n":"Bezawit Mesfin Hunegnaw","a":"JSI","b":"Bezawit M. Hunegnaw is the Deputy Projects Director at JSI Ethiopia, with over 15 years of experience in clinical and public health practice, programs leadership and research in RMNCH. She comes with expertise in strategic leadership, health systems strengthening and evidence-based practice. At JSI, she leads the design and implementation of interventions that aim to strengthen service delivery and quality of care in primary health care while also…"},{"n":"Rajeev Dhakad","a":"Khushi Baby","b":"Dr. Rajeev Singh Dhakad 13+ Years of Experience, As State Program Manager in Public Health, Digital Health & Health System Strengthening Ph.D. from The IIHMR University, Jaipur, Rajasthan Master of Public Health (MPH) from Golbal Open University Master of Arts in Sociology from Dr Bhimrao Ambedkar University Key Expertise Digital Health Systems & Policy Implementation • Proven experience in designing and implementing large-scale digital health…"},{"n":"Kartik Sharma","a":"KHUSHIBABY","b":"Currently working as Lead - Digital Health Strategy (Integration) 7+ Years of Experience in Public Health & Digital Health and Health insurance Qualification - Bachelor of Dental Surgery from Jodhpur Dental College and General hospital , MBA in Hospital and Healthcare administration (Specialization Healthcare) from Indian Institute of Health Management Research, Jaipur Key Expertise Digital Health Strategy Lead digital health strategy at Khushi Baby,…"},{"n":"Purushotam Soni","a":"Department of Medical Health and Family Welfare - Government of Rajasthan","b":"Dr Purushotam Soni, MBBS, MD (TB & Respiratory Diseases), is the State TB Officer (STO), Rajasthan. He is committed to strengthening TB care through innovation, integration and community participation. His contributions to the TB Mukt Gram Panchayat initiative were honoured by the Government of India on World TB Day, 24 March 2025. He was also recognised by the Chief Minister of Rajasthan on 7…"},{"n":"Olasoji Fasogbon","a":"African Field Epidemiology Network (AFENET)","b":"Olasoji Fasogbon is a distinguished Global Health specialist and M&E/Data Manager at the African Field Epidemiology Network (AFENET) Nigeria Country Office, bringing nearly 20 years of expertise to the forefront of health systems strengthening and data-driven governance. A recognized authority in Digital Health, Knowledge Management and emerging M&E trends, Olasoji specializes in transforming complex analytics into high-impact policy frameworks. His…"},{"n":"Prasanjith Chanaka Dissanayake","a":"Ministry of Health, Sri Lanka","b":"I am a medical doctor in Health Informatics working at the Ministry of Health, Sri Lanka. My work centres on digital health systems, including information systems, electronic medical records, with a focus on interoperability, digital public infrastructure, and secure system design in resource-constrained settings. I have postgraduate MSc training in Biomedical Informatics and Data Science and broader interests in artificial intelligence, research, and…"},{"n":"Kaushalya Wijesekara","a":"kaushalyawijesekara91@gmail.com"},{"n":"Olayinka Oloyede","a":"Chemonics International (GHSC-PSM)","b":"Olayinka Gbenga Oloyede is a distinguished public health professional and data scientist with a specialized focus on health systems strengthening, supply chain management, and advanced analytics. Currently serving as a Monitoring and Evaluation (M&E) Manager within the international development sector, Olayinka leverages expertise in Power BI, SQL, Python, and predictive modeling to optimize health commodity logistics and public health surveillance. A…"},{"n":"Carlos Albrecht","a":"UNICEF","b":"My name is Carlos Albrecht Lezama, and I work as a Health & Nutrition Officer. My professional background is being a family medicine doctor, with experience on community health, nutrition, and strengthening the capacities of frontline health workers. I am particularly interested in leveraging digital learning and innovative approaches to empower communities and improve health outcomes. I look forward to exchanging experiences and learning from fellow…"}]},{"id":"s11","t":"Tea Break","d":"2026-12-02","s":"15:30","e":"16:00","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s255","t":"Discovery Stage: Pragmatic Pathways to DPI-H in Low-Maturity Ecosystems","d":"2026-12-02","s":"16:30","e":"17:00","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"","sp":[{"n":"Dilipkumar Hensman","a":"","b":""}]},{"id":"s256","t":"Discovery Stage: From AI Promise to Health for All: Building Regional Capacity for Responsible AI in South-East Asia","d":"2026-12-04","s":"13:00","e":"13:30","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Exploring WHO SEARO - University of Colombo efforts to build responsible AI capacity for precision medicine, primary healthcare and universal health coverage.\n\nHosted by the WHO South-East Asia Regional Office and the University of Colombo.","sp":[{"n":"Vajira Dissanayake","a":"University of Colombo","b":"Professor Vajira Dissanayake, University of Colombo, leads WHO SEARO collaboration on AI capacity-building, digital health and precision medicine."}]},{"id":"s257","t":"Discovery Stage: When People Feel Heard, They Talk: Designing Around User Intent in Indonesia","d":"2026-12-04","s":"10:10","e":"10:40","tags":["Discovery Stage","In-person","Sponsored Session"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"When Nivi ran health campaigns in Indonesia, we built them around one idea: start with what people actually want to know. This talk walks through how we designed those WhatsApp chatbot journeys around user intent, using the Fogg Behavior Model and a seamless entry point to meet people where they already are. When users feel heard, they talk; and when they talk, we design the conversation around them.","sp":[{"n":"Carissa Cornelia Chundiawan","a":"Nivi","b":""}]},{"id":"s258","t":"Integrating an AI-powered Clinical Interaction Platform in a resource-constrained setting: patients’ perceptions and concerns","d":"2026-12-03","s":"22:20","e":"22:25","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"This talk presents a study of Hami®, an AI-powered clinical interaction platform adapted for outpatient clinics in Karachi, Pakistan, with voice and text modes in Urdu and English, a low-bandwidth option and specialty personas built around the local disease profile. A survey of 8,487 patients across four hospitals shows how age, education and public or private hospital settings shaped trust in AI-assisted care, and finds high acceptance when tools are adapted to local context.","sp":[{"n":"Marium Hasan Rizvi","a":"Boston Healthcare Pvt. Limited","b":"Mariam Hasan Rizvi is a researcher and public health specialist based in Karachi, Pakistan, with a strong focus on digital health evaluation, implementation research, and health equity in low- and middle-income countries (LMICs). She currently serves as Research Lead at Boston Health AI, where she designs and leads multi-center studies assessing the quality, usability, and acceptability of AI-powered clinical tools. These studies include comparative evaluations of multiple large language models and a hospital-based assessment of the AI-Powered Clinical Interaction Platform, involving patients' and clinicians' experiences. Her work bridges quantitative and qualitative methods to identify factors shaping patient and provider perceptions, integration barriers, and scalable implementation strategies."}]},{"id":"s242","t":"Discovery Stage: The Missing Decision Layer in Health AI: Introducing the Deployable AI Index","d":"2026-12-02","s":"16:00","e":"16:30","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"This session introduces the Deployable AI Index (DAI) as a structured, evidence-informed approach to assessing AI deployment readiness in health systems. It explores how integrating technical readiness, safety, financial sustainability, and implementation complexity can support transparent, context-specific decisions on AI adoption, procurement, and scale-up, particularly in low- and middle-income countries.\n\nHosted by Jhpiego and the WHO South-East Asia Regional Office.","sp":[]},{"id":"s205","t":"Gates Foundation Sponsored Breakout: From Framework to Field: Evaluating AI Hands-On","d":"2026-12-02","s":"16:00","e":"17:00","tags":["Sponsored Breakout","In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s14","t":"Individual Presentations: Building Digital Health Capacity: Skills, Institutions and Sustainable Adoption","d":"2026-12-02","s":"16:00","e":"17:00","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on building the skills, institutions and practices that help digital health last, from university training programmes and workforce development to AI ethics governance and security in open-source communities.\n\nPresentations in this session:\n7637 - From lessons learned to new opportunities: Outcomes of the inter-university diploma \"Innovation & Health practices\" and open call for new training projects (Maxime Collin, Lea Matel)\n7733 - BEYOND THE DASHBOARD: BUILDING WORKFORCE CAPACITY FOR SUSTAINABLE DIGITAL HEALTH ADOPTION (Vira Horovenko, Tetiana Klymenko)\n8292 - From Global AI Governance Principles to Local Practice: Operationalising an AI Ethics and Governance Capacity-Building Model for Non-Technical Public Sector and Development Professionals in Nigeria (Liss Theodora Yori)\n8527 - Building Ethiopia’s digital health workforce through a university-health system pre-service training pipeline (Biniam Taye)\n7786 - Embedding Security Into Open Source Culture: Early Lessons from the OpenMRS Community (Beryl Kanali)","sp":[{"n":"Maxime Collin","a":"Fondation Pierre Fabre","b":"Digital health project manager at Fondation Pierre Fabre (France), Maxime specializes in the integration of digital health solutions to improve patient care and access, particularly in vulnerable communities. His background as a pharmacist provides him with a strong medical foundation for collaborating seamlessly with healthcare professionals, technology providers, academics, civil society organizations and policymakers to advance the role of…"},{"n":"Lea Matel","a":"Fondation Pierre Fabre","b":"In case Maxime Collin could not present in Bangkok."},{"n":"Vira Horovenko","a":"MSH (Ukraine USG-funded project)","b":"Vera Horovenko is a Senior Technical Advisor for Supply Chain with the U.S. Government-funded SAFEMed Activity implemented by Management Sciences for Health (MSH). She has more than 15 years of experience in pharmaceutical supply chain management, public health, and health systems strengthening. Her work focuses on strengthening national systems for the procurement, forecasting, warehousing, distribution, and pharmaceutical management of medicines and…"},{"n":"Tetiana Klymenko","a":"MSH (Ukraine USG-funded project)","b":"Seasoned MEARL specialist with over 15 years of experience in early warning systems, risk mapping, and data-driven management for international projects. She has successfully designed and operationalized comprehensive MEAL frameworks, enhancing accountability and decision-making in complex environments. With expertise in capacity building, data analysis, and media monitoring, she has led initiatives for high-stakes projects, including crisis response…"},{"n":"Liss Theodora Yori","a":"Africa Hub For Innovation and Development (AHFID)","b":"Liss Yori is a development professional, lawyer and Growth and Engagement Specialist at Africa Hub for Innovation and Development (AHFID). She holds a Bachelor of Laws (LL.B.) and a Master's degree in Information Communication Technology Law. She has over three years of experience supporting development programmes across COVID-19 response, HIV and governance and government technical assistance initiatives. In her current role, she supports business…"},{"n":"Biniam Taye","a":"Ministry of Health, Ethiopia","b":"Dr. Biniam Kefiyalew Taye is a Health Information Systems researcher at the Ethiopian Ministry of Health. He holds a PhD in Public Health Informatics and an MSc in Biostatistics and Health Informatics. His work focuses on routine health information systems, digital health, data quality, health data analytics, and evidence-informed decision-making. He applies mixed-methods and advanced quantitative approaches, including causal inference, to examine how…"},{"n":"Beryl Kanali","a":"OpenMRS","b":"Beryl Kanali is the Open Source Community Coordinator at OpenMRS, the world's largest open-source electronic medical records system, where she has spent the past two years building and sustaining a global community of over 5000 members, 500 active contributors and implementing partners across more than 80 countries. Beryl holds a Bachelor of Science in Mathematics and Computer Science and has a background in open-source community management across the…"}]},{"id":"s248","theme":"","desc":"","sp":[],"t":"Transform Health Spotlight Session","d":"2026-12-02","s":"16:00","e":"17:00","tags":["Spotlight Session","Hybrid Livestream","Sponsored Session"],"fmt":"Spotlight Session","mode":"Hybrid Livestream"},{"id":"s13","t":"What Does It Take to Build Interoperable Health Systems? Lessons from India, Brazil, Ghana, and Rwanda","d":"2026-12-02","s":"16:00","e":"17:00","tags":["Pre-formed Panel","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Pre-formed Panel","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"Interoperability underpins national digital health transformation but is one of the hardest capabilities to scale: its benefits are spread out and slow to appear, and its costs are high and poorly understood. Drawing on the Digital Health Exemplars study led by Johns Hopkins University and the University of Gondar, this panel compares how India, Brazil, Ghana and Rwanda have built their interoperability ecosystems at different levels of digital maturity. Speakers cover architecture choices, governance and legislation, financing and market dynamics. Participants will come away with a phased maturity framework for building a national health information exchange and a clearer sense of which enablers matter most in different country contexts.","sp":[{"n":"Smisha Agarwal","a":"Center for Global Digital Health Innovation, Johns Hopkins Bloomberg School of Public Health","b":"Dr.Smisha Agarwal, PhD, MPH, MBA, BDS is the Director of the Center for Global Digital Health Innovation and Associate Professor in the Department of International Health at the Johns Hopkins Bloomberg School of Public Health. She brings expertise in advancing primary health care through strengthening community health systems and leveraging innovative technological solutions including digital devices. A part of her research has focused on using…"},{"n":"Suruchi Gupta","a":"Center for Global Digital Health Innovation, Johns Hopkins Bloomberg School of Public Health","b":"Suruchi Gupta, MD, MPH, is faculty at the Center for Global Digital Health Innovation, Johns Hopkins University and uses mixed-methods research to advance the quality of primary care in lower-middle-income-countries. She examines health policies and evaluates digital health interventions to study the role of technology in strengthening health systems. She led the India stream within the Digital Health Exemplars study that underpins this panel,…"}]},{"id":"s15","t":"Orchestrating High-Volume Health Financing Analytics in Indonesia via DHIS2 and BAO Analytics Platform","d":"2026-12-02","s":"17:00","e":"17:05","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"Indonesia's Health Financing Information System produces the National Health Accounts from social security and Ministry data, a process that used to depend on manual CSV extractions taking more than a month each year. This talk describes how the Ministry of Health replaced that workflow with an automated pipeline, using DHIS2 as the orchestration layer and the BAO Analytics Platform with Apache Superset for visualisation, pulling data directly from national APIs. The speaker covers the pipeline design, how high data volumes were handled, and the effect on how quickly financing data reaches policymakers. The approach relies on open-source tools and can be adapted by other countries with fragmented, high-volume financing data.","sp":[{"n":"Ratih Syabrina","a":"Castellum Digital Indonesia","b":"Health Information Systems Specialist with 9+ years of experience supporting the design, implementation, interoperability, and governance of national and subnational health information systems across Indonesia. Experienced in collaborating with the Ministry of Health, WHO, FHI360, FAO, UNDP, University of Oslo, CHISU USAID,Project Hope, UNDP, provincial governments, and district health offices to strengthen disease surveillance, health information…"}]},{"id":"s16","t":"Beyond the Sketch Map: Using GIS Analysis to Strengthen Immunization Microplanning in Indonesia","d":"2026-12-02","s":"17:05","e":"17:10","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Indonesia's zero-dose population grew from 571,000 children in 2022 to 748,000 in 2024, partly because vaccination sites were placed without spatial analysis. This talk describes how CHAI Indonesia worked with the Ministry of Health and district health offices in 12 districts across Java to replace hand-drawn sketch maps in immunisation microplanning with GIS-based accessibility analysis. Field teams used KoBoToolbox on standard smartphones to map facilities, and QGIS to identify communities far from services. The speaker shares how the analysis changed microplanning decisions and what other programmes need to adopt this low-cost, open-source approach.","sp":[{"n":"Stella Benita","a":"CHAI Indonesia","b":"With a medical doctor credential and 6+ years of experience in global health, I currently serve as a Senior Program Officer in the Prevention & Immunization Unit at Clinton Health Access Initiative (CHAI). My role focuses on advancing immunization equity through the ACTION project in Indonesia, where I lead cross-functional collaboration, manage program implementation and build strategic partnerships with government agencies and partners. My expertise…"}]},{"id":"s17","t":"Interdisciplinary teaching experience of technology application and digital health transformation for undergraduate medical students","d":"2026-12-02","s":"17:10","e":"17:15","tags":["Lightning Talk","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Lightning Talk","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"The Faculty of Medicine and Health at Institut Teknologi Sepuluh Nopember in Indonesia has introduced a course on technology and digital transformation in medicine for undergraduate medical students. The course is co-taught by lecturers from medicine and medical technology and pairs medical students with medical-technology students on joint innovation projects. Its eight topics include digital health concepts, clinical data ethics, learning health systems, AI in healthcare and design thinking. This talk shares how the course was built, what worked and what the faculty would change, giving other medical schools a model for adding digital health to undergraduate training.","sp":[{"n":"Alfian Nurfaizi","a":"Institut Teknologi Sepuluh Nopember (ITS)","b":"Alfian Nurfaizi is a medical doctor, researcher, and digital health lecturer at the Faculty of Medicine and Health, Institut Teknologi Sepuluh Nopember (ITS), Indonesia. He earned his medical degree from Universitas Airlangga and a Master of Digital Health and Data Science from the University of Sydney as an Australia Awards Scholar, and is a Certified Health Informatician Australasia (CHIA) through the Australasian Institute of Digital Health (AIDH).…"}]},{"id":"s18","t":"Building Interoperable Clinical Decision Support Systems within Digital Public Infrastructure: A Roadmap for Scalable Healthcare","d":"2026-12-02","s":"17:15","e":"17:20","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"Many clinical decision support systems sit inside a single electronic health record and cannot be shared across facilities or care settings. This talk sets out how countries investing in digital public infrastructure for health can deliver clinical decision support as an interoperable, reusable service instead. The speaker presents a conceptual framework showing how standards such as HL7 FHIR and standardised clinical terminologies make this possible, and offers a roadmap for health systems that want decision support to scale nationally while staying secure and patient-centred.","sp":[{"n":"Jakir Hossain Bhuiyan Masud","a":"Health Informatics Bangladesh (HIBD)","b":"Dr. Jakir Hossain Bhuiyan Masud is a Biomedical Informatics Scientist with a PhD in Biomedical Informatics and more than 20 years of experience spanning digital health, biomedical informatics, public health, and artificial intelligence in healthcare. His research focuses on AI-enabled clinical decision support, precision medicine, EHRs, clinical natural language processing, and health data interoperability, including HL7 FHIR. Dr. Jakir serves as…"}]},{"id":"s249","theme":"","desc":"","sp":[],"t":"Transform Health Youth Networking Reception: Youth driving digital health transformation: Networking and learning event","d":"2026-12-02","s":"17:15","e":"18:30","tags":["Reception","Sponsored Session","In-person","Invite Only"],"fmt":"Reception","mode":"In-person"},{"id":"s206","t":"From Activation to Sustainability: A Multi-Pillar District Model for Sustained Adoption of India's National Digital Health Mission (ABDM)","d":"2026-12-02","s":"17:20","e":"17:25","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"India's Ayushman Bharat Digital Mission gives every citizen a digital health ID linked to records across facilities. In Bhopal, a national onboarding drive registered 621 private facilities, yet fewer than 14 kept using the system once field support ended. The Digital Health District pilot tested a three-part model to close this gap: digitising private facilities so the mission is part of clinical workflows, activating public facilities, and building district systems to keep adoption going. The presenters share results and explain why registration targets rarely translate into routine use, with lessons for any national digital health rollout.","sp":[{"n":"Himanshu Dhingra","a":"William J. Clinton Foundation (WJCF)","b":"Currently working as an Associate Director in the Digital Health team of William J. Clinton Foundation, Himanshu is leading the WJCF team working with National Health Authority (NHA) to drive adoption of Ayushman Bharat Digital Mission (ABDM) among healthcare professionals. Himanshu is a well-rounded professional with twelve years of experience across social sector advisory and business process automation.\n An MBA graduate from IIM Kozhikode, Himanshu…"},{"n":"Vibha Bhirud","a":"WJCF","b":"Vibha Bhirud is a digital health leader with over a decade of experience at the intersection of public systems, technology, and social impact. As Co-founder of Intelehealth, she helped scale telemedicine to five countries and 5.2M+ lives, and led the drafting of Kyrgyzstan's national Digital Health Policy. She now works at WJCF Digital Health, supporting India's National Health Authority on the Ayushman Bharat Digital Mission (ABDM). Vibha holds an…"},{"n":"Vishnu Vasudev","a":"WJCF","b":"Vishnu Vasudev is a Director at the Clinton Health Access Initiative (CHAI), where he has spent six years leading work across digital health, health financing, and new initiatives, progressing through roles including Deputy Director and Associate Director. Based in New Delhi, his work supports health systems strengthening in India. Before CHAI, he co-founded Ka Partners and served as Director of Programs at The Antara Foundation, and earlier held…"}]},{"id":"s22","t":"Appy Hour: Solution Demonstrations","d":"2026-12-02","s":"17:30","e":"19:30","tags":["Solution Demonstration","In-person","Sponsored Session"],"fmt":"Solution Demonstration","theme":"","mode":"In-person","desc":"An evening of live solution demonstrations. Presenters show working tools in action, including AI assistants and chatbots, surveillance and early-warning systems, interoperability platforms, campaign management tools and clinical decision support, and are available to answer questions one to one.\n\nSolution demonstrations in this session:\n7327 - What Inclusive GenAI Looks Like When the Audience Has No Internet (Kaiyan Yousaf)\n7337 - Making APIs Usable: Conversational Agents for Inclusive Digital Health Access (Haritha Reddy)\n7399 - Nia: AI Knowledge Assistant for the UNAIDS Global HIV Prevention Coalition (Armen Danielyan)\n7440 - Kobo AI Interviewer: Chat-based data collection for outbreak response (Salomé Garnier, Joshua Beretta)\n7542 - NkwaSafe: A Mobile First-Aid Educational Tool to Support Prehospital Care Gaps in Rural Ghana (Nana Yaa Asante)\n7675 - Adoption of an AI-enabled Digital Labour Monitoring Tool in Primary-Level Care: Evidence from Lagos, Nigeria (Samuel Atanda)\n7754 - An LLM-Powered Conversational Analytics Agent for Health Decision-Making: Natural-Language Querying, Visualization, and Anomaly-Based Data-Quality Assurance (Adane Mamuye, Mesoud Ahmed)\n7794 - From Climate Data to Early Warning: Demonstrating an Open-Source DHIS2 Climate Health Intelligence Ecosystem (Pamod Amarakoon, Ruvinda Jayawardena)\n7879 - Closing the Gap: An AI-Powered Blueprint for Next-Generation Pathogen Surveillance (Nok Suphavilai)\n8006 - Watch Madiro Implementer AI Complete Real Tasks, From Ticket to Deploy (Michaël Bontyes)\n8045 - AI-Powered Tumour Intelligent PACS for Cancer Care in Resource-Constrained Health Systems (Victor Ebhodaghe)\n8087 - AI-Powered Wireless Monitoring Across the 1000-Day Journey: Reducing Preventable Maternal and Newborn Deaths in Resource-Constrained Settings (Arun Agarwal)\n8129 - DPI-H in Action: Demonstrating the openIMIS Interoperability Sandbox for Integrated Digital Health Financing (Uwe Wahser, Sunil Parajuli, Maxime Ngoe)\n8134 - A dynamic data resource on antimicrobial resistance in Uganda for research and evidence-based decision-making (Muwonge Khalifan)\n8272 - Strengthening Specialist Dermatology Workforce Capacity Through a Multi-Country Digital Continuing Professional Development Ecosystem (Khine Pwint Nwe)\n8273 - One Codebase, Every Platform: Bringing FHIR-Native Digital Health Tooling to Kotlin Multiplatform (Fikri Milano)\n8322 - Plan, Enumerate, Identify, Vaccinate, and Pay: A Live Demonstration of CommCare for Campaigns (Anita Kruger, Jordan Lerner, Ismaïla Diene)\n8349 - Safi Analytics: An AI methodological and statistical mentor and analyst (Beth A. Tippett Barr)\n8434 - Solution Demonstration: Showcasing an AI-Enabled Digital Health Platform Integrated with Wearables for Continuous Physiological Monitoring and Real-Time Health Insights (Chiagozie Abiakam)\n8447 - Making Labour-Room Data Actionable at Scale: MaNTrA, Uttar Pradesh’s State-Owned Maternal and Newborn Platform (Bal Krishana Yadav, Girdhari Bora)\n8479 - Closing the Diagnostic Loop: Integrating Laboratory Systems into National Digital Health Workflows (Derek Treatman, Catherine Sieberhagen, Anthony Ndolo)\n8488 - From AI Signal to Resolved Care: Closing the Loop in Conversational Digital Health (George Orjih)\n8521 - One Client, One Record: Achieving Full Interoperability Between Jamii ni Afya, openIMIS and ZanEMR for Continuum of Care in Zanzibar (Isaya Mollel, Antony Khaemba)\n8555 - SpeedyMesh: A Sovereign, Open-Source Data Mesh and Data Spacefor Health Data Interoperability at Continental Scale in Africa and beyond (Hamza Zbidi, Kirstin Groß-Frie, Mirna Hussein, Simon Ndira, Julius Murke, Sean Schwager)\n8630 - Leveraging the Malawi Healthcare Information System (MaHIS) to Enhance Early Detection and Continuity of Care for Non-Communicable Diseases Through Digital Community Screening and Referrals — Solution Demo (Kondwani Munthali, Rajab Billy)\n8631 - Achieving Locally Hosted, Evidence-Based Clinical Decision Support within the Malawi Healthcare Information System (MaHIS): The Malawi Clinical Intelligence Service (MCIS) as Part of Malawi’s National Digital Public Infrastructure for Health (Brett Onions, Rajab Billy)\n8651 - TWIIN: An AI-Powered Digital Assistant for Health Information and Service Navigation (Maria Malakhova)\n8724 - The Global Virtual Reality (VR) Simulation Training Hub for Midwifery: Scaling Quality Care through Immersive Innovative Technologies (SAHIL KAPOOR, Alexander D'alessandro, Deepa Prasad)\n8739 - Bridging the health workforce gap through community health workers: Lessons from a structured capacity strengthening and continuous quality improvement approach in Indonesia (Taufiq Sitompul, Nisa Nurkhotami)\n8766 - Governing the use of AI - Regulations and Data (GUARD) (Suthan Kaveri, Claudia Lopes)","sp":[{"n":"Kaiyan Yousaf","a":"Viamo","b":"Kaiyan Yousaf is the Director of Strategic Partnerships at Viamo, where he leads key strategic partnerships and frontier AI programs for social impact across Africa and Asia. He has over 15 years of experience designing technology-enabled development programs with USAID, FCDO, United Nations agencies, governments, donors, and mobile network operators. Kaiyan conceived and led Noor, Pakistan’s first offline, voice-first Generative AI companion for…"},{"n":"Haritha Reddy","a":"BeeHyv Software Solutions Pvt Ltd","b":"Haritha is the CTO and the first non-founding employee of BeeHyv. She loves coding and even more coding! She is a guru in Java based technologies and has a good understanding of many other technology stacks as well. An expert learner, Haritha picks up technologies amazingly quickly, whether it be Machine Learning or Natural Language Processing or any other. She has been a part of several successful projects done at BeeHyv and has mentored many people.…"},{"n":"Armen Danielyan","a":"FHI 360","b":"Armen Danielyan is a technology leader and IT generalist with 25+ years of experience across startups, private and public sectors, and international development. He has been with FHI 360 since 2010 and currently serves as Director, Digital Development, where he leads several software development teams as well as the AI Lab and AI initiatives from strategy through execution. His background spans nearly every area of IT, including systems engineering,…"},{"n":"Salomé Garnier","a":"Kobo","b":"Salomé Garnier is a Research & Data Specialist at Kobo. With a Master's in Public Health, she brings advanced expertise in mixed-methods public health research, survey design, and digital data collection in complex settings. She has led end-to-end research projects across multiple regions, with a particular focus on social epidemiology and behavioral science applied to health, including vaccine hesitancy and reproductive health. At Kobo, she supports…"},{"n":"Joshua Beretta","a":"Kobo","b":"Joshua Beretta is the Humanitarian Project Coordinator at Kobo, where he supports the research and development of AI-enhanced data collection tools as a Solutions Architect. He specializes in humanitarian technology and information management in low-resource settings, with field deployment experience in emergency response and extensive work supporting humanitarian organizations in survey design workflows."},{"n":"Nana Yaa Asante","a":"NkwaSafe Innovations","b":"Nana Yaa Asante is a Master of Biomedical Sciences graduate from Geisinger College of Health Sciences with experience in clinical research, quality improvement, and global health across the United States and Ghana. Her interests lie at the intersection of digital health, emergency preparedness, and health systems strengthening, with a focus on developing equitable, community centered solutions that improve access to healthcare and lifesaving health…"},{"n":"Samuel Atanda","a":"Health Strategy and Delivery Foundation","b":"Samuel Atanda is a Senior Information Technology Specialist at HSDF. As the IT department manager, he has expertise in IT risk management, service delivery, governance, infrastructure security, project management, strategy development, budget planning, vendor management, technical support, and digital transformation. With 14 years of experience, Samuel has managed numerous transformation projects across diverse sectors, including Real Estate, ICT,…"},{"n":"Adane Mamuye","a":"HABTech Solutions","b":"Dr. Adane Letta Mamuye is a computer scientist and AI researcher with a PhD in Science and Technology from the University of Camerino, Italy. He serves as General Manager and Gates Foundation Project Director at HABTech Solutions and as Assistant Professor at Addis Ababa University's Schools of IT and Engineering, where he teaches and supervises graduate research in artificial intelligence. His work spans machine learning, computer vision,…"},{"n":"Mesoud Ahmed","a":"Ministry of Health, Ethiopia","b":"Mr. Mesoud Mohammed Ahmed is the lead for the statistics and information team of the strategic affairs executive office at MOH-Ethiopia. he served as the assistant director of the previous Policy, Plan, Monitoring, and Evaluation Directorate (PPMED) for over five years and the lead for M&E team, he also served as Digitization Section Chief of Emergency Operating Center at Ethiopian Health Institute for COVID-19 response. He previously served for more…"},{"n":"Pamod Amarakoon","a":"HISP Sri Lanka","b":"Pamod Madusanka Amarakoon is a medical doctor, health informatics specialist, and digital public goods practitioner from Sri Lanka. He is currently Senior Implementer and Lead at HISP Sri Lanka and Project Coordinator of Digital Public Goods at the HISP Centre, University of Oslo, where he works across DHIS2 implementation, digital public infrastructure, and country-level digital health strengthening. He is also a PhD Research Fellow at the University…"},{"n":"Ruvinda Jayawardena","a":"HISP Sri Lanka","b":"Dr. Ruvinda Jayawardene is a medical doctor and Health Informatics specialist with expertise in digital health, health information systems, interoperability, and digital public infrastructure. He is a PhD candidate at the HISP Centre, University of Oslo, where he contributes to the design, implementation, and evaluation of digital health solutions in collaboration with ministries of health and international partners. He holds an MBBS from the…"},{"n":"Katherine Morris","a":"Association of Public Health Laboratories","b":"Katherine Morris is a Senior Specialist at the Association of Public Health Laboratories (APHL) in Global Health, Informatics. Katherine has over 10 years of experience in public health laboratories, specializing in public health informatics. She has a master of public health (MPH) in Epidemiology from George Washington University in Washington, DC USA and a Bachelor of Science (BS) in Biology."},{"n":"Matthew McCarroll","a":"Association of Public Health Laboratories","b":"Matthew McCarroll is a public health professional with expertise in laboratory systems, informatics, infectious disease preparedness, and data interoperability. As Principal Specialist for Global Health Informatics at the Association of Public Health Laboratories (APHL), he leads multinational initiatives that strengthen laboratory information systems and public health data exchange across Africa, Latin America, Eastern Europe and Central Asia,…"},{"n":"Nok Suphavilai","a":"ASTRID Genomics","b":"Dr. Chayaporn (Nok) Suphavilai is the CEO and Co-founder of ASTRID Genomics. She holds a Ph.D. in Computer Science from NUS, specializing in AI for precision medicine. Recognized as one of the \"100 Singapore Women in Tech\" (2023), Dr. Nok bridges the gap between research and clinical care. She spearheads a collaboration with Singapore General Hospital to deploy advanced microbial genomic and AI workflows into diagnostic labs, accelerating life-saving…"},{"n":"Michaël Bontyes","a":"Madiro","b":"Michaël Bontyes is Director of Programs and Digital Health at Madiro, where he leads teams building reusable, open-source health systems that ministries and NGOs own and run. Their work is in use in multiple countries with partners including Doctors Without Borders (MSF), the International Committee of the Red Cross (ICRC) and the Ministries of Health of Burundi and Madagascar. Over 15 years in engineering, innovation and global health, he has seen the…"},{"n":"Victor Ebhodaghe","a":"CARETRACE Inc","b":"I am on a mission to build the digital infrastructure that ensures cancer patients across Africa, especially those in underserved and resource-constrained communities, have access to timely, high-quality, and affordable cancer care. Through innovation and strategic partnerships, I am working to bridge gaps in oncology services by improving access to medical imaging, multidisciplinary care, and AI-powered clinical decision support. With over four years…"},{"n":"Arun Agarwal","a":"Janitri Innovations Private Limited","b":"Arun Agarwal is the Founder and CEO of Janitri Innovations, a medical technology company building AI-powered wireless monitoring solutions for maternal and newborn health. He holds an M.Tech in Biomedical Engineering from VIT and has spent over 10 years translating clinical research into deployable products across India and 4+ countries. Under his leadership, Janitri has grown from a prototype to a full platform deployed across 1,000+ hospitals,…"},{"n":"Uwe Wahser","a":"openIMIS Initiative","b":"Uwe Wahser is an experienced medical informatics and digital health expert with more than 30 years of international experience in health information systems, business intelligence, and digital transformation. He currently serves as an ICT Expert with Deutsche Gesellschaft für Internationale Zusammenarbeit (GIZ), where he coordinates the global development of openIMIS, an open-source health insurance management platform that supports social health…"},{"n":"Sunil Parajuli","a":"Tinkertech"},{"n":"Maxime Ngoe","a":"Y-Note"},{"n":"Muwonge Khalifan","a":"Infectious Diseases Institute / African Center Of Excellence Uganda","b":"I am a Software Engineer and data professional based in Uganda, with a background in Computer Science from Makerere University. I have experience building digital platforms across health, agriculture, education technology, labour, and interactive mobile games. My current focus is on creating technology for public health impact, particularly through healthcare data systems, antimicrobial resistance, multilingual health technologies, and scalable web and…"},{"n":"Khine Pwint Nwe","a":"Z-waka","b":"Dr. Khine Pwint Nwe is a physician, digital health entrepreneur, and Founder and CEO of Z-waka, a Singapore-headquartered digital health platform working across Southeast Asia to strengthen healthcare professional education and health workforce capacity. With over 12 years of experience spanning clinical care, public health, health informatics, and digital health innovation, she has led the design and implementation of scalable CME/CPD-accredited…"},{"n":"Fikri Milano","a":"Ona","b":"Fikri Milano is a Software Engineer at Ona and a maintainer of the Android FHIR SDK, now the Open Health Stack Software Foundation, since 2021. He joined the project through Google Summer of Code 2021 and has worked on it full time ever since, contributing to the open-source FHIR tooling behind digital health applications worldwide, and now to the effort bringing the OHS FHIR Foundation Libraries to Kotlin Multiplatform. His work has been recognized…"},{"n":"Anita Kruger","a":"Dimagi","b":"Anita Kruger is Senior Director of Strategic Partnerships at Dimagi, where she leads partnerships and growth initiatives across Africa. With more than a decade of experience working across global health, digital development and African markets, she works closely with governments, donors, multilaterals and implementing partners to design and scale digital solutions for public health systems. Her work has focused particularly on digital health,…"},{"n":"Jordan Lerner","a":"Dimagi","b":"Jordan Lerner is Director of Delivery for Dimagi's Global Solutions division, where he works with governments and NGOs across sub-Saharan Africa to design and implement digital health programmes. Since joining Dimagi in 2016, Jordan has supported deployments in more than 40 countries, spanning immunisation, HIV, TB, pandemic response and health worker payments. During COVID-19 he was strategic lead for Dimagi's response team, working with governments…"},{"n":"Ismaïla Diene","a":"Dimagi","b":"Ismaïla Diène is the Managing Director of the Solutions Division at Dimagi, focused on driving digital transformation in health systems across the world. With over 15 years of experience in software engineering, health information systems, and strategic partnerships, Ismaïla has played a pivotal role in implementing scalable and sustainable digital health solutions in countries like Burkina Faso, Ethiopia or Madagascar. His leadership has accelerated…"},{"n":"Beth A. Tippett Barr","a":"Nyanja Health Research Institute","b":"Dr. Beth Tippett Barr (DrPH, MSc Epidemiology) is an epidemiologist with over 25 years of program and research experience in Southern and Eastern Africa, including 14 years as a senior research scientist with the U.S. Centers for Disease Control and Prevention across Malawi, Zimbabwe, Kenya, and South Sudan. In 2022, Dr. Tippett Barr returned to her home country of Malawi and established the Nyanja Health Research Institute, with a dual mandate to…"},{"n":"Chiagozie Abiakam","a":"mDoc Healthcare","b":"BPHARM, MSc.HS, PMP, MPH in View Manager, Women’s Wellness, mDoc Health Chiagozie Abiakam is a clinical pharmacist and technical program manager with over 12 years of experience in clinical pharmacy and healthcare project management. She leverages her expertise in behavioural science, data analysis, and AI technology to co-design and implement innovative solutions that enhance maternal health outcomes and address social determinants of health. As…"},{"n":"Bal Krishana Yadav","a":"Tattva Foundation","b":"Bal Krishna Yadav is a Digital Health and ICT4D strategist with almost two decades of experience driving large-scale digital transformations across India’s public healthcare system. He has led the statewide rollout of more than ten mission-critical platforms across Uttar Pradesh, Assam, and Nagaland, engineering resilient solutions for low-resource and last-mile communities. Focused on frontline worker empowerment and systemic scale, his initiatives…"},{"n":"Girdhari Bora","a":"Tattva Foundation","b":"Girdhari Bora is an ICT4D expert with 20 years of experience driving digital transformation and action research in rural communities. Currently the Chief Innovation Officer at Tattva Foundation, he has directly led the ideation, design, and development of digital solutions that enable over 1 million users, driving scalable impact for a population exceeding 240 million. A recognized thought leader in digital health, his work encompasses strategic…"},{"n":"Aleksa Krolls","a":"OpenFn","b":"Aleksa Krolls is the Chief Customer Officer and Co-Founder of OpenFn, the leading Digital Public Good (DPG) for workflow automation. She oversees services, adoption, and digital capacity-building initiatives for OpenFn’s NGO and government partners. Day-to-day, Aleksa helps partners design and implement localised, standards-based automation solutions that enable data exchange and interoperability for health and humanitarian operations. Prior to OpenFn,…"},{"n":"Anthony Ndolo","a":"Medx Intl","b":"Anthony Ndolo is the Chief Commercial Officer at MedX, a health-technology company building the digital infrastructure that connects medical devices, laboratories, and national health systems into reliable, interoperable networks. He leads commercial strategy, partnerships, and market expansion. Trained in software engineering, Anthony pairs commercial strategy with real technical grounding, translating fluently between what the technology can do and…"},{"n":"George Orjih","a":"mDoc Healthcare","b":"Dr. George Ikenna Orjih is a Nigerian medical doctor, digital health professional, and surgeon in training with experience spanning frontline clinical care, telemedicine, and AI-enabled healthcare delivery. He currently serves as Senior Clinical Associate at mDoc, where he supports the safety and quality of Kem, an AI-powered virtual health coach, through clinical review, risk assessment, and escalation design. His work focuses on digital chronic…"},{"n":"Abbas Wandella","a":"D-tree","b":"Abbas Wandella is a Senior Digital Health and Health Informatics Specialist with over a decade of experience leading national and regional digital health initiatives across Sub-Saharan Africa. He specializes in advancing interoperable digital health ecosystems, strengthening data governance, and enabling the use of AI-ready data to support evidence-based decision-making and equitable service delivery. He has advised governments and development partners…"},{"n":"Antony Khaemba","a":"Medic","b":"Antony Khaemba is a Community Manager at Medic, where he leads efforts to establish and nurture strategic partnerships with Community Health Toolkit (CHT) technical implementers. His work focuses on empowering partners and open source contributors to scale CHT implementations, increase impact, and drive innovation within the digital health ecosystem. Antony holds a Bachelor of Science degree in Nursing and he is currently pursuing a Masters in Health…"},{"n":"Hamza Zbidi","a":"Speedykom GmbH","b":"Hamza Zbidi works at Speedykom GmbH (Erlangen, Germany), the creator of SpeedyMesh, an open-source data mesh ecosystem for sovereign, standards-based health data sharing. He contributes to the design and delivery of SpeedyMesh across African and cross-border digital health programmes, including the African Union Digital One Health Platform (AU-DOHP), the IGAD Regional Pandemic Analytics platform (RePan), and the Cameroon One Health Information System…"},{"n":"Kirstin Groß-Frie","a":"GIZ"},{"n":"Mirna Hussein","a":"GIZ","b":"Mirna Hussein, the technical advisor at One Health Data Alliance Africa (OHDAA) project at GIZ, based in Germany. OHDAA has supported and managed the implementation of SpeedyMesh across African and cross-border digital health programmes, including the African Union Digital One Health Platform (AU-DOHP), and the Cameroon One Health Information System (COHIS), and now Africa CDC."},{"n":"Simon Ndira","a":"Africa CDC"},{"n":"Julius Murke","a":"GIZ Cameroon"},{"n":"Sean Schwager","a":"Speedykom Group","b":"- Sean Schwager is Head of Data and AI Services at Speedykom Group and has worked at the intersection of data, AI and international development since 2018, with a strong focus on applied machine learning for public-sector decision support, health data systems and Earth Observation. He leads the data-science workstream for Vector Space, an ESA-backed malaria forecasting initiative combining satellite, climate and surveillance data for early warning, and…"},{"n":"Justin Manda","a":"Luke International Malawi","b":"Justin Manda is a Health Information Systems Technical Manager and Digital Health Specialist with over 10 years of experience leading the design, development, and implementation of health information systems across Malawi. Currently serving at Luke International, he has led the technical strategy behind the Malawi Healthcare Information System (MaHIS), now a national digital health platform, and secured donor funding for its NCD and Electronic…"},{"n":"Kondwani Munthali","a":"University of Malawi","b":"Dr. Kondwani Godwin Munthali is a Lecturer and Deputy Head in the Department of Computer Science at Chancellor College, University of Malawi, where he also coordinates the MSc in Informatics programme. He serves as Head of the Computing Department and Project Lead for the Integrated Community Health Information System (iCHIS), a digital platform now deployed in 15 districts across Malawi, training and supporting over 3,700 Health Surveillance…"},{"n":"Rajab Billy","a":"Luke International Malawi","b":"Rajab Billy is a Senior Project – Software Products Management Officer at Luke International, based in Lilongwe, Malawi, with expertise in software project management and Agile/Scrum development. He oversees the full lifecycle of digital health products—from requirements gathering through deployment and maintenance—supporting national health information systems in Malawi. Rajab also contributes to Malawi's Digital Health Division (DHD) within the…"},{"n":"Brett Onions","a":"Luke International","b":"Brett Larry Lee Onions is a full-stack software developer based in Malawi, specializing in digital health solutions and system interoperability. He is a core developer for MaHIS, a comprehensive health information system that supports critical clinical programs across the country, and closely working with the Malawi Ministry of Health and Sanitation, Luke International and other development partners in attaining the nation's digital health…"},{"n":"Maria Malakhova","a":"Alliance for Public Health","b":"Maria Malakhova is a public health and digital health specialist at Alliance for Public Health, working at the intersection of health innovation, implementation, and service delivery. Her work focuses on developing and scaling digital approaches to improve access to HIV prevention, harm reduction, mental health, and other health and social services for underserved populations. She is involved in the implementation of AI-enabled digital health…"},{"n":"SAHIL KAPOOR","a":"United Nations Population Fund (UNFPA)","b":"Sahil leads innovation work and is appointed as Technology and Innovation Specialist at UNFPA India Country Office since 2021. He is also an active member of Inter-Divisional Working Group of HQ for Innovations and has been successful in bridging financial partnerships with private and governments through innovation modelling for challenges aligned to UNFPA mandate. He holds a degree in management and finance from IIT Delhi, an engineer by profession…"},{"n":"Alexander D'alessandro","a":"UNFPA","b":"Alexander D'alessandro is a Digital Programme Specialist at the United Nations Population Fund's (UNFPA) Digital Center of Excellence in New York, where he leads global frontier-technology initiatives spanning virtual reality training, drone logistics, and AI-driven solutions for sexual and reproductive health. With over 10 years of experience across UNFPA, UNDP, and EU institutions in New York, Brussels, Bolivia, and Nicaragua, Alexander specializes…"},{"n":"Deepa Prasad","a":"UNFPA","b":"Dr. Deepa Prasad is a highly accomplished public health leader currently serving as the Chief of Programs and Technical Support Unit at the UNFPA India Country Office, a position she has held since April 2021. Bringing a wealth of expertise and 15 years of dedicated experience with UNFPA India, Dr. Prasad is a specialist in high-level policy design, comprehensive program management, multi-stake agency coordination, and influential leadership. Her…"},{"n":"Taufiq Sitompul","a":"PATH","b":"Taufiq Sitompul is a digital health specialist with a background in information and communication technology and public health. He has spent more than 20 years strengthening Indonesia's health information systems, including designing health data interoperability, applying international health data standards, and building digital systems that link health services with data use. As Senior Digital Health Advisor at PATH, he leads the development and…"},{"n":"Nisa Nurkhotami","a":"PATH"},{"n":"Suthan Kaveri","a":"Universiti Malaya / United Nation University Global Health","b":"Dr. Suthan Kaveri is a Medical Doctor, early-career public health researcher, and Medical Technopreneur, serving as the founder and CEO of ePink Health Sdn. Bhd., a digital health startup focused on advancing accessible, technology-enabled healthcare solutions. He is currently pursuing a Master of Public Health (MPH) at the Faculty of Medicine, Universiti Malaya, with research interests in digital health adoption, virtual healthcare models, health…"},{"n":"Claudia Lopes","a":"United Nations University - Global Health","b":"Dr. Claudia Abreu Lopes is a Research Lead in Digital Health at the United Nations University (UNU) Global Health, where she explores innovative approaches to addressing health inequities through research and policy. Her interdisciplinary background in behavioural science, research methods and public health was developed over two decades of experience in academia, NGOs and the United Nations to support her commitment to producing rigorous research with…"}]},{"id":"s21","t":"Is Your Organisation Ready for the Next Wave of Digital Health?","d":"2026-12-02","s":"17:30","e":"18:30","tags":["Interactive Workshop","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Interactive Workshop","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Organisations adopting AI, digital technology and data-driven approaches often focus on the tools and overlook whether their leadership and structures are ready for the change. Drawing on more than ten years of advising social impact organisations on growth, leadership transitions and executive search, this virtual workshop introduces the NGO Recruit Partners Organisational Capacity Framework. Participants use the framework to assess their own organisation's leadership, governance and core capabilities, and identify where these need to change to support digital transformation.","sp":[{"n":"Dela ATUBRA","a":"NGO Recruit Partners","b":"Dela Atubra is the Founder and Managing Director of NGO Recruit Partners, a specialist executive search and advisory firm serving the global social impact sector. For more than a decade, she has advised boards, CEOs and senior leadership teams on executive appointments, organisational growth and leadership transitions across Africa, Europe and internationally. Through this work, she has developed a particular interest in how organisations evolve as…"}]},{"id":"s23","t":"Lessons Learnt from Designing Digital Health Intervention for Low and Middle Income Countries - A Case Study of EHR Deployment in 102 Primary Healthca","d":"2026-12-02","s":"18:35","e":"18:40","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Since 2022, the Lagos State Primary Health Care Board and Talamus Health, later supported by CHAI and the Gates Foundation, have rolled out an electronic health record system across 102 primary healthcare centres in Lagos, Nigeria. This talk follows the full implementation journey, from 20 high-volume facilities to statewide scale across 20 local government areas. The speakers give a candid account of adoption: 74% of facilities use the system fully every day, while 6% remain non-functional because of infrastructure gaps. They share practical lessons on phasing a rollout, building government confidence and addressing the realities that limit uptake in low-resource settings.","sp":[{"n":"Joel Aderinto","a":"Talamus Health Limited","b":"Joel Aderinto is a Digital Transformation and Innovation Expert with 15 years’ experience in driving strategic development and leadership within the health sector. He is a UK Global Talent, endorsed by the Tech Nation UK as an exceptional talent in the digital technology sector and currently the Global Head of Strategy, and Country Lead – Nigeria at Talamus Health where he led his team to undertake the biggest and most-successful primary healthcare…"},{"n":"Olalekan Folarin","a":"Talamus Health Limited","b":"Olalekan Folarin is a Business and Project Operations Manager at Talamus Health, a Nigerian healthtech startup building Africa's connected healthcare ecosystem. Talamus deploys Electronic Health Record systems, pharmacy management tools, and patient-facing applications across clinic and pharmacy networks nationally, giving patients and providers a unified digital platform for scheduling, records, and care coordination. In his role, Olalekan sits at the…"},{"n":"Oluwafemi Taiwo","a":"Talamus Health Limited","b":"Femi Taiwo is a digital health practitioner and product leader with close to a decade of experience building and implementing health technology across Nigeria's public and private primary care landscape. He currently serves as Senior Product Manager at Talamus Health Inc., where he leads product strategy and implementation for a suite of tools - including an EMR system and practice management software - designed for the realities of primary healthcare…"}]},{"id":"s24","t":"Women in Business, Women in Technology: Bridging the Digital Divide in Community-Based Pharmaceutical Access in Nigeria","d":"2026-12-02","s":"18:40","e":"18:45","tags":["Lightning Talk","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Lightning Talk","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Women-owned patent medicine vendors are a key source of maternal and newborn health commodities in many Nigerian communities, but manual record-keeping often leads to stockouts. This talk presents a digital inventory training programme for 61 women vendors in Kaduna and Lagos States, designed for different literacy levels and using visual materials. Pre- and post-tests measured changes in digital skills, and the speaker shares the results, what made the training work, and how similar approaches can strengthen community-level access to essential medicines.","sp":[{"n":"Sebastine Ikejide","a":"Society for Family Health Nigeria","b":"Sebastine C. Ikejide is a public health and development professional with over 18 years of experience designing and leading programmes across Nigeria's health system, including USAID, Global Fund, and DFID-financed initiatives. He holds a Master of Public Health from Imo State University and a Bachelor of Pharmacy from the University of Nigeria, Nsukka, and has currently completed an MSc in Health Economics, Management and Policy at the University of…"}]},{"id":"s26","t":"Accrediting the Future: A Cross-Country Dialogue on Pharmacy CPD Policy in Asia and Africa","d":"2026-12-02","s":"19:00","e":"20:00","tags":["Pre-formed Panel","Governance and Digital Health at Scale","Virtual"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Countries regulate digital continuing professional development for pharmacists in very different ways, and little evidence exists on what works. Drawing on surveys, key informant interviews and national policy documents, this panel brings together pharmacy association leaders from Cambodia, Nigeria, Senegal and Vietnam. The research found that Cambodia accredits several digital formats, Vietnam accepts only live webinars and Senegal has no documented policy at all. Panellists discuss how these accreditation rules shape pharmacists' training and what other countries can learn when designing their own policies.","sp":[{"n":"Josselyn Neukom","a":"SwipeRx (mClinica)","b":"Josselyn Neukom is the Senior Vice President of the Public Health Divison at SwipeRx, leading partnerships with global health partners to increase pharmacy contributions to public and community health priorities through largest digital network of pharmacies in Southeast Asia connected via SwipeRx. She is responsible for ensuring quality across a regional portfolio of digital health programs and research leveraging a suite of technology-based trade…"},{"n":"Le Thi Minh Chinh","a":"Vietnamese Pharmaceutical"},{"n":"Ban Botta","a":"Pharmacy Council of Cambodia"},{"n":"Mingue Niasse","a":"DKT, West Africa"},{"n":"Michael Alagbile","a":"Society for Family Health, Abuja, Nigeria"}]},{"id":"s27","t":"Designing the Financing of Community Health Under UHC: Kenya's Exploration of a Community Health Remuneration Package and a Financed Digital Backbone","d":"2026-12-02","s":"19:00","e":"20:00","tags":["Interactive Workshop","Financing for Sustainability","Virtual"],"fmt":"Interactive Workshop","theme":"Financing for Sustainability","mode":"Virtual","desc":"This interactive workshop takes participants through a live policy question from Kenya: how to make community health, and the digital systems it depends on, a permanently financed part of universal health coverage. As the Social Health Authority rolls out a digitised model combining service delivery, financing and digital health, Kenya is considering whether community health can be absorbed into it and what a community health remuneration package would include. Community health promoters' pay is now set in law, but financing for devices, hosting and other digital infrastructure is unresolved. Participants work through these design choices with officials from the Digital Health Agency and the Ministry of Health.","sp":[{"n":"Ryan Gitau","a":"AfyaPress Africa"},{"n":"Joyce Wamicwe","a":"Digital Health Agency - Technical lead for digital health and informatics at the DHA"},{"n":"Maureen Kimani","a":"Ministry of Health - Head of Division -Community health","b":"The real thought and implementation leader of Community Health in Kenya."}]},{"id":"s29","t":"Mapping Without the Map Expert: Building Interactive Health Maps with AI","d":"2026-12-02","s":"19:00","e":"20:00","tags":["Interactive Workshop","AI for Health","Virtual"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"Virtual","desc":"Maps can make a case for action that a table cannot, but producing them usually needs GIS specialists and licensed software. In this hands-on virtual workshop, participants use an AI tool and Leaflet.js, an open-source mapping library, to build interactive health maps from administrative boundary files without GIS expertise. They prompt the AI to write the map code, then add their own indicator data, layers and styling. For confidential data, participants learn a technique where the AI writes only the visualisation code and the real data is added locally, so sensitive information is never shared with the AI tool.","sp":[{"n":"Utkarsha Patil","a":"William J. Clinton Foundation (WJCF)","b":"Utkarsha Patil leads strategy and product work for the Health Analytics and AI Unit at India's National Health Authority as part of her role at the William J Clinton Foundation. Her work sits at the intersection of geospatial analysis, public health, and artificial intelligence, including the design of AI-powered tools that help government leadership navigate large-scale health data. Before moving into AI product work, she spent several years across…"},{"n":"Vibha Bhirud","a":"William J. Clintion Foundation (WJCF)","b":"Vibha Bhirud is a digital health leader with morethan a decade of experience at the intersection of public systems, technology, and social impact. As Co-founder of Intelehealth, she helped scale telemedicine to five countries and 5.2M+ lives, and led the drafting of Kyrgyzstan's national Digital Health Policy. She now works at WJCF Digital Health, supporting India's National Health Authority on the Ayushman Bharat Digital Mission (ABDM). Vibha holds a…"}]},{"id":"s28","t":"Mitigating System Paralysis and Data Cleansing Risks in Legacy HIS Modernization: A Hybrid openEHR and HL7 FHIR Implementation via 5-Pillars-by-Design","d":"2026-12-02","s":"19:00","e":"20:00","tags":["Interactive Workshop","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Interactive Workshop","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"Hospitals often struggle to bring older information systems in line with new national data-exchange rules without costly replacement, downtime or data loss. This workshop presents a layered integration approach used within the Total Hospital Information System framework, in which middleware maps legacy data to HL7 FHIR R4 resources and openEHR archetypes. Using a real case study, the session shows how legacy databases can be wrapped in secure, standards-based APIs, and how to manage risks such as data corruption and system paralysis during modernisation.","sp":[{"n":"FANI URNILA","a":"Freelance","b":"Fani Urnila is an independent healthtech developer and researcher specializing in clinical data interoperability frameworks. With a foundational background in midwifery sciences, she bridges the gap between frontline healthcare operations and modern digital infrastructure. Her current work focuses on developing scalable middleware architectures designed to map legacy hospital data structures into international data exchange standards, including HL7…"}]},{"id":"s25","t":"What Does It Take to Deploy Generative AI Safely for Youth Mental Health in Low-Resource Settings? Evidence and Open Questions from BraveHeart AI","d":"2026-12-02","s":"19:00","e":"20:00","tags":["Pre-formed Panel","AI for Health","Virtual"],"fmt":"Pre-formed Panel","theme":"AI for Health","mode":"Virtual","desc":"Generative AI is being adopted for youth mental health in low-resource settings faster than safety evidence is building up. This panel uses BraveHeart AI, one of the few such deployments with published safety data, to examine what makes a system safe enough to use, how safety can be shown, and which questions remain open. The Slum and Rural Health Initiative team gives three short presentations, each drawing a lesson from their own evidence. Participants will learn which parts of a safe deployment can transfer to other settings and which depend on local context.","sp":[{"n":"Owen Adeniyi","a":"Slum and Rural Health Initiative","b":"Owen Adeniyi — Moderator Director of Creativity and Innovation, Slum and Rural Health Initiative (SRHIN) Owen Adeniyi leads the design and delivery of AI-driven health tools for low-resource settings at SRHIN, including BraveHeart AI. His work sits at the intersection of artificial intelligence, health equity, and communication, spanning product development, applied research, and communication strategy, and he leads a multidisciplinary team of…"},{"n":"Ezekiel Oladejo","a":"Slum and Rural Health Initiative","b":"Ezekiel Oladejo — Presenter 1 (lead): Designing for low-resource reality AI/NLP Engineer, SRHIN AI for Low-Resource Public Health Application Centre Ezekiel Oladejo builds end-to-end machine-learning and NLP systems for mental health and maternal health in low-resource public health settings, from data pipelines and model training through deployment and evaluation, tailored for multilingual local datasets. He specialises in robust, interpretable, and…"},{"n":"Uthman Babatunde","a":"Slum and Rural Health Initiative","b":"Dr Uthman Babatunde — Presenter 2: Generating credible safety evidence Medical Doctor and Applied AI/ML Engineer, SRHIN Dr Uthman Babatunde works at the intersection of clinical medicine and machine learning. Time in clinical practice exposed the gaps that intelligent systems can help close, and he now builds LLM-based systems, retrieval-augmented architectures, and automation pipelines for mental health screening, maternal triage, multilingual NLP,…"},{"n":"Olamide Oso","a":"Slum and Rural Health Initiative","b":"Olamide Oso — Presenter 1 (co-presenter): Building for low-resource reality Software Engineer Olamide Oso is a full-stack software engineer with a strong backend foundation, experienced in building web and mobile applications end to end, from API and database design to responsive, user-facing interfaces, and in applying automation and machine learning to real-world products. He is motivated by turning complex problems into simple, reliable tools that…"},{"n":"Promise Taiwo","a":"Slum and Rural health Initiative","b":"Promise Taiwo — Presenter 3: Equity, reach, and governance Senior Mental Health Programs Officer, SRHIN Promise Taiwo is a mental health communicator, public health professional, and youth-engagement leader with a Master's in Field Epidemiology and over five years implementing mental health programmes for children, adolescents, and young people. At SRHIN she leads youth-centred mental health projects, communication campaigns, and advocacy, including…"}]},{"id":"s30","t":"What Does Mental Health Care Look Like When There Are No Mental Health Services?","d":"2026-12-02","s":"20:00","e":"20:05","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"In conflict-affected camps for internally displaced people in Northern Nigeria, trauma is widespread and formal mental health services do not exist. This talk describes BraveHeart AI, a community-centred generative AI platform that works in Hausa, Yoruba and Nigerian Pidgin and is used in community safe spaces called Friendship Tents. The speaker explains how the tool was designed for a setting with no health facilities to refer to, how safeguards were built in, and what the experience shows about designing digital mental health tools for humanitarian settings.","sp":[{"n":"Ezekiel Oladejo","a":"Slum and Rural Health Initiative","b":"I am an AI Researcher with 4 years experience in machine learning, NLP, speech processing, and Generative AI for real-world public health applications. Proven expertise in developing AI-driven mental health solutions, fine-tuning large language models, and building culturally adapted conversational systems for low-resource settings. Strong background in Python, PyTorch, TensorFlow, Hugging Face Transformers, and applied AI research, with peer-reviewed…"}]},{"id":"s31","t":"A lightweight safety check for clinical AI in small hospitals: hematology triage thresholds as a digital health governance signal","d":"2026-12-02","s":"20:05","e":"20:10","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"This talk presents REDFLAG HEME, a fully synthetic benchmark for checking whether clinical language models keep escalation thresholds in hematology cases seen at small hospitals. The benchmark uses 40 adult internal medicine scenarios, two prompt formats and two free language models, producing 160 outputs for review. The speaker shows why overall accuracy is not enough when deciding whether to use an AI tool, and recommends that teams report under-referral, over-referral, shifts in urgency and parsing failures separately before adding any tool to clinical workflows.","sp":[{"n":"Goktug Ozkan","a":"Kutahya Emet Dr. Fazil Dogan State Hospital","b":"Goktug Ozkan is an internal medicine physician at Kutahya Emet Dr. Fazil Dogan State Hospital in Turkiye. His current work focuses on clinical artificial intelligence evaluation, local implementability, triage thresholds, and safety governance for small hospital decision support."}]},{"id":"s32","t":"Integrating climate data into a digital emergency platform for maternal and newborn care in Kenya: what a null result taught us","d":"2026-12-02","s":"20:10","e":"20:15","tags":["Lightning Talk","Climate and Health","Virtual"],"fmt":"Lightning Talk","theme":"Climate and Health","mode":"Virtual","desc":"Rescue.co added real-time and historical weather data to Flare, its emergency dispatch platform in Kenya, so dispatchers handling maternal and newborn emergencies could see weather alongside case, traffic and facility information. The project was designed around extreme heat, but no heat events occurred during the 24 months, and rainfall, flooding and poor visibility became the main concerns. An analysis of five weather measures against obstetric case volumes found no meaningful relationship. This talk gives an honest account of the work, including the null result, and what it means for teams adding environmental data to health systems.","sp":[{"n":"Anna Fraenzel","a":"Rescue.co","b":"Anna Fraenzel is Director of Partnerships at rescue.co, operator of the Flare emergency dispatch platform, leading government, donor and mass-market partnerships, in addition to research and innovation."}]},{"id":"s33","t":"Evaluating AI-Driven Decision-Support Systems for Outbreak Surveillance Under Resource Constraints","d":"2026-12-02","s":"20:15","e":"20:20","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Most evaluation frameworks for AI-driven decision support assume stable connectivity, complete data and dedicated technical staff, which many African surveillance programmes lack. This talk proposes an evaluation framework for outbreak surveillance tools that accounts for intermittent connectivity, reporting delays and small teams. The speaker applies it retrospectively to a published case: the district-level decision support tool used in Port Loko, Sierra Leone, after the 2014-2016 Ebola outbreak. Participants will see why standard performance metrics can mislead decision-makers and how to adapt the framework to tools they are evaluating now.","sp":[{"n":"Sophia Okpegboroh","a":"Araba Technology Ltd","b":"Sophia Okpegboroh is an early-career professional, Computer Science graduate, AI Engineer, and public health enthusiast focused on advancing health systems in Nigeria and globally. With experience spanning ICT operations, software development, and strategic communications, she brings a cross-functional perspective to applying data science and emerging technologies in resource-constrained health settings."}]},{"id":"s34","t":"From Global Evidence to a Co-Designed Competency-Based Curriculum: Strengthening Health Workforce Capacity for Responsible AI in Health in Low-Resourc","d":"2026-12-02","s":"20:20","e":"20:25","tags":["Lightning Talk","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Lightning Talk","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"AI is entering health systems faster than the workforce is being prepared to govern and use it, and in low-resource settings this gap is institutional and ethical as well as technical. This talk presents how the Global Health Institute at the American University of Beirut developed a competency-based Certificate in Responsible AI for Health in Low-Resource Settings. The speaker describes the method used, from reviewing global evidence to co-designing the curriculum with stakeholders, and shares the resulting competencies. Participants will gain a model they can adapt for their own AI training programmes.","sp":[{"n":"Nadine Sabra","a":"Global Health Institute","b":"Nadine Sabra is the E-Sahha/Digital Health Program Manager at the Global Health Institute at the American University of Beirut, where she coordinates AI, e-health, and digital health projects. Nadine oversees the operations of field-based projects focused on digital health and maternal & refugee health. She also serves as the coordinator of the Global Health and Artificial Intelligence Network in the Middle East and North Africa (GHAIN MENA) and the…"}]},{"id":"s35","t":"Mamawell AI: Embedding Crisis Safeguards into a Generative AI Mental Health Companion on WhatsApp","d":"2026-12-02","s":"20:25","e":"20:30","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Perinatal mental health is one of the least served areas of primary care in Nigeria. Mamawell AI is a WhatsApp companion developed by the Slum and Rural Health Initiative that lets pregnant and postpartum women ask about their mental health in English, Yoruba, Hausa, Igbo and Nigerian Pidgin, with answers grounded in verified maternal health content. This talk focuses on its crisis-detection safeguards, which identify signs of hopelessness or suicidal thoughts and connect women to help, and on how the team measured whether those safeguards work, including sensitivity and specificity.","sp":[{"n":"Fadekemi Fadare","a":"SRHIN","b":"I am an AI Fellow at the Slum and Rural Health Initiative Nigeria (SRHIN), where I lead the development of the BetaMama Pikin ecosystem, a suite of AI-powered maternal and perinatal health products deployed across Nigerian communities. My work spans clinical decision support, perinatal mental health screening, and multilingual conversational AI for low-resource settings. I hold a B.Sc. in Human Nutrition and Dietetics from Osun State University."}]},{"id":"s36","t":"Privacy by Design as Harm Reduction: A Framework for Preventing Psychological Harm in AI Mental Health Tools","d":"2026-12-02","s":"20:30","e":"20:35","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"AI mental health tools are reaching people in Nigeria faster than formal care, and many collect very personal information without privacy practices that match its sensitivity. This talk presents Echoes, a voice-based AI tool for Nigerian users, together with a framework that treats privacy as a way to reduce psychological harm. The speaker explains how weak or unclear data protection can itself cause harm, such as fear of disclosure and anxiety, and sets out design practices that developers of mental health AI can apply.","sp":[{"n":"Mercy Ogunwale","a":"The EPIX Initiative","b":"Mercy Ogunwale has a background in public health and is the founder of The EPIX Initiative, a digital health research and development organization. Her current work focuses on Echoes, a voice based AI mental health tool designed for Nigerian users, with an emphasis on building privacy and psychological safety into AI health tools from the ground up."}]},{"id":"s37","t":"Workforce Capacity and Leadership for the Digital Future","d":"2026-12-02","s":"20:35","e":"20:40","tags":["Lightning Talk","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Lightning Talk","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"In Wakiso District, Uganda, Living Goods supports the Ministry of Health to run the electronic Community Health Information System through a model that digitises, equips, supervises and pays Village Health Teams. Using twelve months of data from community and facility systems, the team tracked whether treatment of malaria in children under five moved from facilities to the community, and compared supported and unsupported sub-counties. This talk shares the results and shows how routine digital data can demonstrate that a digital tool changed where care happens, the kind of evidence governments and funders increasingly ask for.","sp":[{"n":"Moses Okech","a":"Living Goods","b":"Moses Okech is a Monitoring, Evaluation and Learning Manager at Living Goods Uganda, where he leads data analytics and operational research for community health systems strengthening across Wakiso and Mayuge districts. His work centres on digitally-enabled community health — eCHIS and integrated community case management (iCCM) — and on turning routine data from systems like eCHIS and DHIS2 into evidence that informs Ministry of Health and district…"}]},{"id":"s38","t":"Beyond Accuracy: The Novel P3-EQ Framework for Evaluating Consumer-Facing Artificial Intelligence in Assessing Geographically Diverse Risks","d":"2026-12-02","s":"20:40","e":"20:45","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"People increasingly turn to consumer AI platforms, including chatbots and AI-assisted search, for health guidance, yet there is no standard, equity-focused way to judge whether their answers are accurate, suited to the user's context and free of geographic bias. This talk presents the P3-EQ Framework, which assesses AI health outputs on five dimensions: precision, personalisation, proactivity, equity and quality. It was developed from an analysis of travel medicine answers produced by four major AI platforms. The speaker sets out gaps in existing AI evaluation frameworks and shows how P3-EQ can be used to benchmark consumer-facing tools.","sp":[{"n":"FRANKLINE WIRSIY","a":"SHORELAND INC.","b":"Dr. Frankline SEVIDZEM WIRSIY is a global public health and development professional with 12 combined years of relevant experience working with international and national organizations across global health security, public health epidemiology, research and development, emergency outbreak response, humanitarianism, One Health, climate change impact on health, organizational assessments/evaluations, immunization practice, advocacy, travel health, youth…"}]},{"id":"s39","t":"Funding Environmental AMR Mitigation through Digital MRV and Carbon Markets in LMICs","d":"2026-12-02","s":"20:45","e":"20:50","tags":["Lightning Talk","Climate and Health","Virtual"],"fmt":"Lightning Talk","theme":"Climate and Health","mode":"Virtual","desc":"Pharmaceutical pollution in rivers and wetlands is an overlooked driver of antimicrobial resistance in low- and middle-income countries. At the same time, carbon markets are growing but only count climate benefits such as reduced emissions. This talk proposes a digital monitoring, reporting and verification framework that combines low-cost water sensors with periodic lab testing so environmental health improvements can be measured and potentially financed through carbon markets. The speaker explains how the framework could work and what would be needed to link climate finance with action on antimicrobial resistance.","sp":[{"n":"Bridget Kobusingye","a":"Ministry of health","b":"Kobusingye Bridget is a pharmacist with a strong interest in antimicrobial resistance (AMR), public health, and digital health innovation. Her work focuses on addressing environmental drivers of AMR and exploring data-driven and cross-sector solutions that integrate health, climate, and financing systems in low- and middle-income countries. She is particularly interested in how digital tools and innovative monitoring systems can strengthen health…"}]},{"id":"s40","t":"Decoding cardiac \"languages\" with large language models","d":"2026-12-02","s":"20:50","e":"20:55","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"This talk presents an MSc dissertation from the University of Oxford that tests whether electrocardiogram signals can be turned into representations a large language model can use to answer clinical questions. Using the PTB-XL and ECG-QA datasets, the project encodes 12-lead ECGs with a frozen cardiac foundation model, then trains a small adapter that feeds the result into a language model as prompt tokens. The speaker explains the approach, shares results on yes/no diagnostic questions, and discusses what this kind of lightweight multimodal model could mean for ECG interpretation in settings with few cardiologists.","sp":[{"n":"Tariro Banganayi","a":"University of Oxford","b":"I am an MSc Applied Digital Health student at the University of Oxford, with a background in software engineering and undergraduate training in computer science and biology. My dissertation explores how cardiac foundation models and large language models can be connected for ECG question answering. More broadly, I am interested in building digital health technologies that are technically rigorous, usable in practice, and adoptable in public health…"}]},{"id":"s41","t":"Bridging the Maternal Care Gap Through mHealth, AI, and Provider Engagement: Insights from the GAIN MHI Experience in Lebanon","d":"2026-12-02","s":"20:55","e":"21:00","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"GAIN MHI is an AI-based, gamified mobile health programme developed by the Global Health Institute at the American University of Beirut to improve maternal care in Lebanon, where economic crisis, refugee needs and limited antenatal care strain primary healthcare. The study compared three groups: a control group, one engaging pregnant women and their spouses, and one that also engaged obstetricians, gynaecologists and midwives. This talk shares what changed when health providers were involved alongside families and what that means for designing AI-enabled maternal health tools as part of a wider care model.","sp":[{"n":"Nour El Arnaout","a":"Global Health Institute, American University of Beirut","b":"Over the past 9 years, Ms. Nour El Arnaout has overseen the design and implementation of multiple large-scale initiatives at GHI focused on health, capacity building, and institutional strengthening. She has also spearheaded the expansion of the operations of the Institute to more than 10 countries of the MENA region. Her work has primarily focused on underserved and vulnerable refugee populations in fragile and resource-limited settings. Nour has…"}]},{"id":"s43","t":"Bringing data, digital health and AI governance to together for better health outcomes?","d":"2026-12-02","s":"21:00","e":"22:00","tags":["Pre-formed Panel","Governance and Digital Health at Scale","Virtual"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Good health data governance underpins quality, trusted and secure data, which in turn matters for AI governance and digital health. Many global and regional initiatives are now shaping health data governance, including a UN General Assembly process due to finish in 2027, and countries are asking for clarity on agreed norms and standards. This panel brings together speakers from WHO, the World Bank, the Ministries of Health of South Sudan and Sri Lanka, and Baraka Impact Finance Initiative. They map the current initiatives, discuss the components of good data governance, and consider how approaches to data, digital health and AI governance can be brought together.","sp":[{"n":"Craig Burgess","a":"World Health Organization","b":"Craig Burgess (LinkedIn) is the team lead for Management Health Information Systems (MIS), Digital Health & Information Systems unit (ISD), in WHO’s Department for Data, Digital Health, Analytics and AI. This role supports the Health Data Collaborative, Health Information Systems and Health Data Governance. For over 30 years, he has lived and worked in South Sudan, Afghanistan, Myanmar, India, Switzerland, USA, Australian and the UK; working at…"},{"n":"Malar Veerapan","a":"World Bank","b":"Malar Veerapan is a Senior Data Scientist & program manager at the World Bank, based in Washington DC, USA."},{"n":"John Rumunu","a":"Ministry of Health, South Sudan"},{"n":"Pradeep Sylva","a":"Sri Lanka Ministry of Health and University of Colombo"},{"n":"Carolina Batista","a":"Baraka Impact Finance Initiative"},{"n":"Bianca Carvalho","a":"WHO Youth Council"},{"n":"Smisha Agarwal","a":"Johns Hopkins Bloomberg School of Public Health"}]},{"id":"s42","t":"Bringing Mental Health Forward: African AI Innovations in Screening, Support and Care Pathways","d":"2026-12-02","s":"21:00","e":"22:00","tags":["Pre-formed Panel","AI for Health","Virtual"],"fmt":"Pre-formed Panel","theme":"AI for Health","mode":"Virtual","desc":"Mental health needs in Africa are high, while health systems face shortages of specialists, stigma, weak referral pathways and few tools for early detection. This panel brings together StrongMinds, Makerere University, Sunbird AI and Reach Digital Health to discuss whether and how AI can help bring mental health care into community, school, facility and direct-to-client programmes. Speakers share where AI has helped, for example in supervision, automation, linking people to care and direct support, and where it has fallen short. Participants will hear about both the potential and the pitfalls of adding AI to mental health programmes in low-resource settings.","sp":[{"n":"Jordan Levinson","a":"StrongMinds","b":"Jordan Levinson is Director of Digital Transformation at StrongMinds, where she leads the design, adoption and scale-up of digital and AI innovations that strengthen community-based mental health care at scale across Uganda, Zambia and beyond. Over more than fifteen years in digital health and global development, she has embedded frontline tools, data pipelines and dashboards into national systems in eleven countries, spanning community health,…"},{"n":"Carlos Yerena","a":"Reach Digital Health","b":"Carlos joined Reach Digital Health in May 2022, bringing over 15 years of leadership in building high-value partnerships across various industries. With a decade of focused expertise in Digital Health Technologies, he has successfully developed and implemented systems that empower users and health workers throughout Africa, driving positive health outcomes. His strategic acumen in cultivating and sustaining meaningful relationships with key partners…"},{"n":"Ernest Mwebaze","a":"Sunbird AI","b":"Ernest has pursued a distinguished dual career spanning academia and industry, with over a decade of experience as a lecturer at Makerere University. In industry, He has worked with leading research institutions including Google AI, and the United Nations Global Pulse Lab. Currently, Dr. Ernest is the Executive Director of Sunbird AI, a not for profit organisation that focuses on practical AI for social good. He is also the vice chairperson of the…"},{"n":"Charlotte Oloya","a":"StrongMinds","b":"Charlotte Oloya is Deputy Country Director of StrongMinds Uganda, where she oversees community-based depression treatment programs and partners with government ministries to embed mental health care in schools, health centers, and communities. She advocates for the inclusion of mental health in national policy, and her research includes mobile phone interventions for youth sexual and mental health in southwest Uganda. Charlotte is a passionate advocate…"}]},{"id":"s207","t":"Public Health Professionals Mixer- Global","d":"2026-12-02","s":"21:00","e":"22:00","tags":["Interactive Workshop","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Interactive Workshop","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Public Health Professionals Networking Mixers began in Delhi in January 2025 as an informal meeting of 18 people. Within a year they had grown to eight cities, including New York, and reached more than 200 public health students and professionals. The mixers are co-organised by the Public Health Professionals Coalition for Global Impact, SHIIRI Public Health and Aarogya Seva Global Health Volunteer Alliance, and bring together people from academia, NGOs, government, multilateral agencies and healthcare. This session shares how the mixers were set up and grew, and how similar community-led networks can address the isolation, limited mentoring and unclear career paths many early-career public health professionals face.","sp":[{"n":"Ridima Kamal","a":"Public Health Professionals Coalition for Global Impact","b":"Dr. Ridima Kamal (BDS, MPH, PhD Pursuing) is a dentist-turned-public health professional with expertise spanning community health, global health operations, and health systems development. She currently serves as Chief Manager of Partnerships & Collaborations at Aarogya Seva and is the Founder of PHPCG – Public Health Professionals Coalition for Global Impact, one of India's fastest-growing communities for aspiring and mid-career public health professionals.…"}]},{"id":"s20","t":"What Does Successful AI Adoption Look Like in African Health Systems?","d":"2026-12-02","s":"21:00","e":"22:00","tags":["Pre-formed Panel","AI for Health","Virtual"],"fmt":"Pre-formed Panel","theme":"AI for Health","mode":"Virtual","desc":"AI is moving from pilots into implementation across African health systems, yet success is still often judged by technical performance or completing a pilot. This panel asks what successful AI adoption actually looks like: whether tools create real value, are trusted by health workers and patients, are governed responsibly, and become part of routine care. Speakers from AI innovation, health system implementation and AI governance discuss the organisational, operational and governance conditions that decide whether AI tools last, and share practical measures of success that go beyond accuracy.","sp":[{"n":"Valentine Kamau","a":"AI HealthBeat Podcast","b":"Valentine Kamau is the Founder and Host of AI HealthBeat Podcast, a platform spotlighting the people, innovations, and ideas shaping the future of AI in healthcare across Africa. She works at the intersection of health systems, partnerships, and healthcare innovation, convening conversations that connect policy, implementation, research, and technology. With over a decade of experience in global health, Valentine has contributed to multi-stakeholder…"}]},{"id":"s44","t":"When Community Knowledge Becomes the Dataset: Lived Experience as Technical Evidence in AI-Powered Digital Mental Health","d":"2026-12-02","s":"21:00","e":"22:00","tags":["Interactive Workshop","AI for Health","Virtual"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"Virtual","desc":"This workshop presents Lived Experience as Evidence, a framework in which community knowledge is treated as the main source of technical evidence for AI systems, rather than as feedback on decisions researchers have already made. The Slum and Rural Health Initiative team draws on two programmes in Nigeria: GENSCORE, an AI mental health assessment tool in Nigerian Pidgin built from 432 hours of community audio, and Brave Heart, a digital mental health intervention for young people. Participants learn how the framework differs from co-design and human-centred design, and practise applying it to the development, implementation and evaluation of their own digital health tools.","sp":[{"n":"Promise Taiwo","a":"Slum and Rural Health Initiative","b":"Promise Taiwo is a public health professional, mental health communicator, researcher, and lived experience advocate with personal lived experience of depression. She serves as Senior Mental Health Programs Officer at the Slum and Rural Health Initiative (SRHIN), Nigeria, where she leads youth-centered mental health programmes, strategic communication, and lived experience engagement initiatives. As Secretary of SRHIN's Lived Experience Working Group,…"},{"n":"Miracle Adesina","a":"Slum and Rural Health Initiaitve","b":"Miracle Adesina is a Nigerian public health researcher and Country Coordinator at the Slum and Rural Health Initiative, where he leads research on community-led mental health systems for displaced and underserved populations across Africa. He brings both professional and lived experience of mental illness to his work, and is Co-Investigator on GENSCORE, a Wellcome Trust funded project applying generative AI to mental health screening, co-designed from…"},{"n":"Precious Adeyeye","a":"Slum and Rural Health Initiaitve","b":"Precious Adeyeye is a mental health researcher and Junior Research Officer at the Slum and Rural Health Initiative, passionate about advancing evidence-based solutions to improve mental health outcomes in underserved communities. Her work spans research and data-driven advocacy, with a focus on strengthening mental health systems, promoting mental health literacy, and addressing barriers to care. Her research interests include gambling-related harms,…"}]},{"id":"s45","t":"Reimagining Mental Health Support Through AI-Based Digital Platforms: User Experience and Effectiveness","d":"2026-12-02","s":"22:00","e":"22:05","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"This talk shares findings from a qualitative study of how adults in Port Harcourt, Nigeria, use AI-based mental health tools such as chatbots, apps and web platforms. Based on interviews with people who had used these tools, the speaker describes what users found helpful, including privacy, convenience and quick access, and where AI support fell short. The findings point to the features that make AI mental health tools acceptable and useful in an African urban setting, and to the limits that developers and health systems need to plan for.","sp":[{"n":"Chineye Fabian Adili-George","a":"University of Alabama at Birmingham","b":"Dr. Chineye Fabian Adili-George is a trained dental surgeon, health services researcher, and global health innovator whose work sits at the intersection of health systems strengthening, digital health innovation, health policy, and healthcare access in low- and middle-income countries. He is currently pursuing a PhD in Health Services Administration at the University of Alabama at Birmingham (UAB), where his research focuses on health policy…"}]},{"id":"s46","t":"The Price of Representativeness: Costing Nationally Representative Mobile Phone Surveys in Six Countries","d":"2026-12-02","s":"22:05","e":"22:10","tags":["Lightning Talk","Financing for Sustainability","Virtual"],"fmt":"Lightning Talk","theme":"Financing for Sustainability","mode":"Virtual","desc":"Mobile phone surveys are now widely used to track non-communicable disease risk factors in low- and middle-income countries, but ministries of health often stall on one question: how much do they cost? This talk presents the first multi-country cost analysis of nationally representative mobile phone surveys, drawing on CDC-supported surveys in Sri Lanka, India (Mumbai), Malawi, Zambia and Morocco. The speaker breaks costs down into airtime, incentives and administration, compares voice and SMS surveys using cost per completed interview, and offers benchmarks countries can use when planning and budgeting their own surveys.","sp":[{"n":"Dustin Gibson","a":"Johns Hopkins Bloomberg School of Public Health","b":"Dustin Gibson, PhD, is an Associate Research Professor and Associate Director in the Center for Global Digital Health Innovation at the Johns Hopkins Bloomberg School of Public Health, Department of International Health. His research develops and validates mobile phone survey methods for non-communicable disease risk factor surveillance in low- and middle-income countries, with active studies in Bangladesh, Colombia, Uganda and Tanzania under the…"}]},{"id":"s47","t":"Strengthening Supply Chain Resilience Through Sustainable Financing of Digital Supply Chain Information Systems","d":"2026-12-02","s":"22:10","e":"22:15","tags":["Lightning Talk","Financing for Sustainability","Virtual"],"fmt":"Lightning Talk","theme":"Financing for Sustainability","mode":"Virtual","desc":"Electronic logistics management and warehouse management systems keep medicines and vaccines moving in low- and middle-income countries, but cuts to development funding have exposed how fragile their financing is. National budgets tend to fund physical supply chain costs before the digital systems behind them. This talk sets out the main reasons these systems are underfunded and presents a framework for moving them from donor dependence to sustainable country ownership, including how to make the case for them in national budgets.","sp":[{"n":"Omar Balsara","a":"JSI Research & Training Institute Inc","b":"Omar Balsara is a Senior Technical Advisor with JSI Research & Training Institute, Inc. in its Supply Chain Practice, bringing over 15 years of global experience in digital supply chain transformation, supply chain information systems, and system sustainability. Throughout his career, Omar has led the design and implementation of integrated digital tools that strengthen forecasting and inventory management, advance product traceability, optimize costs,…"}]},{"id":"s234","t":"From Fragmented to Unified: Leveraging Free and Open-Source Tools to Standardize AMR Data for National Surveillance in WHONET","d":"2026-12-02","s":"22:15","e":"22:20","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"","sp":[{"n":"Katherine Morris","a":"Association of Public Health Laboratories","b":"Katherine Morris is a Senior Specialist at the Association of Public Health Laboratories (APHL) in Global Health, Informatics. Katherine has over 10 years of experience in public health laboratories, specializing in public health informatics. She has a master of public health (MPH) in Epidemiology from George Washington University in Washington, DC USA and a Bachelor of Science (BS) in Biology."},{"n":"Matthew McCarroll","a":"Association of Public Health Laboratories","b":"Matthew McCarroll is a public health professional with expertise in laboratory systems, informatics, infectious disease preparedness, and data interoperability. As Principal Specialist for Global Health Informatics at the Association of Public Health Laboratories (APHL), he leads multinational initiatives that strengthen laboratory information systems and public health data exchange across Africa, Latin America, Eastern Europe and Central Asia,…"}]},{"id":"s48","t":"Gastric Cancer Pathway Adherence in a Regional Program in Southwestern Colombia: A Cohort-Scale Implementation Study","d":"2026-12-02","s":"22:20","e":"22:25","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Gastric cancer is a leading cause of cancer death in Colombia, and late diagnosis is often caused by gaps between risk assessment and follow-up endoscopy. This talk presents findings from a clinical audit platform that tracked 5,754 patients in a regional screening programme in southwestern Colombia between January 2025 and June 2026. Of the 565 patients rated high risk, 58% had no recorded endoscopy at the time of audit. The speaker explains how routine data and automated audits can reveal gaps in cancer care pathways and help programmes target follow-up where it is most needed.","sp":[{"n":"Katherine Monsalve","a":"Arkangel AI","b":"AI Scientist at Arkangel AI. International training in epidemiological research methods (Erasmus University, the Netherlands) and in Implementation Research. Advanced skills in data science, clinical research and artificial intelligence. Lecturer at Fundación Universitaria San Martín."}]},{"id":"s1","t":"Registration & Check In","d":"2026-12-02","s":"7:00","e":"17:00","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s3","t":"Welcome & Opening","d":"2026-12-02","s":"8:00","e":"8:25","tags":["Plenary","Hybrid Livestream"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s230","t":"Gates Foundation Plenary: Beyond the Pilot: Establishing Evidence for Frontline AI Tools","d":"2026-12-02","s":"8:25","e":"9:10","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"This plenary examines health AI evaluation across the patient care journey, following three grantees of the Evidence for AI in Health (EVAH) partnership - a joint initiative of the Gates Foundation, the Novo Nordisk Foundation, and Wellcome. The discussion explores how evaluations are designed to answer questions relevant to health workers, implementers, and policymakers, and what the broader field can learn from this emerging body of evidence.","sp":[{"n":"Dr. Lydia Nakiyingi","a":"Makerere University","b":"Infectious Diseases Physician and Senior Lecturer, Makerere University"},{"n":"Dr. Daniel Erku","a":"EPIC Health Systems","b":"Health Economist and Finance Lead, EPIC Health Systems"},{"n":"Dr. Christie Akwaowo","a":"University of Uyo","b":"Research Director and Associate Professor, University of Uyo"}]},{"id":"s232","t":"ADB’s UHC PEERS Dialogue: From Digital Health Strategy to Scale","d":"2026-12-02","s":"9:15","e":"10:15","tags":["In-person","Sponsored Session","Invite Only"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"This is an invite-only sponsored session. Speakers and session details will be announced soon.","sp":[]},{"id":"s229","t":"CHAI Spotlight Session","d":"2026-12-02","s":"9:15","e":"10:15","tags":["Spotlight Session","Hybrid Livestream","Sponsored Session"],"fmt":"Spotlight Session","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s5","t":"Climate-Smart Innovation: An AI-driven Tasking Feature for Frontline Resilience Integrated with Meteorological Data in Malawi","d":"2026-12-02","s":"9:15","e":"10:15","tags":["Pre-formed Panel","Climate and Health","In-person"],"fmt":"Pre-formed Panel","theme":"Climate and Health","mode":"In-person","desc":"Malawi's Ministry of Health, the national Meteorological department, the University of Malawi and Last Mile Health have built a climate-smart feature into iCHIS, the country's DHIS2-based community health information system. The feature combines real-time weather forecasts with a predictive AI engine to generate tasks for community health workers, such as handing out water-purification kits ahead of floods or changing vector-control priorities after heavy rain. Panellists walk through the system design, how the partners worked across sectors, and what it takes to bring AI into community-level workflows. Participants will see how climate data can be fed into mobile health tools so frontline teams act before conditions worsen.","sp":[{"n":"Paul Chabala Kaumba","a":"Last Mile Health","b":"Dr. Paul C. Kaumba is a digital health leader, researcher, and technology strategist with nearly two decades of experience designing and implementing digital health solutions across Africa and globally. He serves as Senior Manager for Digital Health at Last Mile Health, where he leads initiatives that strengthen national health systems through digital innovation, interoperability, artificial intelligence, and community health technologies. Dr. Kaumba…"},{"n":"Samuel Gama","a":"Ministry of Health - Malawi","b":"Samuel Gamah is a Primary Health Care Officer in the Community Health Services Section of the Malawi Ministry of Health. He has extensive experience in strengthening community health systems, primary health care, and digital health implementation, with a focus on integrating technology into frontline service delivery. Samuel has played a key role in advancing Malawi’s national community health agenda, including contributions to the implementation of…"},{"n":"Raphael Mwale","a":"Ministry of Health - Malawi","b":"Raphael Mwale is the Principal Digital Health Officer in the Digital Health Division of the Malawi Ministry of Health. He leads the design, implementation, and scale-up of national digital health initiatives that strengthen health service delivery through interoperable information systems, data use, and digital innovation. Raphael has been instrumental in advancing Malawi’s digital health agenda, including the implementation of the Integrated Community…"},{"n":"Victoria Munthali","a":"Last Mile Health","b":"Victoria Munthali is the Director, Community Health System Strengthening at Last Mile Health Malawi, where she leads the implementation and scale-up of the Integrated Community Health Information System (iCHIS) in partnership with the Malawi Ministry of Health and other stakeholders. She has extensive experience managing large-scale digital health programs, strengthening community health systems, and delivering technology-enabled solutions that improve…"},{"n":"Daniel Chaweza","a":"Last Mile Health","b":"Daniel Chaweza is a Digital Health Specialist at Last Mile Health Malawi, where he supports the design, implementation, and scale-up of the Integrated Community Health Information System (iCHIS) in collaboration with the Malawi Ministry of Health and key development partners. His work focuses on strengthening community health systems through digital innovation, health information systems, and data-driven decision-making. Daniel has experience…"},{"n":"Kondwani Munthali","a":"University of Malawi","b":"Dr. Kondwani Munthali is a researcher and digital health specialist at the University of Malawi, with expertise in health informatics, artificial intelligence, digital health systems, and applied research. His work focuses on designing and evaluating innovative digital solutions that strengthen health system performance and improve community health outcomes. Dr. Munthali has collaborated with the Malawi Ministry of Health, Last Mile Health, and other…"}]},{"id":"s201","t":"DCCC Sponsored Breakout: Driving Long-term Health Impact: Sustainable Business Models in Digital Health","d":"2026-12-02","s":"9:15","e":"10:15","tags":["Sponsored Breakout","In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"There is no shortage of pilots in global digital health. But not all of them are able to scale successfully. Creating long-term health impact requires sustainable business models and strong partnerships. It is particularly important in low- and middle-income countries, where the limited resources and growing burden of non-communicable diseases make it difficult to close access gaps through clinic-based care alone.\r\n\r\nGrounded in case examples, this DCCC session introduces four proven models that bring quality care closer to patients: telemedicine, pharmacy brick-and-click integration, remote diagnostics, and professional medical education.\r\n\r\nThe panelists share what makes each model sustainable and impactful, and how cross-sector partnerships help turn promising innovations into solutions that reach millions.","sp":[{"n":"Jeroen Maas","a":"Digital Connected Care Coalition","b":"Jeroen Maas is the Director of Access to Care Technology & Partnerships at Philips and the Core Team Lead at Digital Connected Care Coalition (DCCC), a global private sector coalition, where his work is focused on scaling digital health efforts in low- and middle-income settings through building transformative partnerships."},{"n":"Snehal Patel","a":"Saena Partners","b":"Snehal Patel is Managing Director of Saena Partners, a Singapore-based venture studio, and works with Longitude Health on technology-enabled care delivery in the United States. He co-founded, led, and successfully exited MyDoc, one of Asia’s earliest insurer-linked telemedicine platforms outside China. Trained in medicine, law, and finance, he brings a multidisciplinary perspective to the practical challenges of commercializing and scaling healthcare…"},{"n":"Jinnipa Panyawuthikrai","a":"PharmCare","b":"Jinnipa Panyawuthikrai is the founder and Managing Director of PharmCare, a Thailand-based online pharmacy platform offering medicine delivery, and professional consultations on medication use and health concerns."},{"n":"Dr. Sai Praveen Haranath","a":"Apollo Health Axis","b":"Dr. Sai Praveen Haranath is a US board-certified pulmonary and critical care physician. Based in Hyderabad, India, he serves as Chief Physician and Innovation Officer at Apollo Health Axis. His work has helped pioneer scalable, tech-enabled healthcare models that bridge the gap between urban tertiary centers and underserved communities across India and beyond."},{"n":"Khine Pwint Nwe","a":"Z-waka","b":"Khine Pwint Nwe is the Founder and CEO of Z-waka, a Singapore-headquartered digital health platform focused on making healthcare professional education more accessible, scalable, and impactful across Asia. Her work focuses on building sustainable, partnership-driven models that help bridge healthcare knowledge and access gaps, particularly in emerging markets."}]},{"id":"s8","t":"Discovery Stage: National architecture and EHRs at scale","d":"2026-12-02","s":"9:15","e":"9:45","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Three short presentations on building national digital health architecture and electronic health records at scale, with experiences from Ethiopia, Samoa and a modular EMR approach used across countries.\n\nPresentations in this session:\n7839 - Bridging the Divorce: Ethiopia’s Digital Health Enterprise Architecture and the Business Motivation Model (Amanuel Biru)\n8734 - Build It Once, Localize Anywhere: Modular EMR/HIS Configuration Across Countries (Michaël Bontyes)\n7272 - Scaling a national electronic health record in Samoa: implementation experiences and health worker adoption in a Pacific Island setting (Palepa Lenara Tupai-Fui)","sp":[{"n":"Amanuel Biru","a":"JSI Research & Training Institute, Inc.","b":"Amanuel Biru is a senior digital health leader who has played a key role in shaping Ethiopia’s digital health agenda. He led the development of the country’s foundational Digital Health Blueprint and first eHealth Architecture (eHA) and is currently leading the development of Ethiopia’s next-generation Digital Health Enterprise Architecture. As a long-term advisor to the Ministry of Health (MoH), Amanuel provides strategic and technical guidance to…"},{"n":"Michaël Bontyes","a":"Madiro","b":"Michaël Bontyes is Director of Programs and Digital Health at Madiro, where he leads teams building reusable, open-source health systems that ministries and NGOs own and run. Their work is in use in multiple countries with partners including Doctors Without Borders (MSF), the International Committee of the Red Cross (ICRC) and the Ministries of Health of Burundi and Madagascar. Over 15 years in engineering, innovation and global health, he has seen the…"},{"n":"Emily Porrello","a":"Beyond Essential Systems & UNSW School of Population Health","b":"Emily Porrello is Head of Programs at Beyond Essential Systems (BES) where she leads strategic digital health and health system strengthening initiatives across low- and middle-income countries. She co-designed and oversees implementation of BES’ strategic partnership with the Australian Government Department of Foreign Affairs and Trade under the Partnerships for a Healthy Region initiative, supporting digital health transformation in Pacific Island…"}]},{"id":"s202","t":"Sponsor Lightning Talks: System, Integral Global Health, SenseCare","d":"2026-12-02","s":"9:15","e":"10:15","tags":["Lightning Talk","In-person","Sponsored Session"],"fmt":"Lightning Talk","theme":"","mode":"In-person","desc":"Short sponsored talks on putting AI to work in health systems.\n \n From Data to Action: AI-Powered Epidemic Intelligence for Resource-Limited Settings (Integral Global Health)\n Outbreaks are rarely invisible in the data. Early signals sit in surveillance, campaign, environmental, genomic, and population records, but in resource-limited settings with unreliable internet, few analysts, and shrinking budgets, these streams stay fragmented, unvalidated, and delayed. Risk is recognized only after transmission spreads, putting timeliness targets such as 7-1-7 out of reach, and a detection gap anywhere is a risk to all.\n \n This lightning talk examines how AI can strengthen epidemic intelligence under these constraints, and where it can fail. Illustrated by Integral Global Health's Polio Epidemic Intelligence System (PEIS), built with a national polio eradication program, it shows what becomes possible when two decades of program records are validated, harmonized, and triangulated at sub-district level, then used by models to flag high-risk areas before cases emerge.\n \n Key themes:\n - Data before models: A versioned, multi-layer validation engine with a permanent audit trail makes data trustworthy enough for AI. Models trained on invalidated data can be confidently wrong.\n - Triangulation for early warning: Combining surveillance, campaign, environmental, and population data at the lowest administrative level reveals risks no single source can show.\n - Transparency and traceability: Every derived or estimated value is marked, corrections are human-approved and reversible, and \"not measured\" is never shown as zero.\n - Honest AI validation: Forecasts are tested on time periods the model has never seen, caveats are stated openly, and no impact is claimed before independent review.\n - Designing for the field: Offline-first operation, local data custody, shifting administrative boundaries, and the human trust that decides whether AI is used.\n \n Attendees will leave with practical, transferable lessons for building trustworthy AI from existing program data. Because the approach is disease-agnostic by design, it can extend to Ebola, cholera, measles, and other vaccine-preventable diseases.\n \n From Model to Clinical Practice in Southeast Asia (SenseCare)\n How can medical AI move beyond model performance to create real clinical value?\n In this session, SenseCare will showcase its capabilities in Radiology AI, Digital Pathology AI, and Medical LLMs, highlighting how AI can support medical professionals, enhance diagnostic efficiency, and integrate into clinical workflows.\n The session will also explore the importance of responsible AI adoption, including clinical validation, data governance, and human oversight, demonstrating how medical AI can translate technological innovation into practical healthcare applications.\n \n The System Public Graph: a living representation of the world's science and health knowledge, open, connected and computable (System)","sp":[{"n":"Tariq Khokhar","a":"System","b":"Tariq is the VP of Public Benefit at System: a Public Benefit Corporation with a mission to relate everything, and to help the world see and solve anything, as a system.\n\nTariq has spent the last 20 years building and investing in technology and data systems for the public interest. During the course of senior leadership roles at the Wellcome Trust, Rockefeller Foundation and the World Bank, he has been responsible for investing over $1.5 billion in companies, non-profits, research institutes and government programs working to develop and deploy digital technology, AI and data systems across the scientific, clinical, global health, and development sectors.\n\nTariq is a mathematician and computer scientist by training and has a personal interest in AI for mathematics. He is a senior advisor to several organizations including the UK's Health Data Research Service."},{"n":"Aurel K. Qian","a":"SenseCare","b":"Cofounder and Chief Medical Officer | SenseCare;  Adjunct Associate Professor | Fudan University\nProf. Qian is a computational neuroscientist and medical AI expert who leads trustworthy and safety-oriented AI initiatives at SenseCare. Formerly CIO of Zhongshan Hospital, she led its AI-powered digital transformation and a pioneering hospital digital twin initiative featured by Harvard Business Review. She is committed to using technology to improve…"},{"n":"Dr. Daniel Tom-Abba","a":"Integral Global Health","b":"Dr. Daniel Tom-Abba works at the intersection of epidemiology, health systems and applied AI. He co-architected SORMAS, EpidetectAI, the outbreak surveillance platform that achieved a 100% score on the WHO Global Goods Maturity Model and has been deployed across multiple countries. His work spans outbreak intelligence and surveillance, remote patient monitoring, clinical risk prediction, and the design and governance of AI systems in regulated health…"}]},{"id":"s252","t":"Discovery Stage: Preparing for an International Patient Summary Connectathon","d":"2026-12-03","s":"16:15","e":"16:45","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Join regional digital health leaders to prepare for an upcoming International Patient Summary (IPS) Connectathon. Speakers will cover Pacific health information network, DPI for health, WHO's GDHCN, IPS specifications, and the FHIRlab test environment. Participating labs from Australia, Malaysia, Nepal, Laos, Indonesia and Pacific Island Countries will share readiness, followed by the proposed timelines.\n\nHosted by the Asia eHealth Information Network (AeHIN).","sp":[]},{"id":"s253","t":"From Policy Gaps to Digital Solutions: Using AI and Culturally Tailored Tools to Strengthen Maternal Heat Adaptation in India","d":"2026-12-03","s":"18:50","e":"18:55","tags":["Lightning Talk","Climate and Health","Virtual"],"fmt":"Lightning Talk","theme":"Climate and Health","mode":"Virtual","desc":"Pregnant and lactating women are especially vulnerable to extreme heat, yet they are largely missing from India's climate adaptation plans. This talk shares a policy analysis of all 35 state Heat Action Plans and State Action Plans for Climate Change, which found heavy reliance on behavioural advice and almost no structural or health system measures for this group. The speakers then set out how SMARThealth ChatGPT, an LLM-based chatbot co-created with ASHA community health workers and tested in Hindi and Telugu, could be adapted into a culturally tailored tool that supports maternal heat adaptation.","sp":[{"n":"Gabriela De Jesus Cipriano Flores","a":"Imperial College London","b":"Dr Gabriela Cipriano Flores (MD, MSc) is a Research Assistant at Imperial College London and part of The George Institute Women’s Health Group. Her work focuses on climate change and women’s health, including research on extreme heat, maternal haemodynamics, and policies to better protect women through the Heat in Pregnancy - India program."},{"n":"Sreevatsan Raghavan","a":"Translational Health Science and Technology Institute","b":"Dr Sreevatsan Raghavan is a research scientist in clinical and environmental epidemiology at THSTI in Faridabad. His work focuses on maternal and perinatal health, climate-related exposures, and pregnancy outcomes. He currently manages the HiP-India program, a multicentric study on extreme heat and maternal, fetal, lactation, and newborn health."},{"n":"Karthika Kumar","a":"The George Institute for Global Health","b":"Dr. Karthika Kumar (MBBS, MPH) is a Research Fellow at The George Institute. Her work explores how environmental stressors, infrastructure inequities, and social determinants shape the experiences and adaptive strategies of vulnerable populations, particularly pregnant and lactating women."}]},{"id":"s250","t":"Emerson Collective Spotlight Session: Launching the AI Collaborative: Health - A New Partnership to Advance Responsible AI for Stronger Health Systems in Sub-Saharan Africa","d":"2026-12-03","s":"16:15","e":"17:15","tags":["Spotlight Session","Hybrid Livestream","Sponsored Session"],"fmt":"Spotlight Session","theme":"","mode":"Hybrid Livestream","desc":"The AI Collaborative: Health (AIC:H) is a joint initiative supported by Emerson Collective, the Gates Foundation, the Global Fund, and Google.org to catalyze the responsible use of AI to improve primary healthcare and health intelligence in sub-Saharan Africa. AIC:H is built on a simple principle: the people who know their health systems and communities best should lead decisions about how AI is used. Rather than arriving with ready-made solutions, AIC:H starts by listening to governments, frontline health workers, and communities to understand their priorities and where AI might make a meaningful difference.\n\nIts goal is to accelerate the responsible adoption and scaling of human-centered, evidence-based AI solutions that improve primary healthcare and health intelligence across sub-Saharan Africa.\n\nThis panel brings together government leaders, implementing partners, and digital health experts. We will present the Collaborative's goal, share how the investment priorities were shaped collectively with government leaders and health workers, outline the projects to be launched, and describe the intended impact.","sp":[{"n":"Rebecca Hope","a":"Emerson Collective","b":"Dr. Rebecca Hope, MD, MPH, is a pediatrician, designer, and public health leader serving as Senior Director of Global Health & Opportunity at Emerson Collective, where she leads our international grantmaking. She previously co-founded and led YLabs and held roles at Harvard School of Public Health and IDEO.org, leading design and randomized evaluations of digital health innovations for young people globally. She writes about technology and global health, with a deep interest in AI’s potential to support frontline health workers in low- and middle-income countries. She holds degrees from Harvard and University College London and has been recognized as a Top 50 in Digital Health, an Aspen Health Fellow, and recipient of the Society of Adolescent Health Innovation Award."},{"n":"Joy Kamunyori","a":"SecondMuse","b":"Joy Kamunyori is a digital health and AI leader with 18+ years of experience designing and scaling technology-enabled programs across 14 Sub-Saharan African countries. Currently a Senior Program Manager and Project Lead at SecondMuse, Joy was previously at USAID as Senior Health Information Systems Advisor, where she helped shape the agency’s global digital health and AI agenda. A native of Kenya, she is deeply committed to leveraging technology in practical, context-appropriate ways to advance inclusive, sustainable development. Her work spans strategic planning, program management, and stakeholder engagement."},{"n":"Marc Sépama","a":"Emerson Collective","b":"Marc Sépama, Senior Analyst, Global Health & Opportunity, Emerson Collective, is from Burkina Faso and is passionate about expanding access to quality healthcare for underserved communities across sub-Saharan Africa. At Emerson Collective, he is part of the philanthropy team, where he supports the sourcing and due diligence of global health partners. He brings experience spanning impact investing and the nonprofit sector, having previously worked at the RockCreek Group, Helen Keller International (HKI), and the World Justice Project. At HKI, he worked with stakeholders across multiple levels of the health system, from community health workers to Ministry of Health officials, in countries including Burkina Faso and Guinea. In this role, he supported the implementation of national programs addressing neglected tropical diseases and malnutrition. Marc holds a B.A. in economics from Dartmouth and a M.P.H. from Yale."},{"n":"Ahmed Ogwell","a":"VillageReach","b":"Dr. Ahmed Ogwell is the current CEO and President of VillageReach. He is a Kenyan public health expert with three decades of experience at the national, regional, and global levels.\n\nHe most recently served as Vice President for Global Health Strategy at the UN Foundation, where he led global health policy, advocacy, convening, thought leadership, and grant-making in support of the UN's priorities.\n\nBefore that, he was Deputy Director-General at Africa CDC, an institution he served in multiple leadership roles, including as Acting CEO and founding Deputy Director. He led the organization through a period of significant growth and transformation, steering Africa's response to the COVID-19 pandemic and other disease threats, including Ebola, Marburg, and cholera.\n\nEarlier in his career, Dr. Ogwell held distinguished senior roles at the World Health Organization (WHO) and Kenya's Ministry of Health. He is widely recognized for his expertise in global health security, health systems strengthening, and pandemic preparedness, and is a strong advocate for community and youth engagement in public health.\n\nDr. Ogwell is a Distinguished Fellow of the Academy of Public Health and an alumnus of the University of Nairobi, the University of Bergen, and Harvard Business School."},{"n":"Karla Palmer","a":"Google.org","b":"Karla is the Global Lead of Health AI & Sciences at Google.org, Google’s philanthropic arm, where she leads the organization's grantmaking strategy at the intersection of artificial intelligence, health, and science. Karla is a critical bridge between research scientists and engineers in Google Research and DeepMind and NGOs, universities, and governments seeking to leverage AI to advance societal outcomes. Karla also provides strategic oversight for the Partnership for AI Evidence (PAIE), an initiative created in collaboration with MIT’s Abdul Latif Jameel Poverty Action Lab, to rigorously evaluate the efficacy of AI interventions through randomized controlled trials. She created the strategic vision for the inaugural Google.org Accelerator: Generative AI, a first-of-its-kind initiative that provided funding, Cloud compute, and specialized technical assistance to 20 global nonprofits building generative AI-powered solutions to challenges in education, health, sustainability, and more. In her previous capacity as Program Manager of AI for Social Good & Sustainability, Karla established the Environmental Justice Data Fund, Google’s largest-ever investment in environmental justice. Karla holds an Honors BA in Political Science and a certificate of Advanced Leadership Studies from American University in Washington, D.C."},{"n":"Nana Kofi Quakyi","a":"Aurum Institute Ghana","b":"Nana Kofi Quakyi, MPH, is the Country Director of the Aurum Institute Ghana, where he oversees programs spanning tuberculosis, HIV, antimicrobial resistance, and digital health innovation. A public health policy and management expert, his work focuses on strengthening health systems through service delivery innovation, technology, and evidence-based policy. He is the Principal Investigator of a Gates Foundation-funded initiative developing AI-powered clinical decision support tools to improve antibiotic prescribing and antimicrobial stewardship in Ghana. He also co-chairs Ghana's Ministry of Health Digital Health and Data Infrastructure Sub-Committee. Previously, he was a Research Fellow and Adjunct Assistant Professor at New York University. He holds an MPH from Emory University and a bachelor's degree from Columbia University."},{"n":"Alinafe Mbewe","a":"Malawi Ministry of Health and Sanitation","b":"Dr. Alinafe Mbewe is a Deputy Director within the Quality Management Directorate and leads the Digital Health Division at the Malawi Ministry of Health and Sanitation. A medical doctor and health systems management professional based in Malawi, she leads all national digitalization initiatives for the Ministry. Her work focuses on national leadership, policy, digital health governance, institutional mandates, partner alignment, standards, and financing. She also brings extensive experience in guiding complex, multi-stakeholder initiatives and national rollouts."}]},{"id":"s240","t":"Discovery Stage: Advancing the Strategy for AI in Healthcare for India (SAHI): Strategic Priorities and the Path to Implementation","d":"2026-12-02","s":"9:45","e":"10:15","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"This session introduces India's Strategy for AI in Healthcare (SAHI), launched in 2026, and shares its distinctive approach to national AI policy development and implementation. It highlights how a whole-of-government, whole-of-society, and whole-of-ecosystem approach informed the strategy through extensive multistakeholder consultations, bringing together government institutions, academia, healthcare professionals, industry, development partners, and other stakeholders. It explores SAHI's hybrid top-down and bottom-up model of policymaking, which combined national strategic direction with ground-level priorities, implementation realities, and stakeholder perspectives. Building on this participatory process, the session discusses SAHI's strategic priorities, the development of its implementation roadmap, and the transition from policy formulation to operationalization, including opportunities for state-level implementation, institutional strengthening, and cross-sectoral collaboration to advance responsible, equitable, and sustainable AI adoption in healthcare.\n\nHosted by the WHO South-East Asia Regional Office and Ashoka University.","sp":[]},{"id":"s52","t":"Tea Break (sponsored by PATH)","d":"2026-12-03","s":"10:40","e":"11:15","tags":["In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s243","t":"Discovery Stage: Building FHIR Ecosystems in LMICs: Evidence, Barriers, Enablers and a Strategic Framework from South-East Asia","d":"2026-12-03","s":"11:15","e":"11:45","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"This session presents comparative evidence on HL7 FHIR adoption in India and Sri Lanka, examining the barriers and enabling conditions influencing ecosystem-wide implementation. It shares practical lessons and a strategic framework to advance standards-based interoperability as a foundation for health digital public infrastructure in LMICs.\n\nHosted by The George Institute for Global Health and the WHO South-East Asia Regional Office.","sp":[]},{"id":"s55","t":"Individual Presentations: Building Trusted Digital Public Infrastructure: Examples from Asia","d":"2026-12-03","s":"11:15","e":"12:15","tags":["Individual Presentation","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Individual Presentation","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"Five presentations from Bangladesh, Thailand and Vietnam on building trusted digital public infrastructure for health, covering workforce registries, patient-controlled consent, national FHIR implementation guides and terminology services.\n\nPresentations in this session:\n7942 - Transforming operational systems into foundational digital public infrastructure: Bangladesh's HRIS experience (Tasmia Islam, Sangay Wangmo)\n8808 - Patient-Controlled Consent Infrastructure at National Scale: Lessons from Thailand's MOPH–Mahidol–HealthTAG Health Data Exchange (Dechowat Promda, Suttisak Dendaungchai)\n7927 - Contextualizing FHIR for Bangladesh: A Governance-Driven National Implementation Guide for Interoperability (Abu Ahammad Al Mamun, Muhammed Ziaul Alam Chowdhury)\n7925 - Building Bangladesh's Central Terminology Registry: A Journey from Capacity Gap to Semantic Interoperability (Mohammad Adnan Khan, Hussain Mohammad Avique Asaf)\n7887 - Interoperability and Digital Public Infrastructure (TUAN KIEU QUANG)","sp":[{"n":"Tasmia Islam","a":"World Health Organization, Bangladesh","b":"Public health and digital health specialist with over 15 years of experience in health information systems, digital transformation, digital public infrastructure, interoperability, monitoring and evaluation, and health data governance. Currently serving as National Professional Officer (Health Information Systems) at the World Health Organization (WHO), providing technical leadership for Bangladesh's national digital health initiatives, including…"},{"n":"Sangay Wangmo","a":"World Health Organization","b":"Sangay Wangmo is Team leader for Health Systems unit at the WHO country office in Bangladesh. She has almost 20 years’ experience in the field of health systems and policy in Bhutan, Myanmar, Thailand, and Bangladesh. She has a master’s degree from London School of Hygiene and Tropical Medicine in Health Policy, Planning and Financing."},{"n":"Dechowat Promda","a":"HealthTAG","b":"Dr. Dechowat Promda is the Founder and CEO of HealthTAG, a Thai health technology company building consent-driven, interoperable health data infrastructure. He leads Thailand's smart-contract-based health information exchange, in production at Siriraj Hospital for three years and now expanding across Mahidol University-affiliated hospitals in collaboration with the Ministry of Public Health, serving approximately 200,000 patients. A physician by…"},{"n":"Suttisak Dendaungchai","a":"HealthTAG","b":"Dr. Suttisak Denduangchai is Tech Lead Developer at HealthTAG and a board-certified Occupational Medicine physician. He directs the technical roadmap and cloud architecture of HealthTAG's decentralized health data platform, including secure Personal Health Record storage, NFC-based health data exchange, and end-to-end encryption designed for patient privacy and data sovereignty. Uniquely bridging clinical and engineering domains, he translates medical…"},{"n":"Abu Ahammad Al Mamun","a":"Management Information System (MIS), DGHS, Bangladesh","b":"Dr. Abu Ahammad Al Mamun is a physician and digital health leader currently serving as Director (Management Information Systems) at the Directorate General of Health Services (DGHS), Ministry of Health and Family Welfare, Government of Bangladesh. In this role, he leads Bangladesh's national digital health transformation, including the formulation of the National Digital Health Architecture Blueprint and the development of the country's first National…"},{"n":"Muhammed Ziaul Alam Chowdhury","a":"MIS, DGHS, Bangladesh","b":"Muhammad Ziaul Alam Chowdhury is a Systems Analyst with expertise in health information systems, digital health infrastructure, and data platforms. His professional work focuses on implementing, maintaining, and integrating enterprise health solutions, with technical involvement across platforms such as DHIS2, OpenSRP, OpenMRS, and Fast Healthcare Interoperability Resources (FHIR) APIs. In addition to health software architecture, his technical…"},{"n":"Mohammad Adnan Khan","a":"Management Information System (MIS), DGHS, Bangladesh","b":"Dr. Mohammad Adnan Khan is a physician and health informatician serving as Assistant Chief (Medical) at the Directorate General of Health Services (DGHS), Government of Bangladesh. With academic qualifications spanning MBBS, MPH, M.Phil in Preventive and Social Medicine, and a Master's in Health Informatics, he brings both clinical and informatics perspectives to national digital health policy. At DGHS, he has been centrally involved in the development…"},{"n":"Hussain Mohammad Avique Asaf","a":"MIS, DGHS, Bangladesh","b":"Dr. Hussain Mohammad Avique Asaf, MBBS, MPH, is a Public Health Specialist serving as an RMO at the Management Information System (MIS), Directorate General of Health Services (DGHS), Bangladesh. With a background in Community Medicine, his areas of work and interest include telehealth, mortality data, health data analysis, and eLMIS. He is interested in strengthening data-driven decision-making and improving healthcare services in Bangladesh"},{"n":"TUAN KIEU QUANG","a":"NATIONAL HEALTH INFORMATION CENTER - Ministry of Health, Vietnam","b":"Kieu Quang Tuan is a specialist at the National Health Information Center (Ministry of Health), responsible for research on medical AI, health data, international cooperation, the Open Health Data Portal, and activities related to digital health research and consulting. Previously, he worked at the Center for Medical IT Applications, Department of Information Technology, Ministry of Health (2020–2023), serving as Head of the R&D Division from June 2023…"}]},{"id":"s54","t":"Past the Hype: What Does It Take to Run People-centered AI in Government Health Systems?","d":"2026-12-03","s":"11:15","e":"12:15","tags":["Pre-formed Panel","AI for Health","In-person"],"fmt":"Pre-formed Panel","theme":"AI for Health","mode":"In-person","desc":"AI for community health is moving quickly, but many models reaching the last mile were not built for it, and few have shown they can last inside a government health system. This panel brings together D-tree, Reach Digital Health, Noora Health and Living Goods, all of which work with ministries of health and last-mile communities. Panellists discuss what decides whether people-centred AI has lasting impact: data quality, governance and infrastructure, models adapted to context, and government ownership of both the tools and the intelligence behind them. They share what is working, what is failing, and how to keep equity at the centre.","sp":[{"n":"Shreya Bhatt","a":"Medic","b":"Shreya Bhatt is Co-Executive Director of Medic, where she has spent over a decade building the team, deepening partnerships, and growing the impact of the Community Health Toolkit, an open-source platform powering over 182,000 community health workers delivering last-mile care across 24 countries. Before Medic, Shreya worked with UNICEF, Teach for India, and Trickle Up, advancing programs in education, livelihoods, and socioeconomic empowerment, and…"},{"n":"Riccardo Lampariello","a":"D-tree","b":"Riccardo Lampariello is the Chief Executive Officer at D-tree since 2022. He has over 20 years of experience from the health sector - from Pharma, where he worked for 10 years in various positions in Clinical Development and Business Development, to international non-profit organizations. He worked for GAVI Alliance, the Union of International Cancer Control and most recently before D-tree at the Terre des hommes Foundation as the Head of the Health…"},{"n":"Debbie Rogers","a":"Reach Digital Health","b":"Debbie Rogers, a dynamic leader passionate about advancing mobile technology for health, brings a wealth of experience and expertise to her role as CEO of Reach Digital Health (Reach) and a board member of Turn.io. Her leadership tenure at the organisation, spanning over a decade, has demonstrated her ability to drive innovation and deliver impactful solutions. Drawing on her advanced Electrical and Electronic Engineering and Digital Arts degrees,…"},{"n":"Anubhav Arora","a":"Noora Health","b":"Anubhav is Executive Director - Product at Noora Health, where he helps build remote caregiving support tools for patient families and frontline health workers across India, Bangladesh, Indonesia, and Nepal. Anubhav was part of the founding team at Noora and spent several years designing and implementing Noora programs in the real world before transitioning to building digital solutions. His work sits at the intersection of AI, behavior change, and…"},{"n":"Gitahi Ng’ang’a","a":"Living Goods","b":"Gitahi Ng’ang’a is the Director of Software Engineering at Living Goods. He leads the Global Software Engineering unit, collaborating with cross-functional teams both internally and externally to drive digital interventions for community health in multiple countries. He has vast experience in building software solutions both within and outside the public sector. As a digital health specialist, Gitahi has consulted widely for prominent organizations…"}]},{"id":"s53","t":"Poster Presentations (Round 2)","d":"2026-12-03","s":"11:15","e":"12:45","tags":["Poster Presentation","In-person"],"fmt":"Poster Presentation","theme":"","mode":"In-person","desc":"The second poster round covers digital mental health, AI for diagnosis and community health workers, maternal risk prediction, flood response, climate-health decision support, antimicrobial stewardship, national data infrastructure and remote training for health workers. Presenters will be at their posters to discuss their work.\n\nPoster presentations in this session:\n7593 - From Chatbot to Safe Space: Building an Equitable and Safeguarded Digital Mental Health Ecosystem for University Students in Indonesia (Rizma Adlia Syakurah)\n7852 - TB-AI: Automated Detection of Mycobacterium tuberculosis and Other Pathogens Using Computer Vision and Knowledge-Based Systems (Hira Fareed)\n8442 - FHIR-Powered Maternal Risk Intelligence for Early Detection and Care Planning (Azka Aghnianuri, Rina Pertiwi, Lia Rosida)\n8689 - Making AI Affordable for Community Health Workers: A Guideline-Based Chatbot with Continuous Local Learning (Abu Md. Akteruzzaman Bhuiyan)\n7668 - From Policy Gaps to Digital Solutions: Using AI and Culturally Tailored Tools to Strengthen Maternal Heat Adaptation in India (Gabriela De Jesus Cipriano Flores, Sreevatsan Raghavan, Karthika Kumar)\n8791 - Hatyai ROD: A Real-Time One Data Platform for Flood Health Resilience and Emergency Response (Chanon Kongkamol, Apinya Chintrakul, Boonsita Suebchana)\n7627 - Examining the implementation of the Electronic Community Health Information System (eCHIS) in Kenya: A qualitative study on challenges and opportunities (Dosila Ogira)\n7896 - Digitisation of Antimicrobial Stewardship Workflows in Combating Antimicrobial Resistance (Goh Chan Sing)\n8264 - Digital Health Governance and Community Health in Burkina Faso: Lessons from Implementation Research (Beatriz Torres)\n8296 - Co-Designing Digital Health Technologies with Older People: Lessons for Scale and Sustainability from a UK Based Study (Shuvarthi Bhattacharjee)\n7489 - Strengthening Disease Surveillance Through Open Standards: Lessons from Kenya (Yusuf Ajack Ibrahim)\n8058 - Rebuilding a Scalable Data Infrastructure for Digital Maternal Health Across Four Countries (Kat James)\n8299 - Building a National Digital Health Data Infrastructure: Bangladesh's Central Data Repository for Interoperable Health Information Systems (Animesh Biswas)\n8694 - Investigating The Needs of Custom Coding System (Silvia Alvinia)\n7408 - Digital Classrooms for Remote Capacity Building of Frontline Community Health Workers in Cambodia: Applying Pilot Lessons to Ongoing Scale-Up and Health Systems Strengthening (Amos Zikusooka, Savy Bou)\n8432 - Closing the Follow-Up Gap: In-Person and Virtual Mentorship for Health Workforce Development in Ethiopia (Robel Tezera Zegeye)\n8037 - Co-designing Context-Aware Climate-Health Digital Decision Support with Community Intelligence (Mitali Ayyangar, Wanjiru Waruiru)","sp":[{"n":"Rizma Adlia Syakurah","a":"Universitas Sriwijaya","b":"Rizma Adlia Syakurah is a family physician, public health researcher, and lecturer at Universitas Sriwijaya, Indonesia. Her work focuses on digital health equity, primary care, mental health, and responsible AI implementation. She is currently involved in developing and evaluating an AI-supported digital safe space for university students, with particular attention to safeguarding, human oversight, and implementation in resource-constrained settings."},{"n":"Hira Fareed","a":"TB-AI Inc.","b":"Medical Doctor, MBBS, FCPS MS, Healthcare Management & Policy PhD Candidate, Digital Health Public Health Officer, Sindh Govt Focus Areas: TB, HIV, Dengue, Malaria CEO and Founder TB-AI Inc."},{"n":"Azka Aghnianuri","a":"Summit Institute for Development","b":"Azka Aghnianuri is a health informatics professional with a background in midwifery and public health, specializing in digital health interoperability and health information systems. She has over five years of experience in digital health, including electronic medical record implementation, health data interoperability, and the development of FHIR-based digital health solutions. At the Summit Institute for Development (SID), she works on FHIR-based…"},{"n":"Rina Pertiwi","a":"Summit Institute for Development","b":"Rina Pertiwi is a Research Assosiate at the Summit Institute for Development (SID), an Indonesian research organization advancing healthcare systems through digital innovation and evidence-based solutions. Her work focuses on digital health, artificial intelligence, maternal and child health, and health systems strengthening. She currently serves as Co-Lead of the KONEKSI-funded AI in Healthcare project, where she coordinates strategic planning,…"},{"n":"Lia Rosida","a":"Summit Institute for Development","b":"Lia Rosida is the Chief Operating Officer (COO) of the SUMMIT Institute for Development (SID), where she provides strategic leadership in organizational operations, partnerships, and the advancement of digital health innovations to strengthen primary healthcare systems in Indonesia. She has played a strategic role in the development and scale-up of digital health initiatives across SUMMIT’s portfolio. With over ten years of experience in project…"},{"n":"Mridul Chowdhury","a":"mPower Social Enterprises Limited","b":"Mridul Chowdhury is the Founder and Chief Executive Officer of mPower Social Enterprises Ltd., a Bangladesh-based social enterprise founded in 2008 that leverages technology, data, and human-centered design to address complex development challenges across health, agriculture, education, and livelihoods. A pioneer in the field of ICT for Development (ICT4D), Mridul has over two decades of experience in designing and scaling digital solutions that…"},{"n":"Abu Md. Akteruzzaman Bhuiyan","a":"mPower Social Enterprises Limited","b":"Dr. Akteruzzaman Bhuiyan is a digital health systems specialist who, since 2022, has served as Digital Health Advisor at mPower, following leadership roles at Pathfinder International and D.Net. His work centres on building country-owned, interoperable platforms that link OpenSRP, OpenMRS, DHIS2, SHR, and BRN/NID, translating policy goals into operational tools that extend reach, improve quality, and institutionalise data use. At mPower, he contributed…"},{"n":"Gabriela De Jesus Cipriano Flores","a":"Imperial College London","b":"Dr Gabriela Cipriano Flores (MD, MSc) is a Research Assistant at Imperial College London and part of The George Institute Women’s Health Group. Her work focuses on climate change and women’s health, including research on extreme heat, maternal haemodynamics, and policies to better protect women through the Heat in Pregnancy - India program."},{"n":"Sreevatsan Raghavan","a":"Translational Health Science and Technology Institute","b":"Dr Sreevatsan Raghavan is a research scientist in clinical and environmental epidemiology at THSTI in Faridabad. His work focuses on maternal and perinatal health, climate-related exposures, and pregnancy outcomes. He currently manages the HiP-India program, a multicentric study on extreme heat and maternal, fetal, lactation, and newborn health."},{"n":"Karthika Kumar","a":"The George Institute for Global Health","b":"Dr. Karthika Kumar (MBBS, MPH) is a Research Fellow at The George Institute. Her work explores how environmental stressors, infrastructure inequities, and social determinants shape the experiences and adaptive strategies of vulnerable populations, particularly pregnant and lactating women."},{"n":"Chanon Kongkamol","a":"Prince of Songkla Unviersity","b":"Chanon Kongkamol is an Associate Professor in the Division of Family and Preventive Medicine, Faculty of Medicine, Prince of Songkla University, Thailand. He serves as Director of the Division of Digital Innovation and Data Analytics, Faculty of Medicine, and as Assistant Director of the Research and Development Office, Prince of Songkla University. His academic and research work spans occupational and preventive medicine, ergonomics, public health,…"},{"n":"Apinya Chintrakul","a":"Prince of Songkla Unviersity","b":"Apinya Chintrakul supports clinical and health sciences research, with expertise in research methodology, data collection, statistical analysis, and the application of quantitative methods in medical research. She has contributed to multidisciplinary research in public health, clinical epidemiology, and occupational ergonomics at Prince of Songkla University."},{"n":"Boonsita Suebchana","a":"Prince of Songkla University, Thailand"},{"n":"Dosila Ogira","a":"Strathmore University Business School","b":"Dosila Ogira is a Doctoral Fellow at the Strathmore University Business School, where her research is part of the Digital Innovation and Diagnostics for Infectious Diseases in Africa (Di-DIDA) consortium. Her doctoral studies are also supported by the Initiative to Develop African Research Leaders (IDeAL) through the KEMRI studentship programme. Her work involves health policy, systems research, and digital innovation, with a focus on improving health…"},{"n":"Goh Chan Sing","a":"Hospital Seberang Jaya","b":"Goh Chan Sing received his Master of Pharmacy from International Medical University and Master of Informatics from Universiti Sains Malaysia. He is an avid software developer and has won multiple innovation awards in technology in the Ministry of Health and Private Sector. Including the 2nd Place in the Malaysian Ministry of Health Innovation Award 2023, Most Outstanding LEAN Healthcare Project, International LEAN Healthcare Conference 2025, and 1st…"},{"n":"Claudia Lopes","a":"Kuala Lumpur UNU-IIGH","b":"Dr Lopes has spent over 20 years in academia with positions at the Faculty of Psychology at the University of Coimbra (Portugal), Department of Psychological and Behavioural Science at the London School of Economics and Political Science (LSE), and Department of Politics and International Studies at the University of Cambridge (POLIS). Prior to joining UNU, she was an Affiliated Lecturer in Statistics and Methods at POLIS and a Lead Consultant in Big…"},{"n":"Shuvarthi Bhattacharjee","a":"University of Brighton","b":"Dr. Shuvarthi Bhattacharjee is a digital health researcher with expertise in healthy ageing, co-design, and user-centred technology development. His doctoral research explored older adults’ experiences with digital health technologies across the UK, examining how factors such as trust, autonomy, empathy, privacy, and security influence technology adoption. Using phenomenological and co-design approaches, his work aims to support the development of…"},{"n":"Yusuf Ajack Ibrahim","a":"Kenya National Public Health Institute (KNPHI)","b":"Yusuf is a Public Health Professional with extensive international experience in Monitoring & Evaluation, Data Management, Informatics, and Disease Surveillance. He holds a Master's degree in M&E from the University of Nairobi and is an Advanced Field Epidemiology Laboratory Program graduate, and I have dedicated my career to strengthening Health Information Systems. He has worked with organizations such as AFENET, WHO, the US CDC, the Polio Core…"},{"n":"Kat James","a":"Jacaranda Health","b":"Kat is the Head of Product at Jacaranda Health in Nairobi, Kenya, where she leads a team using data, digital health, and AI to improve maternal and newborn health outcomes across sub-Saharan Africa. Her work spans Jacaranda's PROMPTS, MENTORS, and Delta platforms, alongside prior roles with Dimagi, VillageReach, and the World Bank."},{"n":"Animesh Biswas","a":"MIS, DGHS","b":"Animesh Biswas is a Health Information Specialist with the Management Information System (MIS), Directorate General of Health Services (DGHS), Ministry of Health and Family Welfare, Bangladesh. He has more than seven years of experience in designing, implementing, and strengthening national digital health information systems, with expertise in DHIS2, interoperability, health data integration, data quality, digital dashboards, and routine health…"},{"n":"Silvia Alvinia","a":"OUCRU","b":"Silvia Alvinia is a Biomedical Engineering graduate focused on leveraging data for impactful solutions within health information systems. She currently serves as the Informatics and Dashboard Officer for the SPHERES project by OUCRU Indonesia. Her experience in digital health includes standardizing health data, developing APIs, creating technical guidelines, and training trainers for national health data interoperability."},{"n":"Amos Zikusooka","a":"UNICEF Cambodia Country Office","b":"Amos Zikusooka Amos Zikusooka is a Social and Behaviour Change (SBC) Specialist with more than 20 years of experience designing and implementing evidence-based community engagement, health promotion, and systems strengthening programmes across Africa and Asia. His expertise spans behavioural science, risk communication and community engagement (RCCE), capacity development, digital learning, monitoring and evaluation, and primary health care (PHC)…"},{"n":"Savy Bou","a":"UNICEF Cambodia Country Office","b":"Bou Savy, MPH, is a Health and Social and Behavioral Change (SBC) specialist with over 20 years of experience working with UNICEF and development partners to improve maternal, newborn, child, and adolescent health, nutrition, HIV prevention, and child rights outcomes in Cambodia. She has extensive expertise in SBC strategy development, programme implementation, monitoring and evaluation, community engagement, capacity strengthening, and learning…"},{"n":"Robel Tezera Zegeye","a":"JSI","b":"Robel Tezera Zegeye (PhD) is an expert in health professions education, instructional and eLearning design. He holds master’s degrees in Health Informatics and Health Professional Education, and a PhD in Public Health. His research focuses on health professional education and public health informatics. He is currently serving as a Senior Advisor for Human Resources for Health (HRH)-Blended Learning with the JSI/SSD Project in Ethiopia."}]},{"id":"s211","t":"Qualcomm Spotlight Session: Edge AI for Impact: Bringing Intelligence Closer to People","d":"2026-12-03","s":"11:15","e":"12:15","tags":["Spotlight Session","Hybrid Livestream","Sponsored Session"],"fmt":"Spotlight Session","theme":"","mode":"Hybrid Livestream","desc":"","sp":[{"n":"Sharon Alalouf","a":"Qualcomm","b":"Sharon Alalouf is a Regional Business Development Director driving strategic growth and market development across APAC. Her work spans AI infrastructure, Edge AI, Autonomous Networks, IoT and next-generation connected technologies, translating technology innovation into new markets and business opportunities. She connects customers, partners, governments, and technology ecosystems to build strategic collaborations…"},{"n":"Surajit Nundy","a":"Raxa Health","b":"Surajit Nundy is a physician, a neuroscientist, and the founder of Raxa, where he leads the development of privacy-centric, on-device AI architectures and digital health infrastructure. He focuses on edge AI, local-first data systems, and user data sovereignty in healthcare. An MD, PhD, and Harvard MPH trained at Mass General/Harvard Medical School, he is published in journals including BMJ , NEJM and Nature .…"},{"n":"SV Krishnan","a":"HearSight Audio Vision Private Limited","b":"SV Krishnan is a serial social impact entrepreneur and the Co-founder and CEO of HearSight Audio Vision Pvt. Ltd., where he is leading the development of an assistive wearable device that enables persons with visual impairement to navigate independently. Drawing on over 15 years of working closely with blind people, he is building technology shaped around their real, everyday use cases. Krishnan’s work is driven by…"},{"n":"Ittichai Phoomsirivilai","a":"GreenIO Company Limited","b":"Ittichai Phoomsirivilai is the CEO and Founder of GreenIO, a technology company specializing in Edge AI, AI on Device, IoT, and intelligent digital solutions for healthcare, healthy aging, sustainability, and smart communities. With a background in software engineering and a passion for technology for social good, Ittichai leads the development of privacy-preserving AI solutions that operate directly on local…"}]},{"id":"s212","t":"UNICEF Sponsored Breakout: Launching WHO SMART Guidelines Implementation Support Tools and Resources","d":"2026-12-03","s":"11:15","e":"12:15","tags":["Sponsored Breakout","In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s56","t":"Discovery Stage: Digital health governance and quality of care","d":"2026-12-03","s":"11:45","e":"12:15","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Two short presentations on digital health governance and quality of care: the launch of the State of Digital Health Report 2026 and evidence on telemedicine quality in Rwanda.\n\nPresentations in this session:\n8549 - Introducing the State of Digital Health Report 2026 (Melissa Cederqvist Njihia)\n7463 - Telemedicine at Scale in Rwanda: Evidence from a Standardized Patient Audit Comparing Quality, Efficiency, and Provider-Patient Communication in Virtual and In-Person Care (Piero Mazimpaka Irakiza, Francine Uwamahoro)","sp":[{"n":"Melissa Cederqvist Njihia","a":"WHO","b":"Melissa Cederqvist Njihia is a Technical Officer at the World Health Organization (WHO) in Geneva, where she leads the Global Initiative on Digital Health (GIDH). She has over 13 years of experience in global public health, digital health implementation, health systems strengthening, and strategic partnerships. Before joining WHO, she worked with UNICEF and other international organizations,…"},{"n":"Piero Mazimpaka Irakiza","a":"Ministry of Health","b":"Piero Mazimpaka Irakiza is a Data Scientist, Biostatistician, and Digital Health Systems specialist working with Fionet Inc. and seconded to Rwanda’s Ministry of Health through the National Health Intelligence Centre. His work focuses on strengthening health systems through data integration, digital health evaluation, automated analytics, dashboards, surveillance support, and evidence-informed decision-making. He has experience working with routine…"},{"n":"Francine Uwamahoro","a":"University of Rwanda","b":"Francine Uwamahoro is a Health Informatics professional with strong experience in digital health systems, health data management, data standardization, data quality improvement, user support, and implementation-oriented system design. She is currently a Fellow at Rwanda Biomedical Center, where she contributes to the standardization of health data, strengthening of structured health information systems, documentation of data elements, and improvement…"}]},{"id":"s57","t":"Digital Governance for Maternal and Child Health: Leveraging Digital Public Infrastructure for Accountable, Integrated and Scalable Government Systems","d":"2026-12-03","s":"12:25","e":"13:25","tags":["Pre-formed Panel","Governance and Digital Health at Scale","In-person"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"In many low- and middle-income countries, maternal health programmes miss eligible women because enrolment relies on fragmented paperwork and on women applying themselves. This panel describes how the Government of Rajasthan, India, used digital public infrastructure to change how maternity cash benefits are delivered, linking routine maternal health services, identity systems and payments so eligible women are identified and enrolled automatically. Speakers from the Government of Rajasthan, IPE Global and the Children's Investment Fund Foundation share how the model was built, the governance and accountability it relies on, and what other governments can adapt.","sp":[{"n":"Punam IAS","a":"Government of Rajasthan","b":"Ms. Punam, IAS, a 2005-batch Indian Administrative Service officer of the Rajasthan cadre, currently serves as Secretary to the Government, Women & Child Development Department and Panchayati Raj (Women & Child Development) Department, Government of Rajasthan. She holds a B.Sc. in Electronics & Communications and brings over two decades of distinguished experience in public administration. Over the course of her career, she has held several key…"},{"n":"Raghwesh Ranjan","a":"IPE Global","b":"Raghwesh Ranjan is the Senior Director at IPE Global. A social change enthusiast and systems thinker, he excels in designing innovative solutions that unite communities and governments to address complex developmental challenges. He has pioneered several transformative initiatives, particularly to enhance the lives of girls and women. Ranjan recently led a Cash+ intervention to strengthen women's and children's nutrition in Rajasthan. He studied…"},{"n":"Hemang Shah","a":"Children's Investment Fund Foundation","b":"Dr. Hemang Shah is a public health and management professional leading the Health and Nutrition portfolio for the Children’s Investment Fund Foundation (CIFF) in India—the world’s largest philanthropic organization focused on improving the lives of children and adolescents. A systems-change leader with over 15 years of experience, Dr. Shah has advanced maternal, child health, and nutrition across India by designing, implementing, and monitoring…"}]},{"id":"s244","t":"Discovery Stage: A Shared Vision for Digital Health: The Global Strategy 2028–2033","d":"2026-12-03","s":"12:25","e":"12:55","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"This session presents the draft Global Strategy on Digital Health 2028–2033 and its four strategic objectives, ahead of consideration by EB160 and WHA80. It also looks at how the proposed resolutions on health data interoperability and on trustworthy AI for health would support implementation in countries.\n\nHosted by the WHO Department of Digital Health and Innovation.","sp":[{"n":"Dessislava Dimitrova","a":"World Health Organization (WHO)","b":""},{"n":"Diana Estevez","a":"World Health Organization (WHO)","b":""},{"n":"Melanie Bertram","a":"World Health Organization (WHO)","b":""}]},{"id":"s213","t":"Google for Health Spotlight Session: From Black Box to Open Weights: Empowering Global Health Innovation with Open Models","d":"2026-12-03","s":"12:25","e":"13:25","tags":["Spotlight Session","Hybrid Livestream","Sponsored Session"],"fmt":"Spotlight Session","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s214","t":"Individual Presentations: Gender, Leadership and the Frontline Digital Health Workforce","d":"2026-12-03","s":"12:25","e":"13:25","tags":["Individual Presentation","Workforce Capacity and Leadership for the Digital Future","In-person"],"fmt":"Individual Presentation","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"In-person","desc":"Five presentations on gender, leadership and the frontline digital health workforce, looking at the barriers women face in digital health roles, the digital capacity of women community health workers, women's leadership programmes, training for private pharmacy staff in Kenya, and Kenya's Ministry of Health Virtual Academy for workforce learning.\n\nPresentations in this session:\n7539 - Women's Workforce Participation Barriers In Digital Health and Health Information System in Ethiopia's (Selamawit Teklehaimanot, Hiwot Belay)\n7636 - The Last Mile Has a Gender: Digital Capacity and the Women Who Carry Community Health Systems (Bhumika Piya)\n7894 - Collaborative Leadership for Digital Health Transformation: Lessons from a Regional Women's Leadership Ecosystem in Latin America and the Caribbean (Joseline Carías - Galeano)\n8584 - Making the invisible visible: scaling Kenya's private pharmacy workforce through hybrid training and digital reporting. Empowering Kenya's Health Workforce: Scaling Capacity and Digital Visibility Through Hybrid Training Models (Danielson Kennedy, Rose Nzyoka)","sp":[{"n":"Selamawit Teklehaimanot","a":"JSI","b":"Author Biography\n\nSelamawit Meressa Teklehaimanot is a Senior Monitoring, Evaluation, Learning, and Gender Specialist at JSI's Data Use Partnership (DUP 2.0) funded Gates Foundation in Ethiopia, with over 14 years of professional experience in public health, including more than eight years leading monitoring, evaluation, learning, digital health, health information systems, and gender integration initiatives.\n\nShe has extensive expertise in designing…"},{"n":"Hiwot Belay","a":"JSI","b":""},{"n":"Bhumika Piya","a":"CARE Nepal","b":"Bhumika Piya, PhD, is a Senior MEAL Technical Advisor on the Program Strategy and Innovation’s (PSI) Evidence and Learning team at CARE. In this role, she leads the design and delivery of high-quality MEAL across CARE’s Global Health and Women and Girls portfolios. She leverages monitoring and evaluation data to generate insights and evidence to inform program design, learning, and strategic decision-making. Her work is grounded in innovative methodologies,…"},{"n":"Joseline Carías - Galeano","a":"RECAINSA - NGO","b":"Joseline Carías Galeano is an international consultant, speaker, mentor, and project management expert recognized for her leadership in digital health across the globe. She currently serves as Executive Director of RECAINSA, one of the region’s most influential digital health networks in LAC, leading initiatives that support the development and implementation of national and regional digital health strategies.\n\nShe is also co-creator of innovative…"},{"n":"Danielson Kennedy","a":"inSupply Health","b":""},{"n":"Rose Nzyoka","a":"inSupply Health","b":""},{"n":"Vivian Korir","a":"FAST Elevate Africa","b":"Vivian Korir is a Workforce Transformation, Digital Health, and EdTech leader with over 15 years of experience designing and leading digital health workforce development programmes across 13+ low- and middle-income countries in Sub-Saharan Africa. She is the Founder of FAST Elevate Africa, a Pan-African social enterprise advancing digitally enabled, future-ready health workforces. Vivian is a co-author of the Global Community Health Worker Foundational…"}]},{"id":"s215","t":"Discovery Stage: AI and data quality in clinical care","d":"2026-12-03","s":"12:55","e":"13:25","tags":["Discovery Stage","AI for Health","In-person"],"fmt":"Discovery Stage","theme":"AI for Health","mode":"In-person","desc":"Three short presentations on making AI work in health care: a prospective evaluation of large language models in a live outpatient clinic in Kano, Nigeria, a data quality assessment of Zambia's national HIV electronic health records for trustworthy AI, and scaling AI-driven personalised prevention and behaviour change beyond pilots to millions of people.\n\nPresentations in this session:\n7807 - When LLMs Fall Short: Prospective Evidence from a Live Outpatient Clinic Evaluation in Kano, Nigeria (Tahir Buhari)\n7891 - A Multi-Facility Data Quality Assessment of Zambia's National HIV Electronic Health Records for Trustworthy and Equitable AI (Jacob Mutale, Innocent Chiboma, Mwansa Lumpa)\nBeyond AI Pilots: Scaling Personalized Prevention and Behavior Change to Millions (Ankur Teredesai, CueZen)","sp":[{"n":"Tahir Buhari","a":"eHealth Africa","b":"Tahir Buhari is a Senior Research Program Manager at eHealth Africa, based in Kano, Nigeria, where he leads AI and digital health research at the intersection of implementation science, frontline primary care, and health systems strengthening. He serves as Principal Investigator or Project Manager for a portfolio of AI studies funded by the Wellcome Trust, Bill & Melinda Gates Foundation, GAVI, and PharmAccess Foundation, with cumulative research…"},{"n":"Joe Phiri","a":"CIDRZ","b":"Dr. Joe Phiri is a Health Information Systems professional with over 12 years of experience across Zambia and Southern Africa. He currently serves as Strategic Information Manager – Health Information Systems at the Centre for Infectious Disease Research in Zambia (CIDRZ). He holds a PhD in Computing and Data Science, a Master of Science in Computer Science from the University of Zambia, and a Bachelor of Science in Computing from Greenwich University.\n\nOver…"},{"n":"Innocent Chiboma","a":"Ministry of Health, Ndeke House, Haile Selassie Avenue, P.O. Box 30205, Lusaka, Zambia","b":""},{"n":"Mwansa Lumpa","a":"Centre for Infectious Disease Research in Zambia (CIDRZ), Lusaka, Zambia","b":""},{"n":"Aaron Zimba","a":"School of Computing, Technology and Applied Sciences Artificial Intelligence and Predictive Analytics, ZCAS University, P.O Box 35243, Lusaka, Zambia","b":""},{"n":"Ankur Teredesai","a":"CueZen","b":"Ankur Teredesai is CEO of CueZen, a behavioral digital twin and AI health engagement company, and a tenured Professor of Computer Science and Systems at the University of Washington. He is a recipient of the Association for Computing Machinery Knowledge Discovery & Data Mining society’s prestigious Lifetime Outstanding Contributions award and was the co-general chair for KDD 2019 and Information Director prior to that. His research spans machine learning and healthcare AI, with 150+ peer-reviewed papers. He has the rare distinction of having not just published but also deployed real-world AI models as solutions across global health systems."}]},{"id":"s58","t":"Lunch Break","d":"2026-12-03","s":"13:25","e":"14:45","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s216","t":"World Diabetes Foundation Plenary, co-hosted by the World Bank: FHIR Adoption in LMICs: Country Experiences in Connected Primary Care","d":"2026-12-03","s":"14:45","e":"15:45","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[{"n":"Amanda Bendor","a":"World Bank Group","b":"Amanda Bendor is a global health professional with over 20 years of experience advancing digital health, health systems strengthening, and workforce development in low-resource settings. At the World Bank Group, she supports a range of digital health initiatives including advising countries on the development of digital health architecture, developing resources at the intersection of digital health and NCDs/mental…"},{"n":"Martin Greiffenberg","a":"World Diabetes Foundation","b":"Martin Greiffenberg is a digital health lead at the World Diabetes Foundation. He supports country partners to develop and scale digital health solutions. His focus is on sustainable implementation and building local capacity."},{"n":"Chaminda Weerabaddana","a":"Ministry of Health Sri Lanka","b":"Dr. Chaminda Weerabaddana is a passionate digital health practitioner and a specialist in Health Informatics at Sri Lanka’s Ministry of Health. He leads Sri Lanka’s National Electronic Health Record (NEHR) initiative and the country’s adoption of HL7 FHIR-based interoperability, advancing connected care through standards-based health information exchange. Having served in the Ministry since 2003, he combines…"},{"n":"Fred Hersch","a":"Open Health Stack Foundation","b":"Dr. Fred Hersch is a Senior Product Manager at the Google DeepMind Impact Accelerator, where he leads AI for Social Impact initiatives in global public health. A self-described \"Global Health Technologist,\" he is a medical doctor, social entrepreneur, and lapsed software engineer working at the intersection of health and technology since the early days of web-based telemedicine. Previously the Product Lead for Open…"},{"n":"Santiago Pesci","a":"Ministry of Health Buenos Aires","b":"Santiago Andrés Pesci is an economist and digital health strategist specializing in health information systems, digital transformation, and public sector innovation. As Chief of Staff at the Ministry of Health of Buenos Aires Province, he leads initiatives that strengthen digital health, interoperability, data governance, and integrated healthcare delivery."}]},{"id":"s245","t":"Discovery Stage: ADB's UHC PEERS Dialogue: From Digital Health Strategy to Scale","d":"2026-12-03","s":"15:45","e":"16:15","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Hosted by the Asian Development Bank.","sp":[]},{"id":"s59","t":"Tea Break","d":"2026-12-03","s":"15:45","e":"16:15","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s60","t":"AI for Mortality Surveillance and CRVS: Strengthening Mortality Data Across Africa and Southeast Asia","d":"2026-12-03","s":"16:15","e":"17:15","tags":["Pre-formed Panel","AI for Health","In-person"],"fmt":"Pre-formed Panel","theme":"AI for Health","mode":"In-person","desc":"Only about 42% of deaths worldwide are registered with a usable cause, and in the African and South-East Asian regions the figure can be as low as 4%. This panel looks at how AI is starting to strengthen mortality surveillance and civil registration across the whole process, from verbal autopsy interviews and cause-of-death determination to coding, data quality and use. It brings together work from Africa and Southeast Asia, including CODA, a tool that pairs voice-to-text interviewing with algorithms, and is part of Pillars, a south-south learning network on AI readiness convened by Vital Strategies. Speakers discuss early results and how the work aligns with WHO standards.","sp":[{"n":"Daniel Futerman","a":"Vital Strategies","b":"Daniel has over 15 years of experience as a technologist building and scaling digital health and AI solutions across Africa. With deep expertise in health systems architecture, responsible AI implementation, and multi-stakeholder program management, he brings a practical, evidence-based approach to advancing digital health in low- and middle-income country health systems. Daniel currently leads the CODA (Cause of Death Determination Assistant)…"},{"n":"Rangana Wadugedara","a":"Data for Health","b":"Dr. Rangana Wadugedara is a public health informatics professional and serves as Technical Consultant for Civil Registration and Vital Statistics (CRVS) and Country Manager for Sri Lanka under the Bloomberg Philanthropies Data for Health Initiative at Vital Strategies. His work focuses on digital transformation, cause-of-death data quality, and medico-legal death investigation. He led the implementation of Sri Lanka’s digital mortality information…"},{"n":"Wansa Paoin","a":"Thai Medical Informatics Association","b":"Wansa Paoin is President of the Thai Medical Informatics Association and Advisor to Thailand’s Ministry of Public Health (MOPH). He has worked for 30 years as an Associate Professor at Thammasat University, teaching surgery and medical informatics. Since 2008, he has headed the WHO Family of International Classifications Collaborating Center, Thailand, for ICD-10 and ICD-11. Since 2021, he has supported MOPH in developing Medical Certificate of Cause…"},{"n":"Pedro de Paula","a":"Vital Strategies","b":"Pedro do Carmo Baumgratz de Paula, LLB, M.Sc., Ph.D, is the Senior Vice President of Global Innovation at Vital Strategies, where he oversees the organization's strategy for integrating AI, data science, and digital health solutions across programs and partnerships in more than 70 countries. Pedro joined Vital Strategies in 2015 and founded its Brazil office in 2017, building a multidisciplinary team recognized for translating data into government…"},{"n":"Moderator - TBC","a":"WHO SEARO"}]},{"id":"s61","t":"Individual Presentations: Connecting Health Systems: National Interoperability in Africa","d":"2026-12-03","s":"16:15","e":"17:15","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on national interoperability in Africa, covering client registries, a national georegistry in Niger, Ethiopia's federated health information exchange and Kenya's Digital Health Superhighway.\n\nPresentations in this session:\n8765 - From Patient Identity to a National Health Client Registry: Building Digital Public Infrastructure for Trusted and AI-Ready Healthcare in Nigeria (Gibril Gomez)\n8167 - Beyond Fragmented Pilots: Institutionalizing a National Georegistry for Health in Niger (Bram Piot)\n7490 - From Point-to-Point Integration to an Interoperability Highway: Ethiopia's Journey Toward a Federated Health Information Exchange (Habib Bushira, Tewodros Kersie)\n8687 - Optimizing Health Information Exchange in Kenya's Digital Health Superhighway: Bridging the Gap from Community to Tertiary Care (Derick Lung'aho, Jeremiah Mumo, Ryan Nyotu Gitau)\n8696 - From Fragmentation to a Connected Health Ecosystem: Kenya’s Journey in Building the Digital Health Superhighway (Jeremiah Mumo)","sp":[{"n":"Gibril Gomez","a":"Public Health Information, Surveillance Solutions and Systems (PHIS3)","b":"Gibril Gomez is the Health Informatics Director at APIN Public Health Initiatives on the Public Health Information, Surveillance, Solutions and Systems (PHIS3) project, where he leads the design and implementation of national digital health solutions across Nigeria. Gibril has over a decade of experience in health informatics and health information systems, digital health architecture, digital public infrastructure and interoperability. Gibril's work…"},{"n":"Bram Piot","a":"Bluesquare","b":"With 25 years of experience in global health, Bram is a seasoned public health professional, working at the intersection of monitoring and evaluation, digital health, and development programs to improve health outcomes. Bram specializes in strengthening routine monitoring and health information systems to support informed decisions for public health practitioners, in particular for malaria and communicable disease surveillance programs. His extensive…"},{"n":"Habib Bushira","a":"JSI","b":"Habib Bushira Alfa is a Senior Digital Health Specialist and Interoperability Lead at JSI, serving as technical advisor to Ethiopia's Federal Ministry of Health, Digital Health Lead Executive Office. He leads the National Health Interoperability Highway, Ethiopia's initiative to replace fragmented point-to-point integrations with a governed, federated health information exchange aligned to OpenHIE, and co-developed the country's National Digital Health…"},{"n":"Tewodros Kersie","a":"MoH"},{"n":"Derick Lung'aho","a":"Medic Afya","b":"Derick is a digital health leader that has supported the architecting and national digitalisation efforts in community health service delivery for 6 ministries of health in Africa - Kenya, Uganda, Mali, Togo and Côte d'Ivoire. He has a background in computer science and a decade of experience in digital trasformation in health and currently seriving as Chief Programs Officer at Medic Afya"},{"n":"Jeremiah Mumo","a":"Ministry of Health, Kenya","b":"Dr. Jeremiah M. Mumo is Director of Digital Health and Informatics at the Digital Health Agency (DHA), Kenya, with more than 21 years of experience in health information systems, digital health transformation, data management, monitoring and evaluation, and health informatics. He has extensive experience in the design, development and implementation of integrated health information systems, electronic health records, health information exchange…"},{"n":"Ryan Nyotu Gitau","a":"Medic Afya","b":"Dr. Ryan Nyotu is a clinician, policy architect, and implementation strategist working at the intersection of care, data, and digital transformation in Africa. He is a Senior Fellow at the Centre for Health Al Research, Innovation, and Implementation, and the inaugural Head of the Division of Digital Health at Kenya's Ministry of Health and now currently serving as Executive Director at Medic Afya. He spearheaded the Digital Health Act, helped…"}]},{"id":"s217","t":"UNICEF Sponsored Breakout: From Roadmap to Financing: Aligning Partner Investment in National Digital Health","d":"2026-12-03","s":"16:15","e":"17:15","tags":["Sponsored Breakout","In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"Digital systems are not the goal. Better health outcomes, fairer access and services that keep running are. The financing question is a practical one: when a country decides what to prioritise, what to defer and what to carry on its own budget, how well does partner investment support those decisions? Opened by a government representative, this roundtable puts country decision makers first. Officials from health, finance and procurement explain how priorities are set, how trade-offs are weighed and what they ask of partners on coordination, alignment and predictable financing. Gavi, the World Bank and WHO then respond with the support available at each decision point, from roadmaps and costing to financing windows, including in fragile and humanitarian settings.\n\nThe conversation turns to the question countries raise most often: how today's investment is carried into tomorrow's government budget. Participants will consider progressive integration into national budgets, alternative public financing and private sector models, and the practical steps to explore them. The session closes on how governments and partners can monitor, learn from and remain accountable for these investments over time.\n\nParticipants will leave with a decision point map they can adapt at home, a clearer view of what countries ask of partners, and a commitment from each organisation. Building on the Call to Action agreed by Ministries of Health from 23 countries at the Digital Health for Immunisation workshop alongside GDHF 2025 in Nairobi, the session moves consensus from principle to practice.","sp":[{"n":"Sean Blaschke","a":"UNICEF","b":"Sean Blaschke is Chief of Digital Health at UNICEF, where he leads the organisation's global digital health portfolio across more than 100 countries and oversees delivery of the UNICEF Digital Health Strategy 2026-2030. Over twenty-five years in the field he has built and scaled national systems including Uganda's mTrac disease surveillance platform and mHero, deployed with health workers during the 2014 Ebola response in Liberia, and he co-established UNICEF's first country innovation unit. He coined the term \"pilotitis\" to describe the proliferation of digital health pilots that never reach national scale, and co-authored the peer-reviewed paper of the same name."},{"n":"Daniel Oyaole","a":"Gavi, the Vaccine Alliance","b":"Daniel Oyaole is a leader in global health and digital transformation, with over 15 years of experience shaping technology-enabled solutions that strengthen health systems and improve population health outcomes. As Senior Manager for Digital Health Information at Gavi, the Vaccine Alliance, he leads strategic investments, partnerships, and programmes that advance digital health transformation, enhance data-driven decision-making, and accelerate sustainable impact across countries. Drawing on expertise in digital health, artificial intelligence, data science, portfolio management, and precision public health, Daniel advises governments, development partners, and global institutions on strategy, governance, and digital innovation. He is recognised for designing and delivering high-impact interventions, convening diverse stakeholders around shared priorities, and translating investment and innovation into scalable solutions that expand equitable access to healthcare and strengthen health system resilience."},{"n":"Matthew Hulse","a":"The World Bank","b":"Matthew Hulse (Matt) is the Program Manager for Digital Health and AI at the World Bank Group. With diverse experience in embedded devices and digital communication technologies, he bridges the worlds of public policy and technology investment. He has worked worldwide on digital health, telecommunications access issues expanding digital and economic development, equal and affordable access, and lifesaving information for humanitarian assistance. At the World Bank Group he advises technology investments for health service delivery; as well as serving as a coordinator and focal point for various health, data, and digital information working groups. Matt champions inclusive digital development in partnership with market-driven investment and global public goods to advance accessible, open, and safe healthcare."},{"n":"Derrick Munene","a":"World Health Organization (WHO)","b":"Serving as Team Lead for Data and Digital Health Assessments, Planning and Partnerships of the Insights, Capacity and Operations Unit, in the Data, Digital Health, Analytics and AI (DDA) Department, of the Health Systems, Access and Data (HSD) Division at the World Health Organization, Geneva, Switzerland."},{"n":"Simukai Zizhou","a":"Ministry of Health and Child Care, Zimbabwe","b":"Dr. Simukai Zizhou is a Zimbabwean medical practitioner, public health specialist, and digital health leader. He is Director of Health Informatics at Zimbabwe's Ministry of Health and Child Care (since July 2020) and a lecturer in the Bioinformatics and Bioengineering Department at the University of Zimbabwe. With the Ministry since 1993, he spent over 14 years as Provincial Medical Director for Mashonaland East Province (2006–2020). He holds an MD from the University of Zimbabwe, a Master of Public Health, a Certificate in Applied Epidemiology, and a 2013 certificate in Monitoring and Evaluation from the University of the Witwatersrand. His focus areas include disease management, epidemiology, health informatics, program evaluation, palliative care, and public health consulting."}]},{"id":"s62","t":"‘Phone Wali Didi se Poocho’ (in Hindi it means ask the elder sister): Integrating Generative AI into Community Maternal Health Systems","d":"2026-12-03","s":"17:00","e":"17:05","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Phone Wali Didi se Poocho (\"ask the elder sister\") is an AI-enabled WhatsApp service developed by SNEHA with Project Tech4Dev for mothers in underserved urban communities in Maharashtra, India. Built on the open-source Glific platform, it offers trusted, pregnancy-stage-specific health information by voice and text in several languages, and helps frontline workers with follow-up, risk identification and service tracking. Drawing on three years of work in Bhiwandi, Malwani, Dharavi and Navi Mumbai, this talk covers how the platform went through four rounds of development based on feedback from women, ASHA workers and government, and what it takes to add generative AI to community health systems responsibly.","sp":[{"n":"Sweety Pathak","a":"Society for Nutrition, Education and Health Action - SNEHA","b":"Sweety Pathak is the Director of SNEHA’s Maternal and Child Health - Strategy and Implementation Programme. As a Commonwealth Scholar, she obtained a Master of Science in Public Health from the London School of Hygiene and Tropical Medicine, United Kingdom. Additionally, she earned a Master of Arts in Social Work, specialising in Family and Child Welfare, from the Tata Institute of Social Sciences, Mumbai. Sweety has approximately 20 years of…"}]},{"id":"s63","t":"Effectiveness of automated reminders and follow-up messages on post-discharge neonatal follow-up by community health workers","d":"2026-12-03","s":"17:05","e":"17:10","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"In India, high-risk newborns discharged from special newborn care units should receive scheduled home visits from ASHA workers, but delays in passing on discharge information often mean visits are missed during the riskiest period. This talk presents an approach from The Antara Foundation that uses existing government data to identify the responsible ASHA automatically and send WhatsApp reminders before each scheduled visit, without adding new staff, apps or reporting. The speaker shares the effect on follow-up rates and lessons for strengthening links between hospitals and community health workers.","sp":[{"n":"Anuj Ghera","a":"The Antara Foundation","b":"Anuj has over six years of experience driving programmes across education, environment, and public health. He currently works at The Antara Foundation, where he leads and supports evaluations of public health programmes, while also contributing to the development of data systems for programme monitoring and decision-making. His work focuses on using data and evidence to strengthen programme implementation, evaluate impact, and support data-driven…"}]},{"id":"s64","t":"A Production-Ready FHIR Interoperability Architecture for Integrating Community-Based Immunization Records into Indonesia's National Health Platform","d":"2026-12-03","s":"17:10","e":"17:15","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"Community health workers in Indonesia record large numbers of immunisations at Posyandu sessions in the ASIK app, but this data has sat outside the national electronic health record because it comes from community services rather than health facilities. This talk presents the design and production rollout of a FHIR-based architecture connecting ASIK to SATUSEHAT, Indonesia's national health platform. The speaker explains how community-generated records were brought into national patient histories so citizens can see complete immunisation records, and shares practical lessons for linking community health apps to national platforms using HL7 FHIR.","sp":[{"n":"Novalia Sugianti","a":"Castellum Digital Indonesia","b":"Novalia Sugianti is a Project Manager specializing in digital health interoperability and health information systems. She leads the delivery of national-scale digital health initiatives, working closely with multidisciplinary teams to design and implement production-ready interoperability solutions based on HL7 FHIR. Her experience includes managing the implementation of interoperability architectures that connect community-based health applications…"}]},{"id":"s65","t":"From Pilot to Provincial Scale: Institutionalizing an Open-Source Electronic Health Record System Across Rural Nepal Through Government Partnership an","d":"2026-12-03","s":"17:15","e":"17:20","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"In 2014, Nyaya Health Nepal introduced an open-source, Bahmni-based electronic health record at Bayalpata Hospital, a remote district hospital. Over the following decade, it grew into a government-owned platform supporting public hospitals across a province. This talk traces that journey, covering the partnership with government, governance arrangements, financing, and the technical and workforce changes needed along the way. The speakers share lessons for moving locally led digital health tools from donor-funded pilots into routine public health systems.","sp":[{"n":"Srijana Devkota Adhikari","a":"Nyaya Health Nepal","b":"Ms. Srijana Devkota Adhikari, MBA Director of Programs and Partnerships Nyaya Health Nepal https://nyayahealthnepal.org/ Ms. Srijana Devkota is a senior development leader with more than 20 years of experience leading health systems strengthening digital health transformation, strategic partnerships, resource mobilization, governance, and organizational development across Nepal. She currently serves as Director of Programs and Partnerships at Nyaya…"},{"n":"Dipak Thapa","a":"Nyaya Health Nepal","b":"Dipak Thapa Digital Health Architect and Health Information Systems Specialist Technical Presenter, Nyaya Health Nepal Dipak Thapa is a Digital Health Architect and Health Information Systems Specialist with more than ten years of experience designing, implementing, and scaling digital health systems in low- and middle-income countries. He is recognized for his expertise in electronic medical records, health information exchange, interoperability…"}]},{"id":"s66","t":"Advancing Data Sovereignty for Equitable Digital Transformation in Health Systems","d":"2026-12-03","s":"17:30","e":"18:30","tags":["Pre-formed Panel","Governance and Digital Health at Scale","Virtual"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"As countries speed up digital transformation in health, the way health data is governed has become a national priority. Health data is highly sensitive, and without trust and strong legal safeguards people may avoid digital health services, while the benefits of AI may end up concentrated in a few hands. This panel, convened by United Nations University, discusses health data sovereignty: the ability of nations and individuals to decide how health data is collected, stored, shared and used. Speakers look at how AI is changing governance, accountability and power in global health, and what countries can do to protect rights and public interest.","sp":[{"n":"Claudia Abreu Lopes","a":"United Nations University","b":"Dr. Claudia Abreu Lopes is a Research Lead in Digital Health at the United Nations University (UNU) Global Health, where she explores innovative approaches to addressing health inequities through research and policy. Her interdisciplinary background in behavioural science, research methods and public health was developed over two decades of experience in academia, NGOs and the United Nations to support her commitment to producing rigorous research with…"}]},{"id":"s218","t":"Designing Digital Campaign Payment Workflows: A Hands-On Workshop for Faster, Fairer, and More Accountable Payments","d":"2026-12-03","s":"17:30","e":"18:30","tags":["Interactive Workshop","Financing for Sustainability","Virtual"],"fmt":"Interactive Workshop","theme":"Financing for Sustainability","mode":"Virtual","desc":"Large health campaigns rely on thousands of temporary workers, yet payment processes often depend on paper lists, spreadsheets and manual attendance records, leading to errors, duplicates and late payments. In this hands-on workshop, co-facilitated by Dimagi and Cameroon's Expanded Programme on Immunization, participants map a complete digital campaign payment workflow using Cameroon's system as an example. They work through a sample scenario covering worker enrolment and identity checks, team assignment, attendance tracking, payment statements and review, and leave able to design a payment system that links programme and finance workflows.","sp":[{"n":"Ismaïla Diene","a":"Dimagi","b":"Ismaïla Diène is the Managing Director of the Solutions Division at Dimagi, focused on driving digital transformation in health systems across the world. With over 15 years of experience in software engineering, health information systems, and strategic partnerships, Ismaïla has played a pivotal role in implementing scalable and sustainable digital health solutions in countries like Burkina Faso, Ethiopia or Madagascar. His leadership has accelerated…"}]},{"id":"s67","t":"Malawi’s Digital Health Transformation: Governance and Digital Public Infrastructure for a Sustainable Health Ecosystem in a New Development Era","d":"2026-12-03","s":"17:30","e":"18:30","tags":["Pre-formed Panel","Governance and Digital Health at Scale","Virtual"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Malawi is moving from fragmented, disease-specific systems funded by external partners towards a government-led, standards-based and interoperable digital health ecosystem. This panel presents Malawi's experience, starting with a 25-year look at its health information systems, from paper reporting and early DHIS to the creation of the Ministry of Health's Digital Health Division, the National Digital Health Strategy and a national governance framework. Speakers discuss how digital public infrastructure for health supports service delivery, health security and data use, and how it prepares the country for AI adoption.","sp":[{"n":"Kennedy Kanyimbo","a":"Digital Health Division, Ministry of Health and Sanimation of Malawi"}]},{"id":"s68","t":"Scaling High-Risk Pregnancy Care in India: How a 'tech-plus-touch' Model Combining Classroom Training, LMS, and AI-Powered WhatsApp Support Strengthen","d":"2026-12-03","s":"17:30","e":"18:30","tags":["Interactive Workshop","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Interactive Workshop","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"In India, 20-30% of pregnancies are high risk and account for 75% of perinatal deaths and illness. ARMMAN, working with state and district governments in Telangana and Uttar Pradesh, runs a 'tech-plus-touch' training programme that builds the skills of auxiliary nurse midwives and medical officers to manage high-risk pregnancies and provide quality antenatal care. The model combines classroom training, a learning management app and AI-powered WhatsApp support. This workshop walks through how the programme works at scale, what results it has shown, and how other countries can adapt blended digital learning for frontline health workers.","sp":[{"n":"Anuja Jayaraman","a":"ARMMAN","b":"Dr. Anuja Jayaraman has over 15 years of experience in international development programs, policy-oriented qualitative and quantitative research, and has led the research, monitoring and evaluation, and information management functions. She has worked in the areas of income and non-income dimensions of well-being including poverty and health (maternal, child and adolescent health) in South Asia and Africa. At ARMMAN, she will take on the responsibility…"},{"n":"Amrita Mahale","a":"ARMMAN","b":"Amrita Mahale has over 15 years of experience in product management, digital innovation and strategy, including over 8 years in the social sector in the tech / AI for social impact space. Previously, Amrita was the Head of Ideation & Incubation at Wadhwani AI. Earlier in her career, she worked at organisations such as Google and Boston Consulting Group (BCG). She holds a B.Tech in Aerospace Engineering from IIT Bombay and a MS in Aeronautics &…"},{"n":"Shubalakshmi Iyer","a":"ARMMAN","b":"Dr. Shubalakshmi comes with a vast experience in the field of social development and public health, especially in RMNCH+A (Reproductive, Maternal, Newborn, Child and Adolescent Health) projects, communicable and non-communicable diseases, child undernutrition, local governance, livelihoods, vocational training and women and youth empowerment. She is skilled at strategic planning, team building, capacity building, monitoring and evaluation, stakeholder…"}]},{"id":"s69","t":"Does clinical decision-support change facility-level resource use? Evidence from Burkina Faso and implications for financing sustainability","d":"2026-12-03","s":"18:30","e":"18:35","tags":["Lightning Talk","Financing for Sustainability","Virtual"],"fmt":"Lightning Talk","theme":"Financing for Sustainability","mode":"Virtual","desc":"Burkina Faso's clinical decision support system for children's consultations, based on WHO's IMCI guidelines, has been rolled out to more than 90% of primary health facilities over a decade and is moving to full Ministry of Health ownership. While it has improved quality of care, little was known about its costs at scale. This talk presents an economic study from the Swiss Tropical and Public Health Institute on how the system affects resource use, including consultation costs and prescribing. The findings inform how governments can plan to finance decision support tools once donor support ends.","sp":[{"n":"Talia Salzmann Sekuboyina","a":"Swiss Tropical and Public Health Institute","b":"Talia Salzmann is a Digital Health Specialist at the Swiss Tropical and Public Health Institute (Swiss TPH). She conducts design, coordination and evaluation of digital health interventions for a range of international clients and is conducting doctoral research on long-term implementation and sustainability of CDSS. Before this she worked on digital tools for nutrition and cancer, on maternal and child health, migrant health and non-communicable…"}]},{"id":"s70","t":"Betting on Crisis: Why Digital Health Workforce Training in Sub-Saharan Africa Must Address Gambling-Related Suicide Risk","d":"2026-12-03","s":"18:35","e":"18:40","tags":["Lightning Talk","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Lightning Talk","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Mobile sports betting has grown rapidly across Sub-Saharan Africa, especially among young men. Globally, gambling disorder is one of the strongest independent predictors of suicidal thoughts, attempts and deaths, yet in the region this link is largely missing from clinical practice, policy and health worker training. This talk makes the case for adding gambling-related suicide risk to digital training platforms for health workers, setting out three gaps: frontline workers do not screen for gambling, suicide prevention curricula leave it out, and digital training platforms have not addressed it.","sp":[{"n":"Precious Adeyeye","a":"Slum and Rural Health Initiative","b":"Precious Adeyeye is a Research Officer at the Slum and Rural Health Initiative (SRHIN), a public health non-governmental organisation based in Nigeria, where she focuses on mental health research, community health interventions, and health equity across Sub-Saharan Africa. She holds a Bachelor's degree from Ladoke Akintola University of Technology, Ogbomoso, Nigeria. Precious brings hands-on experience in research design, data analysis, and manuscript…"}]},{"id":"s71","t":"Artificial Intelligence-Based Prediction of Opportunistic Infections Among Patients on Antiretroviral Therapy in Resource-Constrained Settings","d":"2026-12-03","s":"18:40","e":"18:45","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Opportunistic infections remain a major cause of illness and death among people living with HIV, and current prevention relies mostly on CD4 counts and symptoms, which often catch risk too late. This talk presents a study from Debre Markos University that trained and compared ten machine learning models to predict opportunistic infections using routine electronic medical record data from 32,812 adults on antiretroviral therapy across eight hospitals in Ethiopia's Amhara Region. The speaker shares which models performed best, how class imbalance was handled, and how such predictions could help clinicians in resource-constrained settings act earlier.","sp":[{"n":"Abraham Keffale","a":"Debre Markos University","b":"Abraham Keffale Mengistu is a Health Data Science researcher and Health Informatics professional at Debre Markos University, Ethiopia. His work focuses on applying artificial intelligence and machine learning to healthcare data, particularly electronic medical records, to support predictive analytics and clinical decision-making. His research interests include HIV/AIDS care, opportunistic infection prediction, and the development of interpretable…"}]},{"id":"s72","t":"The Excel problem: What 15 years of digital health investment didn't fix","d":"2026-12-03","s":"18:45","e":"18:50","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"PEPFAR and other investments made HIV programmes one of the strongest digital health systems in Africa, with electronic records, lab systems, logistics platforms and national reporting. Yet medicines were often still ordered through Excel, and decisions linking commodities, workforce and budgets relied on spreadsheets, emails and meetings. Drawing on inSupply Health's implementation experience, this talk argues that digital investment has outpaced changes in how governments make decisions. The speaker offers a decision-first test for judging whether a new digital health investment will improve government decisions or simply produce more data and dashboards.","sp":[{"n":"Rose Nzyoka","a":"InSupply Health","b":"Rose Nzyoka is a global health and systems strengthening leader with over 20 years of experience across sub-Saharan Africa (Kenya, South Sudan, Tanzania, Nigeria, Namibia, Zambia, South Africa, and Eswatini). She currently serves as the Country Director, Kenya with Insupply Health. Her previous roles have included Kenya Country director, Palladium,Chief of Party and Deputy Chief of Party on USAID strategic information bilateral projects among other…"}]},{"id":"s219","t":"Achieving Resilience: Operationalising Climate-Resilient Primary Healthcare Systems in Nigeria through a Human-Centered Digital Climate Health Vulnera","d":"2026-12-03","s":"19:00","e":"20:00","tags":["Interactive Workshop","Climate and Health","Virtual"],"fmt":"Interactive Workshop","theme":"Climate and Health","mode":"Virtual","desc":"Climate change is affecting how primary healthcare facilities operate, yet most health systems lack practical tools to assess facility-level climate risks. This session presents the Climate and Health Vulnerability Assessment Tool (CHAT), developed by eHealth Africa with Nigerian government partners. CHAT turns the WHO climate-resilient health systems framework into an interoperable mobile tool and has been used in 50 primary healthcare centres across five climate-vulnerable states. The presenters share how the tool was designed with health workers, what the assessments revealed about floods, droughts and heatwaves, and how governments are using the results to plan.","sp":[{"n":"David Akpan","a":"eHealth Africa","b":"David joined eHealth Africa in March 2022 as the Deputy Director, Programs and Impact, now the Partnerships and Programs Directorate. He oversees the coordination and administration of all new and ongoing projects/programs portfolios across Africa. He drives the program design, program implementation strategy, and designing research and evaluation methods.\n\nBefore joining eHA, David was the Technical Lead and Deputy Chief of Party for a $21.5 Million…"},{"n":"Dominic Gulak","a":"eHealth Africa","b":"Dominic Gulak is a Certified Project Management Professional (PMP®) and Associate Manager at eHealth Africa, with over eight years of experience in climate adaptation, digital health innovation, and health systems strengthening across Nigeria. Within eHealth Africa’s Climate Adaptation in Health, Food Security and Nutrition (CAHFSN) programme area, he has played a pivotal role in designing and implementing technology-driven solutions that enhance…"},{"n":"Edi Jeremiah","a":"eHealth Africa","b":"Edi Jeremiah is a public health and digital innovation specialist with extensive experience in strengthening health systems through technology-driven solutions. At eHealth Africa (eHA), he led the development and deployment of the Climate Health Vulnerability Assessment Tool (CHAT) - a pioneering digital adaptation of the WHO checklist that assesses and strengthens the climate resilience of primary healthcare facilities in Nigeria.\n\nHe brings immense…"}]},{"id":"s73","t":"Building Capacity for Interoperability: the AeHIN Community of Interoperability Labs","d":"2026-12-03","s":"19:00","e":"20:00","tags":["Pre-formed Panel","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Pre-formed Panel","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Achieving interoperable health information systems has proven difficult for many countries. The Asia eHealth Information Network, created by WHO in 2012, developed its 'Mind the GAPS, Fill the GAPS' framework to guide countries, and from it grew the Community of Interoperability Labs (COIL), a group of national labs that share knowledge and resources. This panel brings together lab leads from the Philippines, Bangladesh, Taiwan, Sri Lanka and Malaysia. They describe COIL's goals and ways of working, how the labs support standards adoption and testing in their countries, and what other regions can learn about building interoperability capacity together.","sp":[{"n":"Alvin Marcelo","a":"UPM Standards and Interoperability Lab","b":"Dr. Alvin B. Marcelo is a general and trauma surgeon by training. He currently serves as the president of the Asia-Pacific Association of Medical Informatics (APAMI), director-treasurer of the Asia eHealth Information Network (www.aehin.org), president of the Philippine Society for Digital Health (www.psdh.net), and director at the Asia OpenRAN Academy. He teaches surgery at the Philippine General Hospital and Medical Informatics Unit at the UP College…"},{"n":"B M Riazul Islam","a":"Directorate General of Health Services, MoHFW, Bangladesh","b":"Dr. B M Riazul Islam Current position: Deputy Chief (Medical), Health Information Unit, MIS, Directorate General of Health Services, MoHFW, Bangladesh"},{"n":"Chien-yeh Hsu","a":"National Taipei University of Nursing and Health Sciences and Taipei Medical University"},{"n":"Chaminda Weerabaddana","a":"Ministry of Health, Sri Lanka","b":"Specialist in Health Informatics"},{"n":"Azrin Zubir","a":"MHNexus Malaysia"},{"n":"Prapat Suriyaphol","a":"SIL-THailand","b":"Dr Prapat Suriyaphol is the head of the Standards and Interoperability Lab - Thailand."}]},{"id":"s74","t":"Market scoping and impact modeling for “best buys” in health innovation: an interactive workshop to validate top innovation priorities","d":"2026-12-03","s":"19:00","e":"20:00","tags":["Interactive Workshop","Governance and Digital Health at Scale","Virtual"],"fmt":"Interactive Workshop","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"UNICEF's Office of Innovation is identifying 'best buys' in health innovation: a focused set of 5-10 proven, scale-ready solutions with the greatest potential to reduce maternal and child deaths within 3-5 years. The approach uses UNICEF's 5D Innovation Framework, impact modelling and cost-effectiveness analysis to assess digital, frontier technology and service delivery solutions on their impact, fit with health systems, feasibility and equity. In this interactive workshop, participants help test and refine the shortlist and learn how to move from a crowded field of innovations to a defensible set of priorities.","sp":[{"n":"Anaswara Kovithal","a":"UNICEFs Office of Innovation","b":"Anaswara Kovithal is an Innovation Specialist (Market Scoping) at the UNICEF Office of Innovation in Stockholm, where she leads market scoping and evidence work to identify the innovations most likely to accelerate progress on maternal and child health and other SDG challenges. She has over a decade of experience in bringing innovations into public systems. She began on the ground in rural India, implementing assisted telemedicine, digital health and…"}]},{"id":"s76","t":"Reset Before You Scale: Re-Engineering a Digital Health Organization to Reduce Founder Dependence and Hold Quality","d":"2026-12-03","s":"19:00","e":"20:00","tags":["Interactive Workshop","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Interactive Workshop","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"As Intelehealth grew quickly, with revenue rising about 50% a year, its leaders concluded that the biggest risk to quality was their own organisational design. They launched RESET, a structured effort based on Dan Heath's framework for changing what is not working. This workshop shares what they found, including unclear ownership of end-to-end delivery, under-budgeted projects, product decisions driven by the loudest voice and too much knowledge held by individuals, and what they changed. Participants then use the same method to find the few changes that would most improve delivery in their own organisations as they grow.","sp":[{"n":"Neha Verma","a":"Intelehealth","b":"Neha is the Co-founder and CEO of Intelehealth, a telemedicine technology non-profit that delivers health services where there is no doctor. She is an entrepreneur and medical information engineer. She earned an MS in Applied Health Sciences and a PhD in Health Informatics from the Johns Hopkins University School of Medicine."}]},{"id":"s75","t":"Safety by Design: A Practical Method for Building Responsible Generative AI in Low-Resource Health Settings","d":"2026-12-03","s":"19:00","e":"20:00","tags":["Interactive Workshop","AI for Health","Virtual"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"Virtual","desc":"Generative AI is reaching health care faster than methods for making it safe, and the risk is highest in mental health. This workshop teaches a practical safety-by-design method developed while building BraveHeart AI, a youth mental health service in low-resource settings. It covers four components: grounding answers in a curated knowledge base, classifying user risk, keeping a human involved in high-risk cases, and evaluating safety affordably, along with the governance and referral arrangements each depends on. Participants apply the method to their own context and leave with a structured first draft of a safety plan.","sp":[{"n":"Owen Adeniyi","a":"Slum and Rural Health Initiative","b":"Owen Adeniyi Director of Creativity and Innovation, Slum and Rural Health Initiative (SRHIN) Owen Adeniyi leads the design and delivery of AI-driven health tools for low-resource settings at SRHIN, including BraveHeart AI. His work sits at the intersection of artificial intelligence, health equity, and communication, spanning product development, applied research, and communication strategy, and he leads a multidisciplinary team of engineers and…"},{"n":"Promise Taiwo","a":"Slum and Rural Health Initiative","b":"Promise Taiwo Senior Mental Health Programs Officer, SRHIN Promise Taiwo is a mental health communicator, public health professional, and youth-engagement leader with a Master's in Field Epidemiology and over five years implementing mental health programmes for children, adolescents, and young people. At SRHIN she leads youth-centred mental health projects, communication campaigns, and advocacy, including the BraveHeart Project, and serves as Secretary…"},{"n":"Ezekiel Oladejo","a":"Slum and Rural Health Initiative","b":"Ezekiel Oladejo AI/NLP Engineer, SRHIN AI for Low-Resource Public Health Application Centre Ezekiel Oladejo builds end-to-end machine-learning and NLP systems for mental health and maternal health in low-resource public health settings, from data pipelines and model training through deployment and evaluation, tailored for multilingual local datasets. He specialises in robust, interpretable, and ethical AI for risk prediction, decision support, and…"}]},{"id":"s77","t":"MaHealthBiasAudit: A Framework for Detecting, Attributing, and Mitigating Cross-Lingual Bias in Maternal-Health for Global South","d":"2026-12-03","s":"20:00","e":"20:05","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Maternal-health AI tools are being used in East Africa in languages they cannot reliably understand. This talk presents MaHealthBiasAudit, an audit of maternal-health question-answering systems in English, Luganda, Runyankore-Rukiga and Swahili, using a clinician-validated set of 3,694 question-answer pairs in each language. The study found high bias overall, with the largest gaps between English and the two Ugandan languages, especially on pre-eclampsia warning signs. The speaker explains where the bias comes from and shares a framework for detecting, tracing and reducing cross-lingual bias before tools reach pregnant women.","sp":[{"n":"Richard Kimera","a":"Mbarara University of Science and Technology","b":"Richard Kimera is an Assistant Lecturer and researcher at Mbarara University of Science and Technology, Uganda, who completed a postdoctoral research stay at the International Centre for Reproductive Health, Ghent University, Belgium. He continues his Postdoc studies at Makerere University, Uganda, under the Maternal Understanding through Language-Aware Multimodal AI in Uganda (MULAMU) Project. He holds a PhD in ICT Convergence from Handong Global…"}]},{"id":"s78","t":"Design and Implementation of A DHIS2 Tracker for Inpatient Neonatal services in Kenya","d":"2026-12-03","s":"20:05","e":"20:10","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Neonatal data in Kenya has been split across paper records and parallel digital tools, limiting data quality and government ownership. This talk presents the design and scale-up of a DHIS2 tracker for newborn inpatient care built into the Kenya Health Information System through the Clinical Information Network. A Ministry of Health technical working group harmonised 204 data elements and 47 indicators with national and WHO standards, and the tracker was co-designed with clinicians and health records staff. The speakers share how the project moved from a partner-led pilot to a government-led system and the lessons for other countries.","sp":[{"n":"George Mbevi","a":"KEMRI-Wellcome Trust","b":"George Mbevi is a Health Information Systems & Data Specialist at KEMRI–Wellcome Trust with over 10 years of experience in DHIS2, EMRs and health systems strengthening. He co-ordinates data systems for the Clinical Information Network (CIN) project, a learning health system across 20+ high-volume hospitals in Kenya. His current work focuses on implementing inpatient neonatal data systems and scaling digital health solutions into sustainable,…"},{"n":"Benard Wambu","a":"Programme Manager M&E/Health Systems Neonatal, Child and Child Health Section Ministry of Health,Kenya"},{"n":"Franklin Okech","a":"Kemri-Wellcome Trust"},{"n":"George Okello","a":"NEST360"},{"n":"Nancy Amayo","a":"Division of HIS,MOH Kenya"},{"n":"Josephine Karori","a":"NEST360 Kenya"}]},{"id":"s79","t":"Data Curation, Not Model Scale: Building a Culturally Grounded Clinical Knowledge Base for Substance Use Support in West African Pidgin","d":"2026-12-03","s":"20:10","e":"20:15","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"West African Pidgin is spoken by more than 75 million people but has no digitised clinical text. Young people in Nigeria, Ghana, Sierra Leone and Liberia seeking help for substance use find that AI health tools do not understand their language or local terms for drugs, and respond in a tone that feels stigmatising. This talk describes how the Slum and Rural Health Initiative built the first clinical knowledge base for substance use support in West African Pidgin, combining WHO and SAMHSA guidelines, African research, programme reports and structured community input. The speaker shares a low-cost method other teams can use for languages without clinical data.","sp":[{"n":"Uthman Babatunde","a":"Slum and Rural Health Initiative","b":"Dr. Uthman Babatunde is a Medical Doctor and Applied AI/ML Engineer based in Nigeria, specializing in responsible AI architectures for low-resource clinical environments. He serves as an Associate Research Scientist at the Slum and Rural Health Initiative (SRHIN) and a Pioneer AI Fellow at the ALPHA Center. His work bridges clinical diagnostics and technical infrastructure, focusing on safety guardrails, intent classification, and culturally adapted…"}]},{"id":"s80","t":"Quantifying Data Invisibility in the Global Digital Health Monitor 2023: Geographic Distribution, Socioeconomic Correlates, and Contextual Validity of","d":"2026-12-03","s":"20:15","e":"20:20","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"The Global Digital Health Monitor is WHO's main tool for benchmarking digital health maturity across 169 countries, but much of its country data is missing. This talk introduces a Data Invisibility Score that measures the share of indicators recorded as unavailable for each country. Using the 2023 data, with a focus on Africa, the speaker shows how missing data is distributed across regions, how it relates to national socioeconomic factors, and what it means for how the tool's findings are read. Participants will see missing data as a finding in its own right, with implications for global monitoring.","sp":[{"n":"Wisal Eltayeb","a":"University College Dublin","b":"Dr. Wisal Eltayeb is a medical doctor from Sudan and an MSc Public Health student at University College Dublin (UCD), Ireland. She has experience in clinical medicine, medical education, and public health. Her work has involved research and working in digital health initiatives, with a particular interest in health information systems, digital health governance, and strengthening healthcare delivery in low- and middle-income countries. She is…"}]},{"id":"s81","t":"Strengthening Governance and AI-Enabled Digital Health Systems for Child Mental Health Support in Insecurity-Affected Settings in Nigeria","d":"2026-12-03","s":"20:20","e":"20:25","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Insecurity in Nigeria has exposed many school-age children to violence and disrupted learning, with serious effects on their mental health, while child mental health services remain limited and fragmented. Using Nigeria as a case within a wider review of insecurity-affected settings, this talk looks at how governance frameworks and AI-enabled tools such as chatbots, digital screening and predictive analytics can support early identification of distress, access to information and timely referral. The speaker also covers the safeguards and governance needed to use these tools responsibly with children.","sp":[{"n":"Abolaji Dare","a":"SRHIN","b":"My name is Abolaji Dare Opeyemi, and I am a Public Health professional, entrepreneur, and researcher passionate about digital health, health systems strengthening, and improving health outcomes for vulnerable populations. My work focuses on maternal and child health, health governance, and the use of innovative technologies to address public health challenges in low-resource settings. I am the founder of The Hustle Clinic, where I support entrepreneurs…"}]},{"id":"s82","t":"From Registry to National Digital Infrastructure: Twelve Years of Scaling Pakistan's Electronic Immunization Registry","d":"2026-12-03","s":"20:25","e":"20:30","tags":["Lightning Talk","Governance and Digital Health at Scale","Virtual"],"fmt":"Lightning Talk","theme":"Governance and Digital Health at Scale","mode":"Virtual","desc":"Pakistan's Electronic Immunization Registry started as a district pilot in Sindh and became the country's first national registry. Built on individual records for children aged 0-23 months and pregnant women, it has added birth registration, immunisation decision support, two-way reminders, AI-based support for caregivers, predictive analytics and reporting. This talk traces twelve years of scale-up and shows how the registry moved beyond digitising records to support programme management, supervision and day-to-day decisions. The speakers share the governance, technical and operational requirements for making such systems part of routine immunisation programmes.","sp":[{"n":"Mariam Mehmood","a":"Grassroots Health, Education, and Developmnet Initiative","b":"Mariam Mehmood leads the design, development, and scale-up of innovative public health and social impact programs that advance health equity in complex settings. She brings a pragmatic, systems-oriented approach, guiding initiatives from concept to pilot to scale, while ensuring each phase is grounded in evidence, data analytics, and community insight. With over a decade of experience, Mariam has directed large-scale, multisectoral portfolios that…"},{"n":"Mubarak Taighoon Shah","a":"Grassroots Health, Education, and Development Initiative","b":"Dr. Mubarak Taighoon Shah is a global health implementation scientist and operational leader with over 17 years of experience designing and leading large-scale public health programs across diverse health systems in low- and middle-income countries. With a background in clinical pharmacy (PharmD), and an MPhil in Health Policy and Management from the Aga Khan University, he brings interdisciplinary expertise spanning immunization, cold chain logistics,…"}]},{"id":"s83","t":"FRONTLINE AI","d":"2026-12-03","s":"20:30","e":"20:35","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Frontline AI is a clinical decision support assistant delivered through WhatsApp that gives primary healthcare workers in Nigeria instant access to verified, evidence-based clinical guidance at the point of care. Health workers can ask questions by text or voice and receive answers aligned with national protocols, at any time. This talk covers how the tool was built into existing workflows, the clinical safety features it includes, and early lessons on designing AI support for community health extension workers, nurses and midwives in low-resource settings.","sp":[{"n":"Victor Daniel","a":"Havilah Strategy Consult Limited","b":"Victor Daniel is the Founder and CEO of Havilah Strategy Consult Limited, a management consulting firm specializing in health systems strengthening, public sector reform, and technology for impact across Nigeria and West Africa. He leads the development of innovative digital health solutions, including Frontline AI - a WhatsApp-based AI clinical decision support tool designed to empower frontline health workers at the last mile - and GeoMap-MCH, a…"},{"n":"Taiwo Onifade","a":"Havilah Strategy Consult Limited","b":"Taiwo is a dedicated public health professional and licensed pharmacist with over four years of experience in research, monitoring and evaluation, data analysis, and health systems strengthening. Passionate about leveraging digital health and artificial intelligence to strengthen healthcare delivery, particularly at the primary healthcare level. Core areas of expertise include research design, program implementation, data-driven decision-making,…"}]},{"id":"s84","t":"AI Is Listening in the Wrong Language: How Lived Experience Fixed the Dataset That Clinical AI Could Never Build","d":"2026-12-03","s":"20:35","e":"20:40","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"In Nigerian Pidgin, \"My body no gree me\" is a common way of describing depressive distress, but an AI model trained on English clinical data is unlikely to recognise it. This talk presents GENSCORE Pilot, a depression assessment tool built by the Slum and Rural Health Initiative using training data generated by people with lived experience of depression, including 432 hours of Pidgin audio. The speaker argues that community-generated language data improves data quality, and shows how this approach produced a dataset that adapting or translating existing clinical datasets could not.","sp":[{"n":"Promise Taiwo","a":"Slum and Rural Health Initiative","b":"Promise Taiwo is a public health professional, mental health communicator, researcher, and lived experience advocate with personal lived experience of depression. She serves as Senior Mental Health Programs Officer at Slum and Rural Health Initiative (SRHIN), Nigeria, where she leads youth-centered mental health programmes, strategic communication, and lived experience engagement initiatives. As Secretary of SRHIN's Lived Experience Working Group, she…"}]},{"id":"s233","t":"Institutionalising Cybersecurity Governance for Digital Health: Lessons from Sri Lanka's Public Health Sector","d":"2026-12-03","s":"20:40","e":"20:45","tags":["Lightning Talk","Cybersecurity, Resilience, and Continuity","Virtual"],"fmt":"Lightning Talk","theme":"Cybersecurity, Resilience, and Continuity","mode":"Virtual","desc":"As Sri Lanka moves more of its public health services onto digital systems under the National Digital Health Blueprint, the Ministry of Health has built an information and cybersecurity governance model for the whole public health sector. The model sets out leadership structures, roles, accountability and coordination across national, provincial, regional and institutional levels. This talk shares how it was designed and rolled out, the challenges of doing so in a multi-tiered public system, and practical lessons for other ministries of health.","sp":[{"n":"Sonali Apsara Lunuwila","a":"Ministry of Health, Sri Lanka","b":"Dr Sonali Apsara Lunuwila is a Board-Certified Specialist in Health Informatics serving in the Health Information Unit of the Ministry of Health, Sri Lanka, with over 15 years of experience in digital health across Sri Lanka and the United Kingdom. She holds an MD in Health Informatics and an MSc in Biomedical Informatics from the University of Colombo, an MBBS from the University of Ruhuna, and has completed a Fellowship in Digital Health at the…"}]},{"id":"s85","t":"Securing the Signal: A Threat-Model and Safeguard Architecture for AI-Driven Trauma Detection Systems in LMIC Health Settings","d":"2026-12-03","s":"20:45","e":"20:50","tags":["Lightning Talk","Cybersecurity, Resilience, and Continuity","Virtual"],"fmt":"Lightning Talk","theme":"Cybersecurity, Resilience, and Continuity","mode":"Virtual","desc":"AI tools that detect trauma and PTSD from speech and text could help screen people where psychiatrists are scarce, but they also create serious security and privacy risks. Recordings and transcripts identify people, and model outputs can be reverse-engineered to reveal sensitive traits a person never disclosed. This talk presents a threat model for trauma-detection AI in low- and middle-income countries, covering stored data on shared clinic devices, model inversion attacks and other risks, together with a safeguard architecture teams can use to audit and protect their own deployments.","sp":[{"n":"Elijah Adeyeye","a":"Elitech Hub","b":"Elijah Adeyeye is a cybersecurity researcher, behavioral scientist, and founder based in Abuja, Nigeria. He holds a Bachelor of Education in Guidance and Counselling with Mathematics from the University of Ibadan and is a certified Counselling Psychologist. His professional practice is built on a rare intersection: the technical depth of offensive and defensive security and the psychological insight of behavioral research. He is the founder and CEO of…"}]},{"id":"s86","t":"From data quality to digital health intelligence: building a community health data ecosystem in Burkina Faso.","d":"2026-12-03","s":"20:50","e":"20:55","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"Burkina Faso's first national diagnostic of community health data found large mismatches between paper registers, CommCare, RapidPro and DHIS2, with data completeness of about 20% before late 2024. This talk, presented by the Ministry of Health and Living Goods, describes how the country moved from fragmented community health reporting towards an integrated system that turns data into usable information. The speakers share the interventions that followed, including routine data quality reviews and improved interoperability, and the results so far.","sp":[{"n":"Mahamadi Tassembedo","a":"Ministry of Health Burkina faso","b":"Dr. Tassembedo is the director of community health in Burkina Faso. He has nearly 20 years of experience in the health care system, having held positions of increasing responsibility to the present day. He has also contributed as a consultant to the implementation of health programs in several African countries. Thanks to his leadership, Burkina Faso now has one of the most effective community health systems in the West African subregion."},{"n":"Armand BAMABARA","a":"Living Goods","b":"Armand Bambara is the Senior Digital Health Manager at Living Goods, where he supports the Ministry of Health in the digital transformation of community health. His experience in digital health makes him a key player in Burkina Faso’s digital ecosystem."}]},{"id":"s87","t":"Sustainable Internet Connectivity to Reach Last-Mile Communities: How the Digital Health Impact Accelerator (DHIA) is Supporting Country-Led Digital H","d":"2026-12-03","s":"20:55","e":"21:00","tags":["Lightning Talk","Financing for Sustainability","Virtual"],"fmt":"Lightning Talk","theme":"Financing for Sustainability","mode":"Virtual","desc":"Presented jointly by Zambia's Ministry of Health and UNICEF, this talk looks at how Zambia is closing the rural connectivity and power gaps that limit digital health. A national geospatial analysis of all 3,088 public health facilities found that most rural facilities are already within 4G coverage, so the main barrier is getting facilities connected and running, not building new networks. The speakers show how targeting a small number of high-reach facilities could bring digital access to most young children, and share early results from sustainable connectivity models supported by the Digital Health Impact Accelerator.","sp":[{"n":"Beenzu Muleya","a":"Zambia Ministry of Health","b":"Beenzu C. Muleya is a Senior ICT Officer (Software & Applications) at the Ministry of Health, Zambia, with nearly a decade of experience driving digital health transformation. She has led national initiatives in health information systems, digital infrastructure, and connectivity, including supporting the solarization and internet connectivity of more than 448 health facilities across Zambia. As Chairperson of the Digital Health Infrastructure…"},{"n":"Innocent Chiboma","a":"Zambia Ministry of Health","b":"A passionate digital health expert with over 18 years of experience designing, managing, and implementing national systems in collaboration with top international organizations. Possessing a proven track record of success in leadership, stakeholder engagement, and relationship building, I hold an MBA in Technology Management and a Bachelor of Science (Hons) in Computing."},{"n":"Anthony Waddell","a":"UNICEF"}]},{"id":"s90","t":"Documenting and Comparing Climate-Health Digital Interventions using WHO SMART Guidelines: An Interactive Co-Development Workshop","d":"2026-12-03","s":"21:00","e":"22:00","tags":["Interactive Workshop","Climate and Health","Virtual"],"fmt":"Interactive Workshop","theme":"Climate and Health","mode":"Virtual","desc":"Ministries of health building climate-resilient systems often struggle to define and document their digital interventions in a standard way. In this workshop, facilitated by WHO, WMO and PATH, participants use the WHO SMART Guidelines approach to define three core parts of a climate-health digital intervention: personas, workflows and minimum data sets. Participants can bring their own systems or ideas to work on, mapping user profiles for health workers and environmental analysts and the data that needs to flow between sectors. They leave able to turn climate-health concepts into structured, software-neutral requirements.","sp":[{"n":"Mathew Keks","a":"WHO","b":"10+ years driving global public sector innovation and systems change across the United Nations and the Australian Government ¦ Tackling global challenges through collaborative problem solving ¦ Delivering actionable, sustainable and human-centric insights ¦ Accelerating organisational capability and change using agile principles, systems and strategic design ¦ Demystifying innovative practice in the public sector and multilateral organizations"},{"n":"Joy Shumake-Guillemot","a":"WMO","b":"I am a global environmental health scientist focused on building partnerships and solutions to enhance public health policy and programming to address climate change, particularly in low and middle income countries. Specialties: Environmental Health Climate Adaptation Policy Climate information and Climate Services Climate & Health Risk Assessment Health Systems Sustainability Global Environmental Change International Development & Humanitarian Affairs"},{"n":"Heidi Good","a":"PATH","b":"Heidi Good has worked in the international digital health space for the past 20 years, driving social innovation partnerships that leverage emerging technologies for health in resource constrained contexts. She has led large-scale multi-country programs, built high-value cross-sectoral partnerships, and advanced trusted data-driven solutions that expand equity, accessibility, and resilience in communities around the world. Heidi works with communities,…"}]},{"id":"s88","t":"Medic Afya Emerging from the knowledge of Medic. A journey to Local Leadership for Local Impact","d":"2026-12-03","s":"21:00","e":"22:00","tags":["Pre-formed Panel","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Pre-formed Panel","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Localisation is widely discussed in global digital health but rarely shown in practice. This panel tells the story of how Medic Afya, a locally led and governed organisation, emerged from Medic, the global nonprofit that has supported community health information systems in Africa. Panellists from both organisations explain why the transition began and how it was designed, including governance, legal set-up, leadership, staff transition, transfer of knowledge and assets, and funding. They also discuss what changed for government partners and the hard parts of the process.","sp":[{"n":"Derick Lung'aho","a":"Medic Afya","b":"Derick is a digital health leader that has supported the architecting and national digitalisation efforts in community health service delivery for 6 ministries of health in Africa. He has a background in computer science and a decade of experience in digital health and currently seriving as Chief Programs Officer at Medic Afya"},{"n":"Ryan Nyotu","a":"Medic Afya","b":"Medic Afya ED"},{"n":"Shreya Bhatt","a":"Medic","b":"Medic co-ED"},{"n":"Jovia Tuhaise","a":"Medic Afya"},{"n":"Dykki Settle","b":"Board Member for both Medic and Medic Afya"},{"n":"Loukman Tidjani","a":"Medic Afya"}]},{"id":"s89","t":"Overcoming the Empathy and Access Barriers: Scaling Chronic Disease Self-Care in Africa Through Localized Generative AI and Human-in-the-Loop Coaching","d":"2026-12-03","s":"21:00","e":"22:00","tags":["Interactive Workshop","AI for Health","Virtual"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"Virtual","desc":"Chronic conditions such as hypertension, diabetes and obesity are rising across Africa faster than the clinical workforce. Human coaching alone cannot keep up, and most digital tools assume smartphones and reliable internet. This workshop presents mDoc Healthcare's model, which combines a localised generative AI assistant with human clinical coaches and reaches people through WhatsApp, SMS and USSD. Participants learn how mDoc divides work between AI and human coaches across text and voice channels, and how to apply this approach while keeping care safe and personal.","sp":[{"n":"Sarthak Arora","a":"mDoc Healthcare","b":"Sarthak Arora is a product leader working at the intersection of digital health, artificial intelligence, and human-centred design. He serves as Business Product Manager at mDoc, where he leads the development of product features across mDoc's digital care platform, including Kem, mDoc's AI-powered health coach. His work spans product strategy, feature discovery and delivery, and the translation of clinical and member needs into scalable digital…"},{"n":"George Orjin","a":"mDoc Healthcare","b":"Dr. George Orjih is a Nigerian physician and digital health professional working at the intersection of clinical care, artificial intelligence, and health systems innovation. He serves as Senior Clinical Associate at mDoc, where he contributes to the clinical safety, evaluation, and improvement of AI-enabled care, including Kem, mDoc’s AI-powered health coach. His work spans digital chronic disease management, conversational health data, clinical risk…"},{"n":"Chika Okeke","a":"mDoc Healthcare","b":"Chika Okeke is an Associate Product Manager who works with design, engineering, and business teams to turn user needs into products people rely on. She supports the product lifecycle from discovery through launch, including gathering requirements, prioritizing features, and tracking how releases perform."}]},{"id":"s91","t":"Integration of ICD-11 into Electronic Health Records: Results of the Chilean National Pilot Scheme","d":"2026-12-03","s":"22:00","e":"22:05","tags":["Lightning Talk","Interoperability and Digital Public Infrastructure","Virtual"],"fmt":"Lightning Talk","theme":"Interoperability and Digital Public Infrastructure","mode":"Virtual","desc":"ICD-11 was designed as a digital, interoperable resource, so clinical coding can become part of the health record instead of a separate administrative task. This talk shares results from Chile's first national pilot of ICD-11 for morbidity coding, run by the Ministry of Health, the Maule Health Service and the University of Talca. The project connected ICD-11 terminology services to clinical workflows using APIs and WHO's Embedded Coding Tool, and built a platform to support coding and analysis. The speaker shares the architecture used, results from the pilot and lessons for countries planning their own transition.","sp":[{"n":"Sergio Guinez-Molinos","a":"Universidad de Talca","b":"Computer Engineer and PhD in Medicine and Translational Research. Specialist in health information systems and interoperability; his main focus has been the design, development and implementation of digital health platforms both in academia and in health services and institutions. Founding member of the National Center for Health Information Systems (CENS) and the Digital Health Network of State Universities (RSDUE). He directs the Biomedical…"}]},{"id":"s92","t":"ENTERA: An Equity-Centered Digital Health Framework for Bilingual Breast Cancer Education and AI-Enabled Navigation Among Latina Women in Washington,","d":"2026-12-03","s":"22:05","e":"22:10","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Latina women in the United States face breast cancer disparities, including later diagnosis and limited access to culturally and linguistically appropriate support. In Washington, DC, barriers such as transport, changing contact details, language, limited digital access and mistrust make these gaps worse. This talk presents ENTERA, a bilingual framework combining Spanish-language breast health education, plain-language navigation of resources and AI-enabled support. The speaker explains how it was developed from a review of the evidence and interviews with experts, and what it shows about designing equitable digital health tools for underserved communities.","sp":[{"n":"Noheli Carrasco","a":"ENTERA","b":"Noheli Carrasco is the founder of ENTERA, a bilingual digital health framework designed to reduce breast cancer disparities among Latina women. She is an ARRT-certified radiation therapist with nearly a decade of experience in radiation oncology, working directly with cancer patients through treatment and survivorship. She also brings a background in Spanish-language broadcast media, including Telemundo 44 DC and La Jefa 700 radio, which shaped her…"}]},{"id":"s93","t":"Why Digital Health in Primary Care Starts With People, Not Platforms","d":"2026-12-03","s":"22:10","e":"22:15","tags":["Lightning Talk","Workforce Capacity and Leadership for the Digital Future","Virtual"],"fmt":"Lightning Talk","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"Virtual","desc":"Digital health projects in primary care often stall because the conditions for technology to work were never put in place. This talk shares findings from Naga City in the Philippines, where plans to modernise health data across 27 community health facilities met paper-based workflows, varied digital skills among frontline workers and a culture of reporting for compliance. Instead of starting with a tool, Ariadne Labs and partners mapped workflows, documented facility capacity, co-designed with midwives and community health workers, and built a long-term workforce strategy. The speaker shares a framework for developing the workforce alongside, not after, digital rollout.","sp":[{"n":"Janine Patricia Robredo","a":"Ariadne Labs","b":"Janine Patricia Robredo, MD, MBA, MSc, is a physician and public health professional from the Philippines, and is currently a Research Scientist at Ariadne Labs, a joint system for health system innovation at Harvard T.H. Chan School of Public Health and Brigham and Women's Hospital, where she leads research at the intersection of primary health care systems, digital health, and data-driven decision-making. She is the Principal Investigator of the…"}]},{"id":"s94","t":"Designing for Silence: Building Beep Health for a Country Where Mental Health Isn't Discussed","d":"2026-12-03","s":"22:15","e":"22:20","tags":["Lightning Talk","AI for Health","Virtual"],"fmt":"Lightning Talk","theme":"AI for Health","mode":"Virtual","desc":"Beep Health is a mental health platform built for a country where mental health is rarely discussed. It links people to support that fits their language, culture and needs, and offers anonymous, AI-powered first-contact spaces where someone can describe how they feel before they are ready to talk to another person. This talk explains why the team chose to design for silence: entry points that do not require people to name a condition or be seen. The speaker shows how that choice shapes the platform's AI guardrails, provider checks and business model, with lessons for any tool working where stigma is the main barrier to care.","sp":[{"n":"Ezinne Aso","a":"HSB Innovation Translation Lab","b":"Ezinne Aso is a healthcare strategist, futurist, and emerging thought leader dedicated to a singular mission: architecting equitable, resilient healthcare systems across global and underserved markets. Bridging clinical foundation with deep strategic expertise, Ezinne holds a Pharmacy degree from the University of Ibadan and an MBA in Healthcare, Technology, and Innovation from the Johns Hopkins Carey Business School. Her career sits uniquely at the…"}]},{"id":"s96","t":"A Human-Centered Framework for Evaluating Voice AI for Health in Low-Resource Settings","d":"2026-12-03","s":"22:30","e":"23:30","tags":["Interactive Workshop","AI for Health","Virtual"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"Virtual","desc":"Voice AI could widen access to health information where literacy, workforce shortages and many languages limit care, but most evaluations focus on technical performance, not on how people understand, trust and act on the advice. This workshop presents a human-centred evaluation framework developed by YUX Design through field studies with more than 400 people in Senegal and Rwanda. It combines cultural teaming, behavioural studies, clinical expert review and multilingual testing. Participants practise these methods and learn how to design evaluations that show whether a voice AI tool is ready for real-world public health use.","sp":[{"n":"OLUCHI AUDU","a":"YUX Design","b":"Oluchi Audu is a Senior Design Researcher at YUX and a Human-Computer Interaction researcher specializing in human-centered AI, digital health, and responsible AI evaluation. Her work focuses on designing and evaluating AI systems in low-resource and multilingual contexts, with recent research spanning Senegal, Rwanda, Kenya, and Nigeria. She currently leads research on human-centered evaluation methodologies for Voice-to-Voice AI systems in global…"},{"n":"Mame Coumba Ka","a":"YUX Design","b":"Mame Coumba Ka is a Machine Learning Engineer at YUX and the Product Owner of Kitala.ai, an open platform for human-centered AI evaluation. She specializes in designing and deploying AI systems for low-resource and multilingual contexts, with expertise spanning machine learning, MLOps, and AI product development. Mame co-leads YUX's Voice-to-Voice (V2V) AI evaluation initiative, where she oversees the technical infrastructure supporting large-scale…"},{"n":"Nafissatou Ly","a":"YUX Design","b":"Nafissatou Ly is a Data Analyst with experience in quantitative research and data analysis. Her work focuses on transforming complex research data into meaningful insights, with experience analyzing participant, interaction, and evaluation data in multilingual and cross-cultural research contexts."}]},{"id":"s97","t":"Ethical Implementation Readiness for AI Mental Health Chatbots in America Latina: A Desk-Based Governance Framework","d":"2026-12-03","s":"22:30","e":"23:30","tags":["Interactive Workshop","AI for Health","Virtual"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"Virtual","desc":"AI mental health chatbots are promoted as a way to widen access and reduce stigma where services are scarce, but in many low- and middle-income countries the conditions for safe use are not yet in place. This workshop presents a governance framework, based on desk research focused on Latin America, that assesses whether a setting is ready for these tools across seven areas: regulation, safety and human oversight, language and cultural fit, equity, local evidence, data privacy, and referral pathways and accountability. Participants learn to tell the difference between a chatbot being available and a setting being ready to use it ethically.","sp":[{"n":"Felipe Mejia-Medina","a":"ENOKE","b":"Felipe Mejía-Medina is a Colombian consultant, researcher, and educator working at the intersection of responsible artificial intelligence, digital health, and bioethics. He is the founder of ENOKE (formerly EKOnex), through which he supports organizations and researchers in using AI responsibly through consulting, training, and capacity building, with particular attention to Latin America and the Global South. Through ENOKE, he has designed and…"}]},{"id":"s95","t":"Scaling Digital Claims Management for Universal health Coverage: Evidence and Policy Perspectives from Ghana and Rwanda","d":"2026-12-03","s":"22:30","e":"23:30","tags":["Pre-formed Panel","Financing for Sustainability","Virtual"],"fmt":"Pre-formed Panel","theme":"Financing for Sustainability","mode":"Virtual","desc":"The performance of national health insurance claims systems is an important but often overlooked factor in financing universal health coverage. This panel shares evidence on digitising claims management from two national systems: Kwivuza under Rwanda's community-based health insurance scheme and ClaimIT under Ghana's National Health Insurance Scheme. In Rwanda, digitisation was linked to faster reimbursement, better claims quality and lower administrative costs for facilities. A comparison with Ghana then looks at why two similar systems produced different results. Speakers from the University of Ghana and Johns Hopkins discuss the policy lessons for countries digitising claims.","sp":[{"n":"Frances Baaba da-Costa Vroom","a":"University of Ghana"},{"n":"Yoko Shimada","a":"Johns hopkins Bloomberg School of Public Health"},{"n":"Smisha Agarwal","a":"Johns hopkins Bloomberg School of Public Health"}]},{"id":"s49","t":"Registration & Check In","d":"2026-12-03","s":"7:00","e":"17:00","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s51","t":"Opening Remarks","d":"2026-12-03","s":"8:00","e":"8:15","tags":["Plenary","Hybrid Livestream"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s208","t":"From Fragmentation to Ownership: Malawi’s Digital Health Transformation","d":"2026-12-03","s":"8:15","e":"9:00","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"Digital health in Malawi has evolved over more than two decades: it has evolved from early Health Management Information System (HMIS) and HIV treatment electronic medical records to a growing vision of nationally governed, interoperable digital public infrastructure for health. Yet the central challenge is not simply connecting software. It is deciding who sets priorities, safeguards patients, maintains systems, and pays for them when development financing changes.\n\nIn this moderated conversation, three leaders from Malawi’s Ministry of Health and Sanitation and a representative of Luke International will examine the choices behind the country’s digital transformation: establishing the Digital Health Division and governance mechanisms; aligning partners and technical standards; and building national capacity to sustain services.\n\nTwo concrete cases will anchor the discussion. First, Malawi’s efforts to harmonize the Malawi Healthcare Information System (MaHIS) and integrate antiretroviral therapy (ART) and advanced HIV disease (AHD) functionality while protecting continuity of clinical care. Second, early work to automate the flow of validated facility-level information from MaHIS to national HMIS/DHIS2 reporting.\n\nPanelists will distinguish achievements from unfinished work and explore the respective responsibilities of government, NGOs, development partners and commercial providers. What should governments own directly? Where can partners add value without creating dependence? And what governance, financing and skills are needed for a resilient system that improves quality of care?\n\nModerated by Mark Landry (WHO), the session offers lessons for countries moving from externally supported digital projects toward sustainable national public assets.","sp":[{"n":"Dr Andrew Gonani","a":"Ministry of Health and Sanitation of Malawi","b":"Dr Andrew Gonani directs the Quality Management Directorate and the Digital Health Division at Malawi’s Ministry of Health and Sanitation. He will examine how digital transformation can strengthen service quality, safeguard clinical continuity and maintain accountability as health information systems are consolidated."},{"n":"Dr Alinafe Mbewe","a":"Ministry of Health and Sanitation of Malawi","b":"Dr Alinafe Mbewe is Deputy Director of Malawi’s Digital Health Division. She will discuss government stewardship of digital health, including national governance, partner coordination, standards and the institutional foundations of sustainable digital public infrastructure."},{"n":"Kennedy Kanyimbo","a":"Ministry of Health and Sanitation of Malawi","b":"Kennedy Kanyimbo works in Malawi’s Digital Health Division as a Chief Officer. He will discuss how national governance is translated into interoperable architecture and implementation, drawing on MaHIS harmonization and efforts to strengthen automated routine reporting."},{"n":"Dr Joseph Wu","a":"Luke International","b":"Dr Joseph Wu is a public health and digital health specialist with nearly two decades of experience in Malawi. He holds a PhD in Informatics from the University of Oslo and an MSc in Epidemiology from National Taiwan University. He has worked at Luke International and has lived in Malawi since 2008; he currently serves as Acting Head of Programmes and Head of Research, Innovation, Monitoring and Evaluation. He has supported Malawi’s Ministry of Health and Sanitation in strengthening digital health governance, interoperable health information systems and One Health surveillance since 2008. His work connects government leadership, local technical capacity and implementation research to advance sustainable, nationally owned digital health infrastructure."},{"n":"Mark Landry","a":"World Health Organization","b":"Mark Landry is a Programme Officer with the World Health Organization. He will moderate a discussion of government leadership, health-system resilience and the changing responsibilities of digital health partners."}]},{"id":"s209","t":"Endless Plenary: AI Commons","d":"2026-12-03","s":"9:05","e":"9:50","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s210","t":"PATH Plenary: South-South Collaboration for Digital Health and AI: Why It Matters, How It Works, and What It Takes","d":"2026-12-03","s":"9:55","e":"10:40","tags":["Plenary","Hybrid Livestream","Sponsored Session"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[{"n":"Samuel Wambugu","a":"PATH","b":"Dr. Wambugu is a global digital health and informatics executive with extensive experience leading multi-country health initiatives across digital transformation, strategic information management, governance, risk management, compliance, cybersecurity, and health systems strengthening.\n\nHe currently serves as Chair of the Global Digital Health Network, providing strategic leadership to a global community advancing secure, inclusive, interoperable, and sustainable digital health systems.\n\nAt PATH, he leads work to strengthen national and sub-national health information systems in low-resource settings, supporting governments and partners on digital health policy, governance, interoperability, cybersecurity, workforce capacity, and implementation readiness. His work is grounded in building resilient, locally owned, and future-ready systems that improve public health outcomes.\n\nPreviously, as a Health Informatics Advisor at ICF, he led complex informatics initiatives focused on data governance, analytics, visualization, dissemination, and health information systems strengthening. Across his career, he has led large-scale surveys and informatics programs, advised national and international stakeholders, and contributed to peer-reviewed and technical publications.\n\nHis leadership centers on collaboration, responsible innovation, and AI-ready, people-centered digital health systems that deliver measurable and sustainable impact."}]},{"id":"s116","t":"Tea Break","d":"2026-12-04","s":"10:40","e":"11:15","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s251","theme":"","desc":"","sp":[],"t":"AHPSR / WHO DDA Sponsored Breakout: Leveraging DPIs for Digital Health Wallets: Planning for Resilience and Interoperability","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Sponsored Session","In-person"],"fmt":"Sponsored Session","mode":"In-person"},{"id":"s121","t":"Building the Financing Transition Framework- A Multi-Stakeholder Workshop on Sustaining Digital Health Investment in LMICs","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Interactive Workshop","Financing for Sustainability","In-person"],"fmt":"Interactive Workshop","theme":"Financing for Sustainability","mode":"In-person","desc":"Over the past decade, digital health systems in low- and middle-income countries have mostly been built with time-limited external funding, without the domestic financing needed to keep them running. Recent cuts, including changes to USAID's global health portfolio, have disrupted national health information, community health and supply chain systems in countries such as Kenya, Tanzania and Zambia. In this workshop, PATH guides participants in applying health financing concepts, such as revenue collection, pooling, purchasing and the split between capital and recurrent costs, to digital health. Together they build a framework for moving digital health investments to sustainable domestic financing.","sp":[{"n":"Manya Sachdeva","a":"PATH, India","b":"Manya Sachdeva is a public health professional with a Master of Public Health from Jindal Global University and a background in Applied Psychology. Her work spans health systems strengthening, digital health, global health policy, research, and implementation. She has contributed to projects with organizations including Sangath, MSF, CRY, and PATH, with experience in mixed-methods research, stakeholder engagement, health financing, and data analysis.…"},{"n":"Sameer Kanwar","a":"PATH","b":"Mr. Sameer Kanwar is Director, Regional Centre of Excellence in AI, Digital and Data for Asia-Pacific region at PATH."}]},{"id":"s123","t":"Digital Public Infrastructure for Health: Assessing Investment Needs and Implementation Priorities in Asia","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Interactive Workshop","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Interactive Workshop","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"This workshop builds on the AeHIN General Meeting 2026, where governments from 12 Asia-Pacific countries discussed national investment in digital public infrastructure for health. Using AeHIN's 'Mind the GAPS, Fill the GAPS' framework, participants identify common challenges across governance, architecture, people and programme management, and standards and interoperability. They then use the World Bank's Digital Health Blueprint Toolkit to work through investment planning, costing and prioritisation for their own country context.","sp":[{"n":"Jai Ganesh Udayasankaran","a":"Asia eHealth Information Network (AeHIN)","b":"Jai Ganesh Udayasankaran (Jai) is the Executive Director of the Asia eHealth Information Network (AeHIN). He brings more than 20 years of experience in the planning, procurement, and implementation of a wide range of digital health solutions, including web-based electronic medical records (EMR), picture archiving and communication systems (PACS), telehealth, and chronic disease management portals. Jai serves on several global bodies, including the…"},{"n":"Ali Habib","a":"The World Bank","b":"Ali Habib is a Senior Digital Health Specialist in the Digital Health and AI team at the World Bank's Global Health Department. In this role, he provides technical assistance to World Bank country teams and clients on the planning, designing, budgeting, and implementation of digital health aspects of World Bank-financed projects. He has led the development of knowledge products including the World Bank’s Digital Health Blueprint Toolkit, aimed at…"},{"n":"Fazilah binti Shaik Allaudin","a":"Asia eHealth Information Network (AeHIN)","b":"Previously the Penang State Health Director responsible for all health-related matters in the State. Prior, she has been leading digital health & innovation strategies in MOH Malaysia, and led the national EMR project. She has been part of the governing committee for AeHIN for more than 10 years. She holds an M.D. and an MBA in Healthcare Administration and is certified in Enterprise Architecture (TOGAF 9.0) and in Governance & Management of Enterprise…"}]},{"id":"s118","t":"Enabling Cardiovascular Health Outcomes with Scalable Digital Health Tools and Public Goods","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Pre-formed Panel","Governance and Digital Health at Scale","In-person"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"About 1.32 billion adults in low- and middle-income countries have hypertension, yet cardiovascular disease receives less than 2% of external health funding. This panel brings together Resolve to Save Lives, Medtronic LABS and WHO's Western Pacific Regional Office to share real-world evidence on how digital public goods and interoperable tools are improving cardiovascular care at scale. Speakers cover integration with government systems, regional coordination and cross-sector partnerships, and what it takes to deploy these free, open-standard tools without relying on donors.","sp":[{"n":"Danielle Cazabon","a":"Resolve to Save Lives","b":"Danielle Cazabon is a Senior Program Manager for Cardiovascular Health at Resolve to Save Lives. She has over a decade of experience in public health programming, implementation, and quality improvement and leads large-scale programs across diverse geographic regions through building collaborative relationships with partners across the globe to reach impact. She supports countries to scale up hypertension control with digital solutions, drawing on more…"},{"n":"Eshan Nanda","a":"Medtronic LABS","b":"Eshan Nanda is Chief Technologist at Medtronic LABS, where he leads the technology architecture behind SPICE, a certified digital public good for integrated primary care deployed across government and private health settings in South Asia and Africa. He brings deep expertise in building scalable, open-source digital health platforms for underserved communities in LMICs."},{"n":"TBD","a":"World Health Organization - Western Pacific Regional Office"}]},{"id":"s119","t":"Individual Presentations: Generative AI in Clinical Care: From Evidence to Real-World Implementation","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Individual Presentation","AI for Health","In-person"],"fmt":"Individual Presentation","theme":"AI for Health","mode":"In-person","desc":"Four presentations on generative AI in clinical care, from the first pragmatic randomised trials of AI clinical decision support in Kenya to deployments for health extension workers and AI-assisted documentation in Nigeria.\n\nPresentations in this session:\n7917 - Making AI Work in Frontline Care: Implementation Lessons from the First Pragmatic RCT of an LLM CDSS in African Primary Care (Robert Korom)\n8323 - Generative AI-enabled clinical decision support for primary care in Kenya: a pragmatic cluster-randomized controlled trial (Robert Korom)\n7889 - From Pilot to Scale-Up: Deploying HEP Assist, a Hybrid Localized GenAI Clinical Decision Support Tool for Community Health Workers in Ethiopia (Tamene Egnuni, Netsanet Wolde)\n8480 - Implementing Responsible AI-Powered Clinical Documentation and Clinical Decision Support within Nigeria’s National Electronic Medical Record: Early Findings from a Pilot Implementation Evaluation (Nonye Nwanya, Emmanuel Nnajiofor, Edidiong Udofia)","sp":[{"n":"Robert Korom","a":"Penda Health","b":"Dr. Robert Korom is Chief Medical Officer of Penda Health, a network of primary and urgent care centers in Nairobi, Kenya, serving more than 1,500 patients daily. Trained in Internal Medicine at Massachusetts General Hospital, he has led quality improvement and patient safety initiatives for over a decade in low-resource settings. At Penda, Dr. Korom has pioneered the integration of artificial intelligence into electronic medical records, designing and…"},{"n":"Ambrose Agweyu","a":"KEMRI-Wellcome Trust Research Programme","b":"Ambrose Agweyu is a paediatrician, and Professor of Global Health. He is currently Director of the Nairobi Programme and Deputy Director at the KEMRI-Wellcome Trust Research Programme in Kenya. He has led large, multisite randomised controlled trials, implementation research on translating evidence into routine practice, and efforts to improve quality of care using routine clinical data for audit and feedback. His recent work examines the safe and…"},{"n":"Paul Mwaniki","a":"KEMRI-Wellcome Trust Research Programme","b":"Paul Mwaniki is the lead statistician at the KEMRI–Wellcome Trust Research Programme in Nairobi. His work brings together medical statistics, health services research and machine learning to improve care. He has contributed to research on the quality of paediatric hospital care, including studies using patient records to assess whether quality improvement efforts change clinical practice. He has also worked on common data platforms that help hospitals…"},{"n":"Tamene Egnuni","a":"Last Mile Health","b":"Tamene Feyissa is a distinguished Information and Communication Technology (ICT) professional with approximately 24 years of experience. He holds a BSc in Computer Science and an MSc in Information Technology. Over the past nine years, Tamene has concentrated on the health sector, serving as a technical advisor and senior manager for digital health initiatives within Ethiopia's Ministry of Health and international NGOs. His notable achievements at the…"},{"n":"Netsanet Wolde","a":"Last Mile Health","b":"Netsanet is a Senior Digital Health Coordinator with over 7 years of experience in the design, development, and field deployment of digital health solutions across low-resource settings. At Last Mile Health (LMH), he leads full-lifecycle implementation support, capacity building, and quality assurance for mobile learning applications, including the HEP Assist AI and Extension Essentials tools for Health Extension Workers (HEWs). His work bridges…"},{"n":"Nonye Nwanya","a":"Palladium","b":"Nonye Nwanya is a seasoned digital health informatics specialist with over 10 years of industry experience in leading and developing innovative digital health solutions. With a background in computer science and information System, Nonye has demonstrated expertise in designing and implementing electronic medical record systems and digital health solutions for public health interventions, disease surveillance and evaluation programs. Throughout her…"},{"n":"Emmanuel Nnajiofor","a":"Palladium - Data.FI"},{"n":"Edidiong Udofia","a":"Palladium - Data.FI"},{"n":"Marium Hasan Rizvi","a":"Boston Healthcare Pvt. Limited","b":"Mariam Hasan Rizvi is a researcher and public health specialist based in Karachi, Pakistan, with a strong focus on digital health evaluation, implementation research, and health equity in low‑ and middle‑income countries (LMICs). She currently serves as Research Lead at Boston Health AI, where she designs and leads multi-center studies assessing the quality, usability, and acceptability of AI-powered clinical tools. These studies include comparative…"}]},{"id":"s122","t":"Individual Presentations: Governing Digital Health Transformation: Leadership, Frameworks and System Maturity","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Individual Presentation","Governance and Digital Health at Scale","In-person"],"fmt":"Individual Presentation","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"Five presentations on how countries govern digital health transformation, covering national governance frameworks in Rwanda, Zambia's health intelligence capability, governance in humanitarian settings in Yemen, digital health maturity in South-East Asia and measuring policy implementation for self-injectable contraception in Kenya.\n\nPresentations in this session:\n7729 - Operationalizing a National Digital Health Governance Framework in Rwanda (Christian Mazimpaka)\n8117 - Governance Before Technology: Lessons from Standing Up Zambia's Health Intelligence Capability. (Innocent Chiboma, Mwamulimba Mutinta, Ruth M'kala Chitalu)\n7884 - Strengthening Digital Health Governance in Humanitarian Settings: Lessons from Yemen’s Primary Health Care Digitalization Experience (Ameera Ba-Fadhel)\n8416 - Benchmarking digital health maturity across the WHO South-East Asia Region: evidence from the Global Digital Health Monitor, 2023 to 2024 (Mohamed Mustaf Ahmed)\n7577 - Digital health innovations for non-communicable diseases in underserved populations of Southeast Asian countries: a scoping review (Rabikah Yahya)","sp":[{"n":"Christian Mazimpaka","a":"Ministry of Health, Rwanda","b":"Dr. Christian Mazimpaka is a physician and public health specialist with over a decade of experience in health research, program management, and policy translation in Rwanda and across Africa. He serves as Digital Health Governance Advisor at Rwanda's Ministry of Health, where he reports to the Permanent Secretary and leads the coordination and oversight of digital health governance across the Ministry and its agencies. He also leads the Research and…"},{"n":"Innocent Chiboma","a":"Ministry of Health Zambia","b":"Innocent Chiboma is Principal ICT Officer for Digital Health at the Zambia Ministry of Health's ICT Directorate. He has worked for the Ministry of Health in the Digital Health since 2005. In more than 21 years leading Zambia's digital health governance and implementation work, he has overseen the growth of SmartCare — Zambia's homegrown national EHR, now on its SmartCare Pro release — alongside the country's broader digital health infrastructure. He…"},{"n":"Mwamulimba Mutinta","a":"Clinton Health Access Initiative","b":"Mwamulimba Aaron Mutinta is an ICT Specialist at the Clinton Health Access Initiative (CHAI) in Zambia, with well-versed experience in digital health, data, analytics and use. He has worked in Zambia's digital health space for more than 10 years, supporting the Ministry of Health across various digital health, data analytics, and data-use implementations. He currently leads CHAI's coordination support on the National Health Intelligence Centre (NHIC) —…"},{"n":"Ruth M'kala Chitalu","a":"Systems for Development (S4D)","b":"I am a dynamic, multi-sector professional with extensive experience in strategic communications, partnerships, project management, and business development. Over the past decade, I have worked across the NGO and international development sectors, contributing to initiatives in HIV programming, social marketing, digital health, and technology for development.Currently, I serve as the&nbsp;Project and Change Management Lead at S4D, where I support the…"},{"n":"Ameera Ba-Fadhel","a":"Menistry Of Public Health Yemen","b":"Dr. Ameera Ba-Fadhel is a public health leader, researcher, and health systems specialist from Yemen with more than 10 years of experience in health policy, primary health care, disease control, humanitarian response, and health system strengthening. She currently serves as Deputy Director of the Hadramout Health Office, where she contributes to strategic planning, health governance, program implementation, and coordination with national and…"},{"n":"Mohamed Mustaf Ahmed","a":"Chulalongkorn University","b":"Dr Mohamed Mustaf Ahmed is a medical doctor and data scientist based in Bangkok, where he is pursuing an MSc in Clinical Sciences (Global Health and Tropical Medicine) at Chulalongkorn University. He is an Academic Editor at PLOS Digital Health. His work centres on digital health, disease surveillance, and applied machine learning, with a focus on turning open health data into evidence that supports clinical and policy decisions. He has published…"},{"n":"Rabikah Yahya","a":"National University of Singapore - Centre for Research in Health Systems Performance"}]},{"id":"s120","t":"Navigating Challenges in Evaluating Health AI for Impact","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Interactive Workshop","AI for Health","In-person"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"In-person","desc":"AI tools are rapidly being developed and deployed in health systems. Incorporating evaluation into the product development loop reduces the risk of error-prone AI deployments that can harm real people. However, many organizations face practical challenges in designing evaluations that generate the evidence needed to responsibly inform policy and scale, or approach evaluation as an afterthought. Drawing on lessons from the Evidence for AI in Health (EVAH) initiative’s first request for proposals, where the Abdul Latif Jameel Poverty Action Lab (J-PAL) and the African Population and Health Research Center (APHRC) reviewed over 700 evaluation proposals, and bringing in expertise from the Agency Fund, this workshop helps researchers, AI developers, clinical partners and implementers work through challenges to evaluating health AI solutions.\nA brief expert-led fireside chat will first introduce recurring evaluation pitfalls. These include: (1) evaluating AI tools before sufficient technical validation or implementation readiness has been established; (2) developing incomplete theories of change that overlook implementation realities, human behavior, and pathways to scale; and (3) pursuing evaluation designs or measurement strategies that will not lead to credible results. Panelists will also touch on broader blockers to AI advancement in LMICs, such as data access and capacity.\nAgency Fund will then introduce a four-level evaluation framework for AI tools, leading participants through a live interactive demonstration of resources that can support organizations in evaluating their own AI tools. The tools are designed to bring domain experts like clinicians into the AI evaluation process, empowering them to improve health AI tools over time without relying solely on engineers.","sp":[{"n":"Aimee Barnes","a":"Abdul Latif Jameel Poverty Action Lab (J-PAL)","b":"Aimee Barnes is a Policy Manager at J-PAL Global where she manages the Health sector and oversees J-PAL’s role in the delivery of the Evidence for AI in Health (EVAH) initiative, a US$60 million commitment support real-world impact evaluations of AI-enabled health tools in low- and middle-income countries (LMICs). As a member of the Policy and Communications group, Aimee works with governments, NGOs, academics, technology partners, and others to build…"},{"n":"Agnes Kiragga","a":"APHRC","b":"Agnes Kiragga is Head of Data Science Program and Research Scientist at the African Population Health Research Council in Nairobi, Kenya. She previously worked as the Head of Statistics and data management at the Infectious Diseases Institute, College of Health Sciences at Makerere University in Kampala, Uganda. She has a Ph.D. in Statistics from Makerere University, Uganda/Indiana University, USA, and a Post-Doctoral certificate from a fellowship at…"},{"n":"Miranda Barasa","a":"APHRC","b":"Miranda Barasa is a Program Manager in the Data Science Program at the African Population and Health Research Center (APHRC), where she leads the implementation of multi-country initiatives advancing artificial intelligence (AI), data science, and digital health across Africa. She manages the Data Science Without Borders (DSWB) programme and the Evidence for AI in Health (EVAH) initiative, working with governments, research institutions, and global…"},{"n":"Aman Dalmia","a":"The Agency Fund","b":"Aman Dalmia works as Lead AI Engineer at The Agency Fund, where he partners directly with their grantees to establish rigorous, context-appropriate methods for evaluating AI systems deployed in low- and middle-income countries (LMICs) and is a core contributor to the AI Evaluation Playbook for assessing GenAI products in global development. He is the creator of “Calibrate”, an open-source platform for evaluating AI agents built for non-profits, and…"},{"n":"Olivia Bryan","a":"Abdul Latif Jameel Poverty Action Lab (J-PAL)","b":"Olivia Bryan is a Senior Policy Associate at J-PAL Global, where she helps manage the US$60 million Evidence for AI in Health (EVAH) initiative supporting rigorous evaluations of AI-enabled health tools ready for use in health systems in LMICs. In this role, she coordinates with donors, NGOs, and academics to generate real-world evidence on where AI tools add value and how they can be safely and responsibly integrated into health systems at scale. As a…"},{"n":"Anneka Wickramanayake","a":"Jacaranda Health","b":"Anneka Wickramanayake is Director of Research, Evaluation and Design at Jacaranda Health, overseeing the research and data & analytics departments. She has developed an innovative portfolio of mixed methods research methodologies for evaluating scaled AI-enabled solutions, incorporating principles of model evaluation, piloting, implementation research and impact evaluation. She also specializes in human-centered design methodologies for technology.\n\nAnneka brings experience in development research and analytics, and monitoring and evaluation, having worked in both the private and public sectors. Prior to joining Jacaranda Health, she worked in Ethiopia as research director for Laterite, managing full-cycle research consultancies. Before that, she was monitoring and evaluation specialist for the American Refugee Committee in Rwanda, leading the M&E strategy and assessing the standard of health care provided. Anneka holds an MPH in Epidemiology and Biostatistics from the University of California, Berkeley."},{"n":"Joseph Ross","a":"Ariadne Labs","b":"Joseph (Joey) Ross, MPA, is an Associate Director at Ariadne Labs where he leads the Primary Health Care team’s work in designing and testing innovations in PHC measurement, integrated service delivery, and population health management in the United States and globally. His expertise lies in creating and managing multidisciplinary teams and diverse partnerships that develop and translate PHC evidence and tools into policy and practice. He oversaw Ariadne’s engagement and technical contributions as a core partner of the Primary Health Care Performance Initiative, and is currently supporting global PHC strengthening through the MOMENTUM Knowledge Accelerator and PROPEL Health.\n\nPrior to joining Ariadne Labs, Joey worked at John Snow, Inc., the Global Development Incubator, and ICAP at Columbia University on public health research, strategy, and implementation projects. For over 15 years he has worked in partnership with health systems leaders, practitioners, researchers, and advocates across South and Southeast Asia, Sub-Saharan Africa, and Latin America. Joey completed his undergraduate studies at Bucknell University and his MPA in Development Practice from Columbia University where he was a Global Health Fellow."}]},{"id":"s117","t":"Pacific Digital Health Academy: A Regional Model for Workforce Development and Sustainable Digital Transformation","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Pre-formed Panel","Workforce Capacity and Leadership for the Digital Future","In-person"],"fmt":"Pre-formed Panel","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"In-person","desc":"Large investments in digital health infrastructure, telehealth and e-learning across Pacific Island Countries have produced only partial gains, mainly because health workers lack digital health skills. This panel introduces the Pacific Digital Health Academy, a proposed regional platform built on a Learn, Build, Connect and Implement framework. It would offer structured competency pathways, certification and communities of practice across the region. Speakers from the Pacific Community, UNICEF, the World Bank and the Ministries of Health of Fiji and Tonga discuss how the academy would work, how it would be governed and how it differs from one-off project training.","sp":[{"n":"Rumanusina Francine Maua","a":"The Pacific Community (SPC)","b":"Ms Rumanusina Francine Maua is the Health Information System Adviser, Public Health Division, at the Pacific Community (SPC), supporting digital health and health information systems across the Pacific region (22 Member Countries). With over fifteen years of experience in Samoa's health sector as well as Pacific regional health context, she brings expertise in health system strengthening, policy and planning, ICT for health, and project design and…"},{"n":"Rajeshwar Prasad","a":"UNICEF","b":"Rajeshwar Prasad is an accomplished ICT professional with close to three decades of experience across infrastructure, application development, cloud solutions, and service management. He has led complex ICT projects from conception to delivery across diverse industries, with particular expertise in cloudification, database administration, and project management. Rajeshwar has a strong interest in developing business applications that support data…"},{"n":"Rochelle Eng","a":"The World Bank","b":"Senior Health Economist, World Bank"},{"n":"Shaneel Prakash","a":"Ministry of Health and Medical Services, Fiji","b":"Shaneel Prakash is the Director of Digital Health at the Ministry of Health and Medical Services, Fiji. A visionary tech leader with over a decade of public sector experience, he spearheads national health transformations, including the Fiji Digital Health Strategy. Mr. Prakash specializes in infrastructure modernization, cross-sector collaboration, and geospatial data analytics to build resilient, data-driven healthcare systems. He holds a…"},{"n":"Tifa Halafihi","a":"Ministry of Health, Tonga","b":"ICT Officer, Ministry of Health Tonga"},{"n":"Umer Nisar","a":"CSIRO: Commonwealth Scientific and Industrial Research Organisation","b":"Umer Nisar is Indo-Pacific Digital Health Lead at CSIRO's Australian e-Health Research Centre, where he leads a regional program strengthening interoperable health systems, governance, and workforce capability across Southeast Asia and the Pacific. With over 15 years of experience spanning Australia, the United States, and the Indo-Pacific, he contributes to WHO's work on Digital Public Infrastructure for Health and supports international agencies and…"}]},{"id":"s225","t":"Roundtable Workshops","d":"2026-12-04","s":"11:25","e":"12:25","tags":["Roundtable Workshop","In-person"],"fmt":"","theme":"","mode":"In-person","desc":"Small-group roundtable workshops held in the corners of the room. Choose a table and work with the facilitators on youth co-design, adapting digital health interventions across settings, or applying a health system framework to AI in primary care.\n\nRoundtable workshops (one in each corner of the room) in this session:\n8536 - Designing With, Not For: How Youth Co-Design Drives Better Digital Solutions for Adolescent Health (Yusuf Babatunde, Zach Witkin, Katy Ashe)\n8050 - From AI Applications to Health System Impact: Applying a Health System Framework for AI in Primary Health Care (Joseph Ross, Madeline Pesec, Merrick Schaeffer) [TBC]","sp":[{"n":"Yusuf Babatunde","a":"Youth Development Labs (YLabs)","b":"Yusuf Babatunde is a Growth and Partnerships at YLabs. He started as a Youth Leadership Fellow, building scalable solutions with young people that change how governments, foundations, and large-scale implementers serve them."},{"n":"Zach Witkin","a":"Youth Development Labs (YLabs)","b":""},{"n":"Katy Ashe","a":"Youth Development Labs (YLabs)","b":""},{"n":"Carlos Yerena","a":"Reach Digital Health","b":"Carlos Yerena is a Digital Health and Strategy leader committed to advancing digital innovation for stronger health systems across Africa. Since joining Reach Digital Health in 2022, he has led strategic collaborations with governments, funders, and implementing partners, leveraging over a decade of experience in digital health, sustainable development, and ICT4D. His work focuses on scaling impactful mobile and AI-enabled health solutions and aligning…"},{"n":"Joseph Ross","a":"Ariadne Labs","b":"Joseph (Joey) Ross, MPA, is an Associate Director on the Primary Health Care team at Ariadne Labs, a dual center for health systems innovation at the Harvard School of Public Health and Brigham and Women’s Hospital. Joey has over 16 years experience working in global public health, building partnerships and managing multidisciplinary research and project implementation teams to translate PHC evidence and innovation into policy and practice. He previously…"},{"n":"Madeline Pesec","a":"Ariadne Labs","b":"Madeline Pesec, MD, ScM, is a faculty member with the Primary Health Care Program at Ariadne Labs and a physician in Internal Medicine and Pediatrics. Her research focuses on population health management, person-centered integrated care, and health outcome equity. She is an expert in Costa Rica’s primary health care system, with work examining the mortality impact of primary care reform, implementation strategies, and measurement for improvement.\n\n…"},{"n":"Merrick Schaeffer","a":"Ariadne Labs","b":""}]},{"id":"s124","t":"Lunch Break","d":"2026-12-04","s":"12:25","e":"14:00","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s125","t":"Discovery Stage Fireside Chat: Extending AI models to new disease types: Predictive spatiotemporal models for climate affected water-bourne diseases, including cholera and malaria, based on community-level signals","d":"2026-12-04","s":"12:30","e":"13:00","tags":["Discovery Stage","Climate and Health","In-person"],"fmt":"Discovery Stage","theme":"Climate and Health","mode":"In-person","desc":"In Zambia, climate change has disrupted seasonal disease patterns, while disease notifications are often delayed by four to six weeks. Healthy Learners, the University of Edinburgh and the Government of Zambia are working to turn schools into early-warning sites, using school-based symptom data together with rainfall and temperature data to train AI models that predict outbreaks of cholera, malaria and other climate-affected diseases weeks before official confirmation. This fireside chat covers the modelling approach, the project's design and how community-level signals can make health systems more responsive to climate change.","sp":[{"n":"Maeghan Orton","a":"Healthy Learners","b":"Hi, I'm Maeghan. I'm a global digital health leader with 15+ years of experience including 10 years of field-first technology product development and deployment in Africa and Asia. I take inspiration for my product strategy work from deep field-first experience, supporting community health workers, patients and health leaders develop adaptive and innovative digital health products to improve patient outcomes. I identify health system problems, define…"}]},{"id":"s246","t":"Discovery Stage: Gender, Equity and Rights in Digital Health","d":"2026-12-04","s":"14:00","e":"14:30","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"An interactive dialogue on monitoring gender, equity and rights in digital health through data and indicators.\n\nHosted by the University of Warwick.","sp":[{"n":"Meg Davis","a":"University of Warwick","b":""},{"n":"James Kiilu","a":"University of Nairobi","b":"Dr. James Kiilu is a medical doctor with a strong in…"}]},{"id":"s131","t":"From Global Standards to Local Systems: Introducing the WHO SMART Guidelines-digital adaptation kits (DAK) implementation facilitation guide through an interactive localizaiton workshop","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Interactive Workshop","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Interactive Workshop","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"WHO SMART Guidelines Digital Adaptation Kits (DAKs) turn written health recommendations into structured requirements that can be built into digital systems used at the point of care. Countries still lack practical, standard ways to adapt this global guidance to local needs. This workshop introduces WHO's newly published DAK implementation facilitation guide and findings from impact evaluations that used the DAK method. Facilitated by WHO, AeHIN, HELINA and the Institute for Health Measurement Southern Africa, it takes participants step by step through localising DAK workflows, data elements, decision logic and indicators for new or existing systems.","sp":[{"n":"Rosemary Muliokela","a":"WHO","b":"Rosemary is a dynamic global digital health strategist and expert, currently serving as a technical consultant with the World Health Organization’s Department of Sexual and Reproductive Health and Research. She spearheads the integration of digital tools to strengthen SRH service delivery. Her work has included spearheading the introduction and implementation of WHO SMART Guidelines and Digital Adaptation Kits (DAKs), driving digital health innovation…"},{"n":"Tigest Tamrat","a":"WHO","b":"Tigest Tamrat is a Scientist in the Department of Sexual and Reproductive Health and Research at the World Health Organization based in Geneva, Switzerland. Her work focuses on the use of digital technologies, including artificial intelligence(AI), to accelerate health system improvements and support sexual and reproductive health. Within this role, she coordinates multisite research on the design and impact of digital tools, as well as the development…"},{"n":"Jai Ganesh Udayasankaran","a":"Asia eHealth Information Network (AeHIN), India","b":"Jai Ganesh Udayasankaran (Jai) is the Executive Director of the Asia eHealth Information Network (AeHIN). He brings more than 20 years of experience in planning, procuring, and implementing digital health solutions, including web-based EMR, PACS, telehealth, and chronic disease management portals. Jai serves on several global and national bodies. He is a Board member of the Global Digital Health Network (GDHN) and sits on the eHealth Expert Committee…"},{"n":"Sosthenes Bagumhe","a":"Pan Africa Health informatics association( HELINA) I Ministry of Health, Tanzania","b":"Mr. Sosthenes Bagumhe is a human-centered design and digital health expert with over 16 years of experience in health information systems, project management, and implementation. He serves as General Secretary of the Pan African Health Informatics Association (HELINA) and President of the Tanzania Health Informatics Association (TAHIA), championing digital health standards, data governance, FHIR interoperability, and WHO SMART Guidelines across Africa.…"},{"n":"Kuwani Banda","a":"Institute for Health Measurement (IHM) Southern Africa, Lusaka, Zambia","b":"Kuwani Banda is a Digital Health and Clinical Informatics Specialist with over 14 years of experience supporting USG/PEPFAR-funded projects in Zambia, specializing in strategic planning, technical assistance, and program design. He has collaborated with CDC, USAID, WHO, and Peace Corps to deliver training programs, including Training of Trainers initiatives, and has contributed to Zambia's national data and system harmonization strategy in support of…"},{"n":"Robert Gongora","a":"Ministry of Health and Child Care (MoHCC), Zimbabwe","b":"Dr Gongora is a digital health specialist who has led the implementation of the Zimbabwe Ministry of Health and Child Care (MoHCC) Electronic Health Records (EHR) system since 2017. He currently serves as the Deputy Director for Electronic Health Records EHR) for the Zimbabwe Ministry of Health and Child Care ( MoHCC) in Zimbabwe. His leadership has been instrumental in championing the introduction, adaptation, and practical application of WHO Digital…"}]},{"id":"s228","t":"Individual Presentations: Climate-Smart Digital Health: From Data to Early Warning and Action","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on using climate and environmental data for health, from the effects of climate variability on child diarrhoeal deaths in Ethiopia to adding climate data to DHIS2, a voice-first AI companion for climate disasters in Pakistan, AI-powered community surveillance for early outbreak detection and a flood-exposure surveillance framework for coastal Africa.\n\nPresentations in this session:\n8055 - The Short-Term Effects of Climate Variability on Diarrhoeal Mortality Among Children Under Five in Ethiopia (Flavian Otieno)\n8391 - Integrating Climate and Environmental Data into National DHIS2 Platforms: A Practical Framework for Climate-Informed Public Health Decision-Making (Priyanga Senanayaka)\n8404 - Beyond Early Warning: Lessons from Pakistan's First Offline Voice-First Gen AI Companion for Climate Disaster Preparedness (Kaiyan Yousaf)\n8399 - From Community Narratives to Actionable Intelligence: AI-Powered Community Surveillance for Early Outbreak Detection (Dércio Duvane, Jeremias Chone)","sp":[{"n":"Flavian Otieno","a":"APHRC","b":"I am a Data Scientist at the African Population and Health Research Center (APHRC), with a background in Mathematics and Statistics. My research focuses on climate-health modeling, with a focus on climate-sensitive diseases, mental health, maternal and child health, and stroke in relation to climate variability. I am an early-career researcher."},{"n":"Priyanga Senanayaka","a":"Ministry of Health, Sri Lanka","b":"Dr. Priyanga Senanayaka is a Specialist in Digital Health and Consultant in Health Informatics at the Family Health Bureau, Ministry of Health, Sri Lanka. He previously served as a Digital Health Consultant with the World Health Organization in Sri Lanka and the Maldives, leading the design and implementation of national digital health initiatives.\n\nHe holds an MD in Health Informatics (Gold Medal), an MSc in Biomedical Informatics, MBBS and is a…"},{"n":"Kaiyan Yousaf","a":"Viamo.io","b":"Kaiyan Yousaf is Director of Strategic Partnerships at Viamo, where he leads key strategic partnerships and frontier AI programs for social impact across Africa and Asia. He has over 15 years of experience designing technology-enabled development programs with USAID, FCDO, United Nations agencies, governments, donors, and mobile network operators. Kaiyan conceived and led Noor, Pakistan’s first offline, voice-first Generative AI companion for disaster…"},{"n":"Dércio Duvane","a":"VillageReach","b":"Dércio Duvane is a Senior Manager for Health Information Systems based in Maputo, Mozambique, with expertise in digital health, artificial intelligence (AI), telehealth, health information systems, and data governance. He works at the intersection of technology and public health, leading initiatives that strengthen health systems through innovative digital solutions, improved data use, disease surveillance, and evidence-based decision-making. Dércio…"},{"n":"Jeremias Chone","a":"Mozambique Ministry of Health","b":""},{"n":"Benjamin Shaibu","a":"eHealth Africa","b":"Shaibu Benjamin Ojoka is a Spatial Data Scientist with 7+ years of experience integrating GIS, remote sensing, and AI to drive spatial intelligence across health, climate resilience, and development projects in Sub-Saharan Africa.\n\nShort third-person (LinkedIn/website, ~120 words)\n\nShaibu Benjamin Ojoka is a Spatial Data Scientist with over seven years of experience applying GIS, remote sensing, and AI to solve problems in public health, climate resilience,…"}]},{"id":"s227","t":"Individual Presentations: Financing Digital Health at Scale: Costs, Value and Sustainability","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on the costs, value and financing of digital health at scale, including an economic evaluation of Ethiopia's community health information system, outcome-based payments for community workers, linking private and public providers to Nepal's social security system, Rwanda's use of claims data to reform provider payment, and the effect of India's clean air programme on out-of-pocket health spending.\n\nPresentations in this session:\n7742 - Economic Evaluation of Ethiopia's Electronic Community Health Information System (eCHIS): Evidence from a Comparative Study (Wubshet Denboba Midekssa, Abebaw Gebeyehu Worku)\n8575 - Paying frontline workers per verified case: an outcome-based financing model for community Kangaroo Mother Care in Uganda (Saumyadeb Dasgupta)\n8336 - Harmonizing Private and Public Healthcare Systems into Nepal’s Social Security Architecture Using openIMIS (Roshan Koju, Keshab Bahadur Dhami)\n8340 - Using Claims Data to Reform Provider Payment: Rwanda’s Data-Driven Capitation Model (África Periáñez Santiago, Sumiko Tanaka Pusch)","sp":[{"n":"Wubshet Denboba Midekssa","a":"JSI","b":"Wubshet is a seasoned public health professional with about 20 years of experience in Ethiopia’s health sector, currently serving as Project Director at JSI. He holds a Master’s degree in Public Health and brings deep expertise in designing and implementing health information systems, as well as health policy and planning.\n\nBeginning his career as a public health practitioner and manager at a district-level Health Center, Wubshet went on to work with…"},{"n":"Abebaw Gebeyehu Worku","a":"JSI","b":"Dr Abebaw Gebeyehu is a Senior Public Health Professional and associate professor in reproductive health with extensive experience in health systems, research, and academia. Dr. Abebaw holds a Ph.D. from Addis Ababa University, an MPH from the University of Gondar, and a first degree in Public Health from Debub University. Currently he is leading MERL activities at JSI/Data Use Partnership and serve as senior advisor of the MOH- PSR LEO. He\n has previously…"},{"n":"Saumyadeb Dasgupta","a":"Dimagi","b":"Saumyadeb Dasgupta manages Dimagi's community Kangaroo Mother Care program across Uganda, Kenya, Nigeria, and India. Working with locally led organizations, the program focuses on improving outcomes for preterm and low-birthweight infants once they leave the health facility, with frontline health workers visiting their households through this fragile period. The financing structure follows a pay-per-completed-case model built on a carefully designed…"},{"n":"Roshan Koju","a":"Social Security Fund, Nepal","b":"Dr. Roshan Koju is an IT and Digital Transformation Specialist at Nepal's Social Security Fund (SSF), where he leads initiatives in digital health financing, interoperability, and enterprise architecture. He has played a key role in designing and implementing Nepal's national health purchasing platform based on openIMIS, enabling the integration of public and private healthcare providers through HL7 FHIR-compliant interoperability standards. His work…"},{"n":"Keshab Bahadur Dhami","a":"Social Security Fund","b":"Network and Security Professional with 6+ years of experience in enterprise IT infrastructure, network administration, cybersecurity, virtualization, and system operations. Experienced in managing and troubleshooting FortiGate firewalls, F5 WAF/LTM, Sophos, VPNs, enterprise switching, VMware/vSphere, SAN/NAS storage, backup systems, and network monitoring."},{"n":"África Periáñez Santiago","a":"Causal Foundry","b":"África Periáñez Santiago\n CoFounder & CEO\n https://www.linkedin.com/in/africaperianez/\n África is an AI scientist and entrepreneur. África held the role of Chief Analytics Officer at Inditex, leading the AI strategy and bolstering one of the world's fastest supply chains.\n Before, África held the role of Chief Analytics Officer at Inditex. Previously, she founded Yokozuna Data, an AI firm based in Tokyo dedicated to nudging and predicting individual…"},{"n":"Sumiko Tanaka Pusch","a":"Causal Foundry","b":"Sumiko Tanaka Pusch is Chief Operating Officer at Causal Foundry, where she leads partnerships and operations to advance AI for all. Her career in international relations began during her undergraduate studies at the University of Washington, leading to a UN internship in New York and a dual master’s degree in diplomacy and strategic negotiations in Paris. She has supported…"},{"n":"Karthika V Menon","a":"Indian Institute of Technology, Roorkee","b":"Karthika V Menon is a doctoral researcher in Economics at the Indian Institute of Technology (IIT) Roorkee, specialising in health economics, health financing, and behavioural economics. Her research sits at the intersection of environmental health, household financial protection, and public policy, with a particular focus on how ambient air pollution, insurance coverage, and social determinants interact to shape healthcare expenditure among vulnerable…"}]},{"id":"s127","t":"Individual Presentations: Strengthening Health Data at the Source: Quality, Intelligence and Use","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on improving health data where it is collected, including AI to replace paper-to-DHIS2 transcription, digital supportive supervision, geospatial workload planning for immunisation, conversational AI for sensitive reporting and linking hospital and police data to prevent violence.\n\nPresentations in this session:\n7491 - ‘SnapiForm: Practical AI to Eliminate Paper-to-DHIS2 Transcription and Strengthen Routine Health Information Systems’ (Poppy Farrow, Arantxa Roca-Feltrer)\n8377 - Digital Integrated Supportive Supervision (ISSV) as a District Health-System Intelligence Model for Primary Health Care Supervision and National Scale-Up in Sierra Leone (Alhassan Mayei, Lisa Seidelmann, Nathaniel Soloku)\n7866 - PlanFeld: Leveraging Geospatial Intelligence for Digital Workload Rationalization to Strengthen Immunization Campaign in Northern Nigeria (Abubakar Shehu, Comfort Audu, Loveth Metiboba)\n8131 - From Trust to Disclosure: How Conversational AI Changes Sensitive Health Reporting in LMICs (Devika Kapadia, Mokshada Jain, Tanya Agrawal, Ashish Jain)\n8048 - Cardiff Model @ Pattaya: Integrating Hospital and Police Data for Community Violence Prevention (Suppasit Srisaeng)","sp":[{"n":"Poppy Farrow","a":"PATH","b":"Originally from the UK, I bring over 14 years of experience in the global digital health sector. I began my career in 2012 in Zanzibar with D-tree International, at a time when “digital health” was still emerging as a field. Since then, I have held roles with Save the Children, Malaria Consortium, and most recently JSI, where I worked closely within a US-based team supporting large-scale health programmes. My career has taken me across East, West, and…"},{"n":"Arantxa Roca-Feltrer","a":"PATH","b":"Dr. Arantxa Roca-Feltrer is a malaria epidemiologist with a PhD from the London School of Hygiene and Tropical Medicine and more than 20 years of experience supporting malaria control and elimination programs across Africa and Asia. Her expertise spans surveillance, monitoring and evaluation, operational research, epidemiology, and capacity strengthening, with a particular focus on improving data quality and data use for decision-making. She has led…"},{"n":"Alhassan Mayei","a":"German cooperation for International Development (GIZ)","b":"Alhassan Mayei is a Digital Health | Results-Based Monitoring and Evaluation Advisor with experience in public health data systems, health systems strengthening, immunization logistics, supportive supervision, and digital health implementation. He supports the design, analysis, and use of programme data to improve decision-making, data quality, accountability, and service delivery. His work bridges field implementation, analytics, and evidence…"},{"n":"Lisa Seidelmann","a":"German cooperation for International Development (GIZ)"},{"n":"Nathaniel Soloku","a":"Ministry of Health Sierra Leone"},{"n":"Abubakar Shehu","a":"eHealth Africa","b":"Abubakar Shehu is a seasoned public health professional with a strong background in disease prevention, health systems strengthening, and digital health innovation. He currently serves as a Program Manager of the Disease Prevention and Monitoring (DPM) portfolio at eHealth Africa (eHA), where he provides strategic leadership and technical oversight for public health interventions across multiple states in Nigeria. At eHA, Abubakar has led the…"},{"n":"Comfort Audu","a":"eHealth Africa"},{"n":"Loveth Metiboba"},{"n":"Devika Kapadia","a":"Surgo Health","b":"Devika Kapadia is a manager at Surgo Health, where she has worked on the behavioral dimensions of reproductive health, abortion access, and TB. She is interested in ensuring ethical, inclusive access to AI for global development, and works to adapt Surgo's AI, data and technology products to diverse cultural and resource contexts."},{"n":"Mokshada Jain","a":"Surgo Health"},{"n":"Tanya Agrawal","a":"Surgo Health"},{"n":"Ashish Jain","a":"Surgo Health"},{"n":"Suppasit Srisaeng","a":"Office of Disease Prevention and Control Region 6 (ODPC 6)","b":"Suppasit Srisaeng is a physician, epidemiologist, and Deputy Director of the Office of Disease Prevention and Control Region 6 (Chonburi) under Thailand's Department of Disease Control, Ministry of Public Health. He oversees the office's epidemiology, emergency response, and digital units, and leads the Cardiff Model @ Pattaya violence-prevention project. Currently pursuing studies in Health Informatics at Mahidol University, he is a alumni of…"}]},{"id":"s129","t":"Is This AI Application Ready for Care? A Practical Workshop on Clinical Validation and Safety Harnesses","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Interactive Workshop","AI for Health","In-person"],"fmt":"Interactive Workshop","theme":"AI for Health","mode":"In-person","desc":"AI models can pass medical exams, but that does not mean they are ready to support patient care. In this workshop, Ariadne Labs guides participants through a framework for validating AI health applications as complete products, covering the model, software, user interaction, workflow, data, safeguards and monitoring. The framework covers six domains, including validity, reliability, safety, fairness and usability. Participants learn to move from testing models to validating whole applications, and leave with an outline of a validation and safety plan to inform design, piloting, deployment and monitoring.","sp":[{"n":"Madeline Pesec","a":"Ariadne Labs","b":"Madeline Pesec, MD, ScM, is a faculty member in the Primary Health Care Program at Ariadne Labs and a practicing physician in internal medicine and pediatrics at Brigham and Women’s Hospital. Her work focuses on strengthening primary health care through population health management, person-centered integrated care, and digital health. She works across Latin America and sub-Saharan Africa to develop and study practical approaches to improving patient…"},{"n":"Joey Ross","a":"Ariadne Labs"},{"n":"Merrick Schaefer","a":"Ariadne Labs"}]},{"id":"s128","t":"Pacific Common Data Set for Interoperability: A Hands-On Workshop for Clinical Data Modeling","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Interactive Workshop","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Interactive Workshop","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"Interoperability depends on agreeing which clinical information should be exchanged, not just on adopting technical standards. This workshop draws on the Pacific Common Clinical Data for Interoperability initiative, a regionally owned effort to agree a shared clinical dataset across Pacific Island countries and territories. Facilitated by CSIRO and the Pacific Community, it puts participants through the same decisions Pacific clinicians, informaticians and policymakers faced in identifying, prioritising and agreeing core clinical data across countries with different systems and levels of digital maturity.","sp":[{"n":"Kylynn Loi","a":"CSIRO: Commonwealth Scientific and Industrial Research Organisation","b":"Kylynn Loi is an experienced SNOMED CT Terminology Analyst with a background in pharmacy and a career built at the intersection of clinical practice and health informatics. She currently leads development of the Australian Core Data for Interoperability (AUCDI) through the Sparked Clinical Design Group as part of the HL7 AU FHIR accelerator. Her expertise spans clinical terminology content development, terminology mapping, education and training, and…"},{"n":"Kate Ebrill","a":"CSIRO: Commonwealth Scientific and Industrial Research Organisation","b":"Kate Ebrill is an experienced senior executive with a demonstrated history of working in the health care industry. Champion for standards development with a focus on community building. Skilled in government procurement, digital strategy, healthcare information technology (HIT), program development, change management and delivery. Strong business development professional with post graduate qualifications in Public Health from University of Sydney."},{"n":"Rumanusina Maua","a":"The Pacific Community (SPC)","b":"Rumanusina Maua is a Health Information System Adviser at the Pacific Community (SPC), where she has worked since 2022 supporting digital health and health information systems across the Pacific region. With over ten years of experience in Samoa's health sector, she brings expertise in health system strengthening, policy and planning, ICT for health, and project design and implementation. Her regional work spans human resource management, capacity…"},{"n":"Heather Leslie","a":"Atomica Informatics","b":"Heather's digital health journey has been focused on merging the deep knowledge of clinicians with clinical data recording patterns to develop an ecosystem of atomic health information models. These models create the potential of lifelong health data for the first time, independent of any specific application or technology. My work not only bridges the gap between clinicians and software engineers; it simplifies the challenge of interoperability…"},{"n":"Kitione Waqanisau","a":"Fiji, Ministry of Health and Medical Services","b":"Dr Kitione Waqanisau is a senior clinician and digital health leader based in Fiji. A specialist with expertise in obstetrics, gynaecology, and paediatrics, he has combined a distinguished clinical career with national leadership in health system digitisation. He currently serves as Chairman of Fiji's Digital Health Technical Advisory Group at the Ministry of Health and Medical Services, having previously chaired the Digital Health Working Group from…"}]},{"id":"s126","t":"Rationalising digital health architecture under aid cuts: a government-owned method from Malawi, Cambodia, and Eswatini","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Pre-formed Panel","Governance and Digital Health at Scale","In-person"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"Foreign aid cuts in 2025 took digital health systems offline overnight in several countries, risking data loss and halting services. Behind these failures are years of donor-funded digitisation that left crowded, fragmented systems no government fully owns. Drawing on CHAI's work with the Ministries of Health of Malawi, Cambodia and Eswatini, this panel sets out a practical, government-led method for taking stock of a country's digital health systems and consolidating them into a leaner core architecture the ministry can own and sustain. Speakers walk through the systems census, how core systems are prioritised and how an architecture vision is set.","sp":[{"n":"Sameen Babur","a":"Clinton Health Access Initiative","b":"Sameen Babur is Director of Digital Health for Malaria and NTDs at CHAI, supporting Ministries of Health across more than 20 countries on malaria information systems, campaign digitization, and disease surveillance. She has worked in digital health at CHAI since 2017, after managing health technology products at Accenture. She holds degrees in biology from Stanford and Brown"},{"n":"Moses Majya","a":"System Architecture Unit, Digital Health Division, Quality Management Department, MoH, Malawi"},{"n":"Jonathan Mtaula","a":"Clinton Health Access Initiative"}]},{"id":"s130","t":"Trusted Cross-Border Health Data: GDHCN, Personal Health Records, Digital Health Wallets and Digital ICVP in Practice","d":"2026-12-04","s":"14:00","e":"15:00","tags":["Interactive Workshop","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Interactive Workshop","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"The Global Digital Health Certification Network (GDHCN) lets countries verify health documents across borders. This workshop opens with countries sharing how they use it for personal health records, digital home-based maternal and child health records, digital health wallets including the International Patient Summary, the Hajj health card and the digital international certificate of vaccination (the 'yellow card'). Moderated by Natschja Ratanaprayul (WHO), the session brings together speakers from WHO, UNICEF, the Agence Togo Digital and the Ministries of Health of Thailand and Zimbabwe, with PAHO joining by video. It then introduces the GDHCN readiness assessment and a step-by-step pathway for joining the network, which interested participants can begin working through.","sp":[{"n":"Natschja Ratanaprayul","a":"WHO","b":"Natschja Ratanaprayul is a Technical Officer in the Department of Data, Digital Health, Analytics and AI at the World Health Organization Headquarters in Geneva. She leads WHO's SMART Guidelines programme, an initiative transforming how WHO develops and implements normative guidance across to support implementation in digital and AI systems. She has provided direct technical support to over 45 countries across all six WHO regions. She also plays a…"},{"n":"Thandekile Moyo","a":"Technical Officer, Research and Development for Health Innovations Unit, Health Systems and Services Cluster, WHO Regional Office for Africa","b":"Thandekile is a Public Health Officer at the World Health Organization (WHO) with a regional portfolio spanning program management, digital health, and health systems strengthening. She serves as the Digital Health Focal Point for WHO AFRO, supporting Member States to scale evidence-based innovations, improve public health intelligence, and advance digital transformation strategies that reinforce resilient health systems. Her experience includes…"},{"n":"Godwin Kossi M. ELITCHA","a":"The Agence Togo Digital (ATD)","b":"Godwin Kossi M. ELITCHA is Head of Architecture and Compliance at Togo's national digital agency (ATD). He specializes in digital government, enterprise architecture, IT governance, and interoperability. He contributes to national digital transformation initiatives, focusing on secure data exchange, digital public infrastructure, and interoperable public services. He played a key technical role in Togo's onboarding to the WHO Global Digital Health…"},{"n":"Supharerk Thawillarp","a":"Ministry of Public Health of Thailand","b":"A Physician, Epidemiologist and Public Health Informatics Enthusiast involved in several digital health project in Thailand. Currently working at Department of Disease Control, Ministry of Public Health of Thailand. Dr Supharerk Thawillarp is also a member of WHO's Global Digital Health Network Strategic Advisory Group."},{"n":"Simukai Zizhou","a":"Director ICT, Health Information and Digital Health Services, Ministry of Health and Child Care, Zimbabwe","b":"Dr. Simukai Zizhou is a Zimbabwean medical practitioner, public health specialist and digital health leader. He has been Director of Health Informatics at Zimbabwe's Ministry of Health and Child Care since July 2020, and lectures in the Bioinformatics and Bioengineering Department at the University of Zimbabwe. He has worked with the Ministry since 1993, including more than 14 years as Provincial Medical Director for Mashonaland East Province (2006-2020). He holds an MD from the University of Zimbabwe, a Master of Public Health, a Certificate in Applied Epidemiology and a 2013 certificate in Monitoring and Evaluation from the University of the Witwatersrand. His areas of focus include disease management, epidemiology, health informatics, programme evaluation, palliative care and public health consulting."},{"n":"Alex Muhereza","a":"Digital Health Systems Specialist, UNICEF Global Programme Division, Health","b":"Alex Muhereza leads digital health technical support at UNICEF, working with Ministries of Health across Africa, Asia Pacific, and the Americas. Alex supports countries to assess their digital health readiness, prioritise high impact use cases, and strengthen the governance and interoperability foundations needed for trusted, verifiable and portable health records, ranging from vaccination certificates to digital home-based records for mothers and children."},{"n":"Myrna Marti","a":"Pan American Health Organization (PAHO)","b":"Myrna Marti is a digital health advisor at the Pan American Health Organization / WHO Region of the Americas, who has been supporting the the Pan American Highway for Health (PH4H) initiative, supported by the Intra American Development Bank (IADB), to support cross border interoperability using WHO's Global Digital Health Certification Network. Myrna is a multifaceted consultant and IT leader with a strong track record of delivering digital…"}]},{"id":"s226","t":"World Café","d":"2026-12-04","s":"14:00","e":"15:00","tags":["World Café","In-person"],"fmt":"","theme":"","mode":"In-person","desc":"An unconference-style session with small table discussions. Each table is hosted by a presenter on a topic such as AI at the last mile, digital health workforce, interoperability, health financing, climate and health, and youth engagement. Move between tables and join the conversations that interest you.\n\nWorld Café tables in this session:\n7898 - State surveillance experienced as intimate surveillance among young adults living with HIV and key populations in Kenya: criminalisation, stigmatisation, and the political determinants of health (James Kiilu)\n8502 - Leapfrog or Stumble? What It Takes for Generative AI to Reach the Last Mile (Dr. Shekhar Waikar)\n7378 - Enhancing community death notification in Uganda using a hackathon based approach to integrate mortality surveillance into the electronic Community Health Information System (eCHIS) (Jimmy Patrick Alunyo)\n8059 - Developing an Evidence Guide to Strengthen Public Investment Decisions for Digital Health Technologies in Lower-Resource Settings (Kinanti Khansa Chavarina, Sarah Edney, Dohyun Seo, Thapanee Sangkaew)\n7955 - From Organizational Readiness to Digital Transformation: Investing in Leadership, Systems, and Workforce Capacity for Digital Health (Vipin Joseph, Manesh Thomas)\n8477 - Designing for What Comes After: A Multi-Country Model for Moving Health Innovation from Hackathon to Implementation (Miranda Barasa)\n8723 - Access Without Assurance? Evaluating the Quality of Digital Family Planning Services in Kenya Through Mystery Shopping (Michael Waithaka)\n7503 - Beyond Deployment: Understanding what drives sustainable use of Digital Public Health Interventions among frontline Health Care Workers in Kenya. (Wandia Ikua)\n7805 - Measuring Readiness, Enabling Scale: The Digital Health Maturity Index as a Governance Tool for Continental Digital Health Transformation (Nokulunga Twala)\n8695 - Digital Skills Aren't Gender Neutral: Launching a Gender-Responsive Digital Literacy Training of Trainers Toolkit for Health Workers (Naina Ahuja)\n7882 - Health Misinformation in the Digital Age: A Rapid Review of Social Media's Role in Amplifying Health Misinformation and Interventions to Address It (Poorna Fernando)\n8334 - From Tool to Collective: Scaling Kenya’s National eCHIS Through Localized Capacity and DPG Leadership (Simon Mbae)\n7848 - Digital Readiness, Healthcare Access, and Service Delivery: A Provider’s narrative from Haryana, India (Jagjit Kaur)\n7524 - Advancing Digital Health Transformation through Capability-Based Health Workforce Development and Competency Frameworks: The Case of Ethiopia (Hana Gebeyehu, Nigussie Mengesha)\n7762 - Governing Interoperability at the County Level: How Kisumu, Kenya Built a Sustainable Maternal Health Information Exchange Through Public-Private Partnership (Mercy Kamau)\n8658 - From Pilots to a National Platform: The Technology and Financing Behind Kenya's Level 1 Digitalisation with eCHIS (Ryan Gitau, JOHN WANYUNGU)\n8304 - Embedding stewardship in Ethiopia’s RHIS: implementation mechanisms in a university-government partnership (Biniam Taye)\n8112 - Digitizing One Health for Climate-Resilient Care in Kenya's Last-Mile Communities (Elmer Ongus)\n7845 - Bridging Last Mile Healthcare Disparities Through Sustainable Digital Primary Healthcare and Health Financing (Sujay Santra, Sandip Mondal, Saptak Ghosal)\n7405 - Creating climate-sensitive disease forecasting platforms for health systems via use-first approaches (Karen Finnegan)","sp":[{"n":"James Kiilu","a":"University of Nairobi","b":"Dr. James Kiilu is a medical doctor with a strong interest in global health, community participation, and equitable healthcare systems. As a member of the Kenya Community Advisory Team (KCAT) under the Digital Health and Rights Project, he contributes to national and global discussions on rights-based digital governance and equitable access to healthcare.\n\nJames is passionate about strengthening participatory approaches that bridge policy and lived…"},{"n":"Dr. Nikesh Shah","a":"Intelehealth","b":"Dr. Nikesh R. Shah is a physician and health-systems executive with over twenty years across US and Indian healthcare, and Clinical Advisor for AI R&D at Intelehealth. He previously served as CEO of the National Cancer Grid's Koita Centre for Digital Oncology at Tata Memorial Centre, leading digital transformation of cancer care including oncology EMRs, a national tele-oncology platform, and AI and machine-learning innovations. His work spans clinical…"},{"n":"Jimmy Patrick Alunyo","a":"Uganda National Institute of Public Health","b":"Jimmy Patrick Alunyo is a public health researcher, surveillance specialist, and digital health practitioner affiliated with the Uganda Ministry of Health and Busitema University. His work focuses on infectious disease surveillance, mortality surveillance, outbreak preparedness and response, digital health systems strengthening, epidemiology, and health information systems in low-resource settings. He has contributed to several national and regional…"},{"n":"Kinanti Khansa Chavarina","a":"HITAP","b":"Kinanti Khansa Chavarina is an Associate at the International Unit of the Health Intervention and Technology Assessment Program (HITAP) Foundation in Thailand. Her work focuses on health policy and systems research, such as scoping and systematic reviews, qualitative analysis, and economic evaluation. Her research interests include health policy, health technology assessment, kidney disease, and digital health. Khansa also manages international collaborations,…"},{"n":"Sarah Edney","a":"HITAP","b":""},{"n":"Dohyun Seo","a":"HITAP","b":""},{"n":"Thapanee Sangkaew","a":"HITAP","b":""},{"n":"Vipin Joseph","a":"Catholic Health Association of India","b":"Vipin Joseph leads the Strategic Information Division of CHAI. He is a public health professional with 15+ years of experience in MEAL systems, project implementation, partnership building, and knowledge management across HIV/AIDS, TB, Community Health, and Health Systems Strengthening. Skilled in leading donor-funded initiatives, fostering learning cultures, and leveraging digital tools for public health impact. Proven ability to coordinate with…"},{"n":"Manesh Thomas","a":"Catholic Health Association of India","b":"Mr. Manesh Thomas leads CHAI’s information and communication technology initiatives. He is responsible for managing IT infrastructure, digital systems, and ensuring smooth technology operations across the organization. With a background in Physics and additional qualifications in computer applications, hardware, and networking, he contributes to CHAI’s mission by driving digital innovation and supporting technology-enabled solutions."},{"n":"Miranda Barasa","a":"African Population and Health Research Center(APHRC)","b":"Miranda Barasa is a Program Manager in the Data Science Program at the African Population and Health Research Center (APHRC), where she leads the implementation of multi-country initiatives advancing artificial intelligence (AI), data science, and digital health across Africa. She manages the Data Science Without Borders (DSWB) programme and the Evidence for AI in Health (EVAH) initiative, working with governments, research institutions, and global…"},{"n":"Michael Waithaka","a":"Jhpiego","b":"Michael Waithaka is a Research and Learning Advisor at Jhpiego and an experienced monitoring, evaluation, research, and learning (MERL) specialist with expertise in data analytics, biostatistics, implementation research, and evidence generation. He currently leads research and learning initiatives, providing technical leadership in study design, protocol development, data quality assurance, knowledge management, and dissemination of research findings.…"},{"n":"Victor Femi-Lawal","a":"University of Ibadan","b":""},{"n":"Wandia Ikua","a":"Independent Consultant","b":"Wandia Ikua is a public health systems specialist, digital health researcher, and Monitoring, Evaluation and Learning (MEL) expert with more than 17 years of experience advancing health programs across Africa. She has built a career at the intersection of health systems strengthening, digital health, health security, and evidence-informed decision-making.\n\nWandia has advised governments, donors, and implementing partners on the design of national…"},{"n":"Nokulunga Twala","a":"https://www.genesis-analytics.com/","b":"Nokulunga Twala is an Associate in the Health Practice at Genesis Analytics, based in Johannesburg, South Africa. With 3+ years of experience in research, data analysis, and monitoring and evaluation, she specialises in translating complex governance frameworks into actionable diagnostic tools for national planning.\n\nNokulunga supported the DHMI implementation across 10 African countries, generating insights on how governance maturity predicts digital…"},{"n":"Naina Ahuja","a":"UNICEF","b":""},{"n":"Poorna Fernando","a":"Ministry of Health Sri Lanka","b":""},{"n":"Simon Mbae","a":"Medic Afya","b":"Simon Mbae is a seasoned public health professional with over a decade of expertise at the intersection of community health and digital innovation. Driven by a commitment to accelerating Universal Health Coverage (UHC), he specializes in deploying transformative technologies to strengthen primary healthcare systems in Africa.\n\nCurrently serving as the Program Head for East Africa at Medic Afya, Simon leads strategic partnerships with Ministries of…"},{"n":"Jagjit Kaur","a":"Ashoka University","b":"Dr. Jagjit Kaur is a sociologist, a postdoctoral fellow at the Department of Computer Science, Ashoka University, and a project head at the Koita Centre for Digital Health, Ashoka University, where she leads interdisciplinary research at the intersection of sociology, artificial intelligence, and digital health. She currently heads projects at the Koita Centre for Digital Health focused on digital health readiness, electronic health records, AI in…"},{"n":"Hana Gebeyehu","a":"BITS College","b":"Hana Gebeyehu Mandefro is a Digital Transformation Consultant, Business Analyst, and Engagement Manager with over eight years of experience in digital transformation, enterprise architecture, and organizational capability development. She currently serves as Engagement Manager and Business Analyst for Ethiopia's Digital Health Enterprise Architecture Development Project, supporting the Ministry of Health in advancing its national digital health agenda.\n\nHer…"},{"n":"Nigussie Mengesha","a":"Brock University","b":"Dr. Nigussie Tadesse Mengesha is an Assistant Professor of Information Systems at the Goodman School of Business, Brock University, Canada. His teaching and research focus on digital transformation, artificial intelligence, business analytics, cloud computing, and information systems strategy.\n\nWith over 20 years of experience in academia, consulting, and industry collaboration, he has worked extensively on digital health, digital banking, cloud adoption,…"},{"n":"Mercy Kamau","a":"IntelliSOFT Consulting","b":"Mercy Kamau is a Business Analyst at IntelliSOFT Consulting Limited, Kenya, working at the intersection of clinical medicine and digital health. With a background as a general medical practitioner and clinical analyst, she brings a clinician's lens to the design and implementation of context-appropriate digital health solutions for low-resource settings in Africa. At IntelliSOFT, she has been centrally involved in the design and deployment of the…"},{"n":"Ryan Gitau","a":"MEDIC AFYA","b":"Dr. Nyotu is one of Kenya’s foremost digital health architects. He is a physician, entrepreneur, and policy leader whose career has been defined by building systems that work at scale, within government, and for the communities that need them most. His appointment reflects exactly the kind of Africa-rooted, mission-driven leadership that Medic Afya was created to center.\n\nAs the inaugural head of the country’s first Division of Digital Health at Kenya’s…"},{"n":"JOHN WANYUNGU","a":"MINISTRY OF HEALTH - DIVISION OF COMMUNITY HEALTH","b":"John Wanyungu’s role in Ministry of Health Republic of Kenya is Division of Community Health Services, Moh, Deputy Head (Kenya). He has been the technical lead who has guided the conversation and collaborated with the Division of Digital health, the MOICT and the DHA to ensure that all aspects the implementation are monitored."},{"n":"Biniam Taye","a":"Ministry of Health, Ethiopia","b":"Dr. Biniam Kefiyalew Taye is a Health Information Systems researcher at the Ethiopian Ministry of Health. He holds a PhD in Public Health Informatics and an MSc in Biostatistics and Health Informatics. His work focuses on routine health information systems, digital health, data quality, health data analytics, and evidence-informed decision-making. He applies mixed-methods and advanced quantitative approaches, including causal inference, to examine…"},{"n":"Elmer Ongus","a":"Safari Doctors","b":"Elmer Ongus is the Monitoring & Evaluation Officer at Safari Doctors, supporting data systems, reporting, learning and evidence use for last-mile health programmes in Kenya. His work focuses on turning outreach, school health, Youth Health Ambassador and One Health data into practical decisions for climate-resilient, community-led care."},{"n":"Sujay Santra","a":"iKure Techsoft Pvt Ltd","b":"Sujay Santra, Founder & CEO of iKure TechSoft, is a distinguished social entrepreneur, an Ashoka Fellow and a member of the National Core Committee on Artificial Intelligence at CII. Sujay has been honored by former President Pranab Mukherjee for his contributions to social impact. Under his leadership, iKure is providing affordable healthcare across rural India and has impacted 34 million lives. Author of Losing Big, Winning Bigger and a sought-after…"},{"n":"Sandip Mondal","a":"iKure Techsoft Pvt Ltd","b":""},{"n":"Saptak Ghosal","a":"iKure Techsoft Pvt Ltd","b":"Public Health and Epidemiology professional with 4+ years of experience in research, monitoring and evaluation (M&E), health program implementation, and data analysis. Proficient in study design, data collection, statistical analysis, program monitoring, stakeholder engagement, team supervision, and grant-funded project management. Strong track record of working in multidisciplinary environments to achieve program and research objectives."},{"n":"Karen Finnegan","a":"Pivot","b":"Karen Finnegan, PhD, MPH, is a public health researcher with more than twenty years of experience conducting research into health systems in countries around the world. She is a Research Scientist at Harvard Medical School and the Director of Science and Impact at Pivot, leading research activities for the NGO, which works to strengthen the public health system in rural Madagascar."}]},{"id":"s247","t":"Discovery Stage: Introducing Climate-Health Intelligence: The Next Frontier of Digital Health","d":"2026-12-04","s":"14:30","e":"15:00","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"This session looks at how linking climate, environmental and health data can help health systems anticipate and respond to climate-related risks, from heatwaves and floods to shifts in infectious disease. It brings together approaches in early warning, surveillance and decision support, and the data governance, interoperability and capacity needed to use them safely and equitably in countries.\n\nHosted by the World Meteorological Organization.","sp":[{"n":"Shona Kamps","a":"World Meteorological Organization (WMO)","b":""},{"n":"Mathew Keks","a":"World Health Organization (WHO)","b":"10+ years driving global public sector innovation and s…"}]},{"id":"s132","t":"Closing Plenary","d":"2026-12-04","s":"15:15","e":"16:00","tags":["Plenary","Hybrid Livestream"],"fmt":"Plenary","theme":"","mode":"Hybrid Livestream","desc":"","sp":[]},{"id":"s98","t":"Registration & Check In","d":"2026-12-04","s":"7:00","e":"16:00","tags":["In-person"],"fmt":"","theme":"","mode":"In-person","desc":"","sp":[]},{"id":"s221","t":"Discovery Stage: Paying, equipping and financing the frontline","d":"2026-12-04","s":"8:30","e":"9:00","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Three short presentations on paying, equipping and financing frontline health workers, including Cameroon's digital system for campaign worker payments, an inclusive decision support platform for community health workers and savings-based financing for digital health access.\n\nPresentations in this session:\n8298 - From Polio to Nationwide Campaign Payment Governance: Cameroon’s Digital System for Managing, Validating, and Paying Campaign Workers (Shalom J Tchokfe Ndoula)\n8738 - Designing for scale: Building an inclusive digital decision support and reporting platform for community health workers through human-centered design (Taufiq Sitompul, Nisa Nurkhotami)\n7387 - From Donor Subsidy to Household Resilience: Financing Sustainable Digital Health Access through Nano-Savings and Microinsurance in Bangladesh (Dr Rahul Mathew) [TBC]","sp":[{"n":"Shalom J Tchokfe Ndoula","a":"Expanded Programme on Immunization (EPI), Cameroon Ministry of Public Health","b":"Dr. Shalom J. Tchokfe Ndoula is a Cameroonian public health physician and epidemiologist, and serves as Director of the Expanded Programme on Immunization (EPI) within Cameroon’s Ministry of Public Health. He has played a leading role in advancing immunization and child health in Cameroon, including the country’s historic 2024 launch of the world’s first routine malaria vaccination programme for children.\n\nHis work focuses on strengthening immunization…"},{"n":"Taufiq Sitompul","a":"PATH","b":"Taufiq Sitompul is a digital health specialist with a background in information and communication technology and public health. He has spent more than 20 years strengthening Indonesia's health information systems, including designing health data interoperability, applying international health data standards, and building digital systems that link health services with data use. As Senior Digital Health Advisor at PATH, he leads the development and…"},{"n":"Nisa Nurkhotami","a":"PATH","b":""},{"n":"Dr Rahul Mathew","a":"World Vision","b":"Dr. Rahul Mathew Nimmagadda is a development and partnerships leader with over 15 years of experience designing and scaling innovative solutions across health, financial inclusion, livelihoods, climate resilience, and humanitarian response in Asia. He currently serves as Head of Resource Development and Communications at World Vision Bangladesh, where he leads strategic partnerships, resource mobilization, innovation, and external engagement initiatives.\n\nRahul…"}]},{"id":"s104","t":"From commitment to action: collaborating in support of country leadership and ownership of digital health transformation","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Interactive Workshop","Governance and Digital Health at Scale","In-person"],"fmt":"Interactive Workshop","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"A new WHO Global Strategy on Digital Health is in place, and the WHO Global Initiative on Digital Health is the main way to coordinate its adoption. Without national ownership, global commitments risk adding to the fragmentation the sector already faces. This interactive session brings together civil society, governments, multilateral agencies, academia and the private sector to define what coordinated, country-led action looks like in practice. It draws on Transform Health's Roadmap to 2030 and its national coalitions. Participants leave with a clearer view of the governance, legal and financing conditions governments need to lead their own digital health transformation.","sp":[{"n":"Nahashon Aluoka","a":"Transform Health","b":"Nahashon Aluoka is an advocacy, campaigns and policy specialist with over fifteen years of experience in Africa and globally. He has provided technical advocacy and campaign expertise and leadership over the years to successfully influence policy, legislation and knowledge, attitude and practices in different countries working on different themes including maternal and child health, ending violence against children, humanitarian advocacy, social…"}]},{"id":"s107","t":"From Diagnosis to Defense: Building Cyber Resilient Health Systems","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Pre-formed Panel","Cybersecurity, Resilience, and Continuity","In-person"],"fmt":"Pre-formed Panel","theme":"Cybersecurity, Resilience, and Continuity","mode":"In-person","desc":"Health systems are a frequent target of cyberattacks, and the consequences are growing. In 2025, a hospital in England reported that a cyberattack had contributed to a patient's death, and a breach at Kenya's M-TIBA digital health wallet exposed millions of records. Many governments still lack a structured way to assess their health sector's cybersecurity. This panel brings together the World Bank, WHO, Mongolia's Ministry of Health and South Korea's Health Insurance Review and Assessment Service to share how countries can assess cybersecurity maturity, set priorities and build health systems that can withstand and recover from attacks.","sp":[{"n":"Niki O'Brien","a":"The World Bank","b":"Niki O’Brien is a Data Governance / Health Specialist at the World Bank Group with substantial experience working in international NGOs and academia. She is also an Honorary Research Fellow at the Centre for Health Policy, Imperial College London, and has worked across research and policy projects to develop policy, technical capacity, and expertise across multiple subject areas. She has published several policy reports and more than 20 academic papers…"},{"n":"Gerelt-Od Lkhagvasuren","a":"Center for Health Development, Ministry of Health Mongolia","b":"Gerelt-Od Lkhagvasuren is a Mongolian leader at the intersection of education, management, and technology, with a distinguished career spanning academic leadership, institutional development, and digital transformation. She holds a PhD in Educational Administration, an MBA from the Mongolian National University, and a Bachelor's degree in Software Engineering, complemented by studies in English language and finance management. Her global outlook has…"},{"n":"Natschja Ratanaprayul","a":"World Health Organization","b":"Natschja Ratanaprayul is a Technical Officer in the Department of Data, Digital Health, Analytics and AI at the World Health Organization Headquarters in Geneva. She leads WHO's SMART Guidelines programme, an initiative transforming how WHO develops and implements normative guidance across to support implementation in digital and AI systems. She has provided direct technical support to over 45 countries across all six WHO regions. She also plays a…"},{"n":"Hee-sung Jung","a":"South Korea Health Insurance Review and Assessment Service (HIRA)","b":"Heesung Jung is a deputy director who has engineered HIRA's national digital healthcare platform for 18 years. He designed HIRA's first cloud-native architecture and led a variety of digital healthcare projects, including AI initiatives. He also led Bahrain's SEHATI-IT project, exporting Korea's national healthcare information system."},{"n":"Malarvizhi Veerappan","a":"World Bank","b":"Malarvizhi (“Malar”) Veerappan is a Program Manager at the World Bank, specializing in data governance, digital transformation, and technology modernization. With over two decades of experience, she has led complex institutional initiatives to modernize data systems, strengthen governance, and scale digital platforms that support evidence-based policymaking and service delivery. Malar played a key role in launching the World Bank’s Open Data…"}]},{"id":"s106","t":"Individual Presentations: Digital and AI-Ready Hospitals: Diagnostics, Governance and Resilience","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on making hospitals digitally ready and AI-ready, covering data science capacity at Douala General Hospital, governance of networked medical devices, smart hospitals in Thailand, radiology systems and AI-assisted cervical cancer triage in Rwanda.\n\nPresentations in this session:\n7952 - Creating an AI-Ready Hospital: The Data Science Without Borders (DSWB) Experience at Douala General Hospital in Cameroon (François Anicet Onana Akoa, Miranda Barasa, Bertrand Hugo Mbatchou Ngahane)\n8180 - Networked Medical Devices as Institutional Data Assets: A Governance Framework for Public Tertiary Hospitals (Jaime Kristoffer Punzalan)\n8818 - From Digital Infrastructure to Data Governance: Scaling Smart Hospitals Across Thailand’s Public Health System, 2024–2026 (NITCHANUND TANTISIRIVIT, Jarupol Tuangsirisup, Nardanong Charoensuntisuk)\n8663 - From Contingency to Routine Practice: Digital Resilience and the Early Stages of Scaling a Radiology System in Sri Lanka (Malinda Wijeratne)\n7452 - AI-Assisted Cervical Cancer Triage in Rwanda: Deep Learning Classification of Histopathology Images in a Resource-Constrained Pathology Setting (Piero Mazimpaka Irakiza)","sp":[{"n":"François Anicet Onana Akoa","a":"Douala General Hospital","b":"Dr. ONANA AKOA François Anicet is a digital health and implementation science expert leading efforts to transform hospitals into AI-ready learning health systems across Africa. As Country Project Coordinator for the Data Science Without Borders (DSWB) initiative at Douala General Hospital, Cameroon, he coordinates the implementation of interoperable health data systems, OMOP Common Data Model (OMOP-CDM), AI readiness, and capacity-building programs…"},{"n":"Miranda Barasa","a":"African Population and Health Research Center(APHRC)","b":"Miranda Barasa is a Program Manager in the Data Science Program at the African Population and Health Research Center (APHRC), where she leads the implementation of multi-country initiatives advancing artificial intelligence (AI), data science, and digital health across Africa. She manages the Data Science Without Borders (DSWB) programme and the Evidence for AI in Health (EVAH) initiative, working with governments, research institutions, and global…"},{"n":"Bertrand Hugo Mbatchou Ngahane","a":"Douala General Hospital, Cameroon","b":"Prof. Bertrand Hugo Mbatchou Ngahane is a Cameroonian physician, pulmonologist, occupational medicine specialist, researcher, and Professor at the Faculty of Medicine and Pharmaceutical Sciences of the University of Douala. He is a Consultant in Pulmonary and Occupational Medicine and serves as Head of the Division of Research, Training, Innovation and Cooperation at Douala General Hospital, where he contributes to strengthening research, innovation,…"},{"n":"Jaime Kristoffer Punzalan","a":"Zamboanga City Medical Center","b":"Jaime Kristoffer Punzalan is a physician currently working at Zamboanga City Medical Center and Ateneo de Zamboanga University, where he oversees programs and research in health enterprise architecture, biomedical engineering, and health systems and policy development. His work is grounded in a commitment to data-driven decision-making and the use of digital health solutions to improve healthcare delivery in Western Mindanao. His work is anchored in a…"},{"n":"NITCHANUND TANTISIRIVIT","a":"Ministry of PUBLIC Health Thailand","b":"​Dr. Nitchanund Tantisirivit, M.D., MPH Current Position: ​Deputy Director, Digital Health Bureau, Office of the Permanent Secretary, Ministry of Public Health (MOPH), Thailand ​Profile Summary: Dr. Nitchanund is a visionary pediatrician and healthcare executive specializing in public health policy and digital health transformation. She currently serves as the Deputy Director of the Digital Health Bureau under Thailand's Ministry of Public Health,…"},{"n":"Jarupol Tuangsirisup","a":"Ministry of public health Thailand","b":"​Dr. Jarupol Tuangsirisup is an Emergency Physician and a prominent leader in digital health transformation in Thailand. He currently serves as the Deputy Director of the Digital Health Office at the Ministry of Public Health (MOPH) and the Deputy Director of the Digital Health Mission Group at Kalasin Hospital. With deep expertise in data analytics, strategic design, and project management, Dr. Jarupol leads several of Thailand's milestone national…"},{"n":"Nardanong Charoensuntisuk","a":"Ministry of public health Thailand"},{"n":"Malinda Wijeratne","a":"Postgraduate Institute of Medicine, University of Colombo, Sri Lanka","b":"Dr. Malinda Wijeratne is medical doctor specializing in MD Health Informatics at Postgraduate Institute of Medicine, University of Colombo, Sri Lanka. He holds an MSc in Biomedical Informatics and an MBA in Hospital and Healthcare Services. He previously worked at Lady Ridgeway Hospital, supporting the development, implementation, and optimization of clinical information systems. He is also a contributor to the Ministry of Health Technical Working…"},{"n":"Piero Mazimpaka Irakiza","a":"Ministry of Health","b":"Piero Mazimpaka Irakiza is a Data Scientist, Biostatistician, and Digital Health Systems specialist working with Fionet Inc. and seconded to Rwanda’s Ministry of Health through the National Health Intelligence Centre. His work focuses on strengthening national health intelligence through data integration, automated data pipelines, advanced analytics, surveillance support, dashboards, and decision-support systems for public health action. He has…"}]},{"id":"s103","t":"Individual Presentations: Digital Innovation for Equitable Access to Essential Health Services","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on digital innovations that widen access to essential services, including machine learning for HIV care, AI-enabled self-care, out-of-pocket costs in digital family planning, a child health app for Francophone Africa and a review of digital tools for non-communicable diseases in underserved Southeast Asian populations.\n\nPresentations in this session:\n7746 - An Explainable Multi-Outcome Machine Learning Framework for Personalized HIV Clinical Decision Support in Zambia (Joe Phiri, Innocent Chiboma, Mwansa Lumpa, Aaron Zimba, Andrew Kashoka)\n8024 - Rethinking entry and access to care: AI-enabled self-care as HIV service infrastructure (Dino Rech)\n8566 - Can policy be implemented if it cannot be measured? Lessons from scaling DMPA-SC self-injection in Kenya (Jane Mutegi)\n8718 - Why Insured Women Still Pay Out-of-Pocket: Lessons from Kenya's Digital Family Planning Ecosystem (Agnes Ngure)\n7601 - Aina: A Pediatric Health PWA for Growth Tracking and Vaccination Support in Francophone Africa (Rakotoarivony Tokiniaina, Helminah Malalaniaina Randriamananoro)","sp":[{"n":"Joe Phiri","a":"CIDRZ","b":"Dr. Joe Phiri is a Health Information Systems professional with over 12 years of experience across Zambia and Southern Africa. He currently serves as Strategic Information Manager – Health Information Systems at the Centre for Infectious Disease Research in Zambia (CIDRZ). He holds a PhD in Computing and Data Science from ZCAS University, a Master of Science in Computer Science from the University of Zambia, and a Bachelor of Science in Computing from…"},{"n":"Innocent Chiboma","a":"Ministry of Health"},{"n":"Mwansa Lumpa","a":"Centre for Infectious Disease Research in Zambia (CIDRZ)"},{"n":"Aaron Zimba","a":"ZCAS University"},{"n":"Andrew Kashoka","a":"Centre for Infectious Disease Research in Zambia, P.O. Box 34681, Stand 378A / 15, Main Street, Ibex Hill, Lusaka, Zambia"},{"n":"Dino Rech","a":"Audere Africa","b":"Dino is a recognized global health leader, published researcher, and ER physician with first-hand knowledge of how technology can both help and hinder clinical workflows. He has dedicated his career to the advancement of global health through research and innovation, holding leadership roles at organizations such as Centre for HIV and AIDS Prevention Studies (CHAPS) and The Aurum Institute. As CEO, Dino enthusiastically drives Audere&#39;s vision…"},{"n":"Jane Mutegi","a":"inSupply Health","b":"Name, Title: Jane Mutegi, Manager – Data Transformation Intelligence & Impact Work Background/Key Achievements: Jane is a results-oriented Monitoring, Evaluation, Accountability, and Learning (MEAL) specialist with 17 years of experience delivering on donor project requirements for major organizations, including the CDC, Gates Foundation, and USAID. She brings strategic vision, rigorous organization, and a strong collaborative approach to driving…"},{"n":"Agnes Ngure","a":"Jhpiego","b":"Agnes Ngure is a seasoned communications and marketing strategist with extensive experience designing and implementing health communication and demand generation programs across Africa. She currently serves as Regional Design & Demand Advisor at Jhpiego and Regional Marketing Advisor at Population Services International (PSI), where she leads multi-country initiatives focused on increasing demand for health products and services through evidence-based…"},{"n":"Rakotoarivony Tokiniaina","a":"WHO Madagascar","b":"Dr Tokiniaina Fanambinantsoa Rakotoarivony is a medical doctor and field epidemiologist with WHO-supported experience in vaccine-preventable disease (VPD) surveillance, EPI supervision, immunization campaigns and rapid field response in Madagascar. He is also a digital health innovator, passionate about developing clinical simulation systems (ClinicalSim) and pediatric mobile health applications (Aina) to support healthcare professionals in francophone…"},{"n":"Helminah Malalaniaina Randriamananoro","a":"Université Cheikh Anta Diop, Dakar","b":"Dr Helminah Malalaniaina Randriamananoro is a physician and pediatric resident at Université Cheikh Anta Diop in Dakar, Senegal. She created AINA, a digital child health application focused on growth monitoring, immunization support and locally relevant nutrition guidance for Francophone Africa. Her work brings pediatric practice and digital health design together."}]},{"id":"s101","t":"Individual Presentations: From Platforms to Ecosystems: Scaling and Sustaining Digital Health","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on moving from single platforms to sustainable national digital health ecosystems, with examples from Kyrgyzstan, Zambia, Mozambique and others covering telemedicine, enterprise architecture, mortality surveillance, malaria programme data and specialist referral at scale.\n\nPresentations in this session:\n8490 - Inside the National EMR: Integrating Open-Source Telemedicine into Kyrgyzstan's Digital Public Infrastructure (Neeraja Reddy Karna)\n7530 - From Crisis to Ecosystem: An Enterprise Architecture Journey through Pandemic Response, National Health Transformation, and Global Impact (Francis del Rosario Uy)\n8202 - Evaluation of Zambia's National Mortality Surveillance System Following Implementation of the Integrated Multisectoral Mortality Surveillance Strategic Plan (Mohamed Talib)\n7381 - Specialist care in minutes, at scale: implementation and impact of a smartphone referral and teleconsultation platform across public and private health systems (William Mapham)\n8634 - Using Digital Health Systems to Enable Subnational Tailoring for Malaria Control in Mozambique (Nelson Cossa, Mariana da Silva)","sp":[{"n":"Neeraja Reddy Karna","a":"Intelehealth","b":"I lead technology with a focus on scale, execution, and real-world impact. As VP of Technology at Intelehealth, I own the end-to-end technology charter, spanning platform architecture, AI integration, interoperability, and global deployments - building systems designed to scale reliably to millions of users."},{"n":"Francis del Rosario Uy","a":"Sinag Solutions","b":"Francis Uy serves as a Core Architect for the World Health Organization (WHO) and ITU on Digital Public Infrastructure for Health (DPI-H), shaping global digital health standards, and co-chairs The Open Group Healthcare Forum. He advises the World Bank on foundational Digital Public Infrastructure and Digital Nutrition, and leads architecture initiatives for the Asian Development Bank and the Philippine Department of Information and Communications…"},{"n":"Mohamed Talib","a":"Africa CDC","b":"I am a Public Health Informatics professional at Africa CDC, committed to translating strategic goals into actionable partnerships that improve community health and address global hunger. With over three years of experience, I bring a clear vision: to support sustainable, data-driven collaborations that strengthen public health systems, promote health equity, and uphold human rights principles. My professional background is rooted in epidemiology,…"},{"n":"William Mapham","a":"Vula Medical","b":"Dr William Mapham (MBChB, DipOphth, FCOphth) is an ophthalmologist and the founder and CEO of Vula Medical. His experience working as a doctor in under-resourced, rural settings — where getting timely specialist advice for a patient could be slow or impossible — was the catalyst for Vula, a smartphone-based referral and teleconsultation platform he launched in 2014. What began with eye referrals has grown into one of Africa's largest digital referral…"},{"n":"Nelson Cossa","a":"Celinka Survey Consultoria e Servicos Lda","b":"Nelson Cossa is the Executive Director of Celinka Survey Consulting & Services in Mozambique and a public health researcher specializing in malaria surveillance, digital health, monitoring and evaluation, and health systems strengthening. He has led national and international studies on malaria control, health information systems, programme evaluation, and implementation research in collaboration with the Ministry of Health, Harvard T.H. Chan School of…"},{"n":"Mariana da Silva","a":"MoH - National Malaria Control Program - Mozambique"}]},{"id":"s220","t":"Introducing the Open Health Stack Software Foundation: Shaping the Future of Standards-Based Global Digital Health Innovation Together","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Sponsored Breakout","In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"Following its July 2026 intention-to-launch announcement by the Linux Foundation—backed by Google, the World Health Organization (WHO), Anthropic, Endless Health, and with support from over 20 global partners—the Open Health Stack Software Foundation (OHS-SF, ohs.foundation) is establishing a vendor-neutral, community-governed home for shaping the future of standards-based global digital health innovation together.\n\nGrounded in global open standards for health and AI (HL7 FHIR, MCP, and Skills), OHS-SF stewards shared open-source building blocks - as global goods - for advancing digital health and AI innovation, with a clear boundary: the Foundation maintains and drives innovation around the shared infrastructure layer (the “building blocks”), while developers and implementers build end-user applications.\n\nDesigned as an informal 40-minute community breakout, this session covers where the Foundation stands today, where it is headed in 2027, and how builders and organizations can get involved:\n\nWelcome & Foundation Introduction: Why neutral Linux Foundation stewardship matters for long-term sustainability, who is involved across the founding coalition, and how shared building blocks help close health equity gaps.\nPillar Working Groups: Rapid updates across the OHS-SF pillars - FHIR Foundations, OHS Player Reference Toolkit and AI Commons - how developers are using these tools, regional ecosystem engagement and developer capacity building.\nLooking Ahead to 2027 & Getting Involved: Current thinking for 2027 alongside clear pathways to participate - from inclusive Linux Foundation memberships (including zero-fee Associate tiers and LMIC implementer pathways) to joining working groups and contributing code.\n\nShort presentations will be followed by a facilitated panel with key OHS SF leadership and supporters and open Q&A\n\n- Panel members: Rubayat Khan (Endless Health), Garrett Mehl (WHO), Adele Waugaman (Gates Foundation), Steven Wanyee (IntelliSOFT) and Fred Hersch (Google)\n- Panel facilitator: Smisha Agarwal (Johns Hopkins)\n- Other presenters: Jing Tang, Matt Berg, Roy Munge, Fikri Milano\n\nThe session is broadly applicable to the Global Digital Health ecosystem including MoH, Funders, NGOs, Technology groups and implementers.","sp":[{"n":"Fred Hersch","a":"Google","b":"Dr. Fred Hersch is a Senior Product Manager at the Google DeepMind Impact Accelerator, where he leads AI for Social Impact initiatives in global public health. A self-described \"Global Health Technologist,\" he is a former engineer turned medical doctor and corporate social innovator. Previously the Product Lead for Open Health Stack (OHS) at Google Research, he led its transition to the Linux Foundation - establishing a neutral, community-owned home for open-source building blocks that help developers everywhere create standards-based, AI-ready health solutions. He continues to serve the OHS Software Foundation as a Google Governing Board Member and \"Acting\" Executive Director. Across his work, Fred is dedicated to catalyzing sustainable approaches to local innovation that advance safe, effective, AI-powered digital health."},{"n":"Smisha Agarwal","a":"Johns Hopkins Bloomberg School of Public Health","b":"Smisha Agarwal, is Director of the Center for Global Digital Health Innovation and Associate Professor of International Health at the Johns Hopkins Bloomberg School of Public Health, and Editor-in-Chief of Oxford Open Digital Health. A trialist, she has led more than two dozen evaluations of digital and AI programs across ten countries, and her WHO-commissioned Cochrane reviews informed WHO’s digital health guidelines. She now studies safe, equitable AI in low-resource health systems, including civil registration systems, governance and speech technology for under-served languages. Her work has informed policy and strategy for governments and for normative and multilateral agencies."},{"n":"Rubayat Khan","a":"Endless Foundation","b":"Rubayat Khan is Head of AI and Director of Health Programs at Endless Foundation, where he leads a portfolio of AI and digital health investments aimed at health and education systems transformation globally. Previously, Rubayat has founded and scaled digital-health and data-for-development ventures across Africa and Asia that have collectively impacted over 100 million people. He has received fellowships from Acumen, Mulago Foundation and Aspen Institute, and sits on the board of Instiglio and the Alliance for Health Policy & Systems Research at the WHO.\n\nA sought-after writer and speaker known for taking a first principles approach to applying exponential tech for amplifying human agency and social impact, Rubayat has briefed cabinet ministers, world health leaders and Fortune 500 executives on what comes after ChatGPT. He lives in Baltimore with his wife and two children, and all of them unequivocally agree that he is a nerd."},{"n":"Garrett Mehl","a":"World Health Organization","b":"Dr Garrett Mehl is the Head of the Digital Health and Information Systems Unit in the Department of Data, Digital Health, Analytics and AI (DDA) of the World Health Organization. Garrett leads a team who work on topics including a WHO-ITU Reference Architecture on Digital Health Transformation; Geographic Information Systems, SCORE HIS country assessment, Health Facility Assessment, SMART Guidelines; mechanisms to support country production of digital systems with quality assured content and interoperability standards; the Global Digital Health Certification Network (GDHCN), a global digital public infrastructure for verifiable health documents."},{"n":"Adele Waugaman","a":"Gates Foundation","b":"Adele Waugaman has two decades of experience building the policy, program, financing, and partnership infrastructure that enables digital technologies, including AI, to deliver value in developing countries. In her current role at the Gates Foundation, she leads advocacy strategies supporting the strategic introduction and scale-up of AI for development innovations. Previously, she led digital health policy at USAID, and a $30M partnership between the United Nations Foundation and Vodafone Foundation advancing digitally enabled health and humanitarian programs. She has helped catalyze financing coalitions including the AI for Development Funders Collaborative and Digital Square at PATH, co-authored and edited reports such as Fighting Ebola with Information and Disaster Relief 2.0, and co-chaired field-building communities of practice including the Digital Health & Interoperability Working Group. She helped conceptualize the first mHealth Summit in 2009, the predecessor to the Global Digital Health Forum."},{"n":"Steven Wanyee Macharia","a":"IntelliSOFT Consulting Limited","b":"Steven Wanyee Macharia is a health informatics leader with 30 years of experience using technology and data to transform healthcare across Africa. Through his work supporting more than 25 countries and as founder of IntelliSOFT Consulting Limited, he partners with governments, UN agencies, and tech leaders to build sustainable digital health systems and open-source solutions like OpenMRS and OpenHIE. A champion for local talent and leadership, Steven serves on several regional boards—including as Deputy Board Chair of the Africa Digital Health Networks—and holds advanced degrees from the Universities of Liverpool and Washington, along with a Ph.D. specializing in health informatics and Ubuntu Health AI."}]},{"id":"s100","t":"Strategic Pillars to enable AI scale up: What should Governments and health systems get right early on?","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Pre-formed Panel","AI for Health","Hybrid Livestream"],"fmt":"Pre-formed Panel","theme":"AI for Health","mode":"Hybrid Livestream","desc":"Many countries are writing national AI strategies for health, but there is little agreement on how to turn principles of responsible AI into a coherent strategy, which institutions to build, or what should come first. This panel uses India's Strategy for AI in Healthcare (SAHI), one of the first comprehensive national AI strategies in WHO's South-East Asia Region, as a worked example. Speakers from Jhpiego, WHO's South-East Asia and Eastern Mediterranean regional offices, India's National Health Authority and the Asia Pacific Observatory on Health Systems and Policies discuss the building blocks of a national AI strategy and what governments should get right early on.","sp":[{"n":"Anunaya Jain","a":"Jhpiego","b":"Dr. Anunaya Jain is a physician, digital health strategist, and innovation leader with extensive experience driving health systems transformation through technology, data, and artificial intelligence. He serves as Technical Director for Digital Health and Data Science at Jhpiego, where he leads global initiatives focused on digital health, AI for health, data science, and health system innovation across low- and middle-income countries. With a…"},{"n":"Karthik Adapa","a":"Regional Advisor – Digital Health & Artificial Intelligence, WHO SEARO)","b":"Dr. Karthik Adapa is a physician, public health expert, and Indian Administrative Service (IAS) officer of the 2008 Punjab cadre, currently serving as Regional Adviser, Digital Health and AI at the World Health Organization South-East Asia Regional Office (WHO-SEARO). In this role, he provides strategic leadership to countries across the region on digital health transformation, artificial intelligence governance, health data systems, interoperability,…"},{"n":"Sunil Kumar Baranwal","a":"Chief Executive Officer, National Health Authority, Ministry of Health & Family Welfare, India (SAHI Chair)","b":"Dr. Sunil Kumar Barnwal is a senior Indian Administrative Service (IAS) officer with over two decades of experience in public policy, governance, and public sector management. Over the past five years, he has served in key leadership positions with the Government of India. As Joint Secretary in the Ministry of Home Affairs, he played a pivotal role in designing the Vibrant Villages Programme to strengthen development and resilience in India's border…"},{"n":"Nima Asgari Jirhandeh","a":"Director, Asia Pacific Observatory on Health Systems and Policies","b":"Dr. Nima Asgari-Jirhandeh is Director of the Asia Pacific Observatory on Health Systems and Policies (APO), a partnership hosted by the World Health Organization that supports evidence-informed health policy and systems strengthening across the Asia-Pacific region. With more than two decades of experience in public health, health systems development, and international health cooperation, he leads the Observatory's work on generating policy-relevant…"},{"n":"Novera Ansari","a":"Technical Officer – Digital Health & Innovations, WHO Regional Office for Eastern Medditerrain (EMRO)","b":"Dr. Novera Ansari is a digital health specialist and global health leader serving as Technical Officer for Digital Health at the World Health Organization Regional Office for the Eastern Mediterranean (WHO EMRO). With expertise spanning digital transformation, health information systems, digital health governance, and health technology implementation, she supports countries across the Eastern Mediterranean Region in developing and scaling digital…"},{"n":"Mengji Chen","a":"Technical Lead, Research, Ethics and Innovation, WHO Regional Office for the Western Pacific (WIPRO)","b":"Dr. Mengji Chen is a health innovation and technology governance specialist working with the World Health Organization Western Pacific Regional Office (WHO WPRO). His work focuses on the governance of emerging technologies, artificial intelligence for health, digital transformation, and fostering innovation ecosystems that support stronger and more equitable health systems across the Western Pacific region. Drawing on experience at the intersection of…"},{"n":"Paulin Basinga","a":"Director, Gates Foundation, Africa","b":"Dr. Paulin Basinga is Director for Africa at the Gates Foundation, where he leads the foundation’s work across the African continent and oversees strategic partnerships, investments, and initiatives spanning health, nutrition, agriculture, gender equality, and financial inclusion. Based in Nairobi, he works closely with governments, regional institutions, development partners, and the private sector to advance sustainable development and human capital…"},{"n":"Emilie Chambert","a":"Chief Executive Officer, Living Goods","b":"Dr. Emilie Chambert is Chief Executive Officer of Living Goods, a global nonprofit organization working with governments to strengthen community health systems through digitally enabled, data-driven approaches. With more than two decades of experience in international development, health systems strengthening, and organizational leadership, she has led initiatives across Africa, Asia, and Europe focused on improving health outcomes at scale through…"}]},{"id":"s105","t":"Testing What Works: Hands-On Experimentation for Social Sector Programs","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Interactive Workshop","Governance and Digital Health at Scale","In-person"],"fmt":"Interactive Workshop","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"Development organisations need to test and improve their programmes quickly, but traditional evaluations are slow and costly, and commercial A/B testing tools do not work for programmes delivered through WhatsApp, voice calls or community health workers. Evidential is a free, open-source tool from IDinsight that lets programme and M&E teams run randomised experiments without data scientists or engineers, while sensitive data stays on their own systems. In this hands-on workshop, participants design an experiment from start to finish: forming a testable hypothesis, sizing the sample with a power calculator and interpreting results.","sp":[{"n":"Srivatsan Ramesh","a":"IDinsight","b":"Srivatsan Ramesh is a Product Growth Manager at IDinsight, based in India. At IDinsight, Srivatsan leads the growth and maturity of the organization’s suite of products, working to expand their client and user base while developing the sustainable operating and financial models needed to scale them. His work sits at the intersection of product strategy and organizational development, building the product discipline and processes that will define how…"},{"n":"Mark Botterill","a":"IDinsight","b":"Mark Botterill is a data scientist at IDinsight and works on building data science solutions across various sectors in the global development space. He is a developer and solutions engineer on Evidential and is passionate about lowering the bar for organizations to run continuous experiments. Prior to IDinsight, Mark managed the global data science curriculum for the education company Le Wagon and worked as a Data Ambassador for the UK charity…"}]},{"id":"s102","t":"Youth Voices for People‑Centered Digital Transformation of Health Systems","d":"2026-12-04","s":"8:30","e":"9:30","tags":["Pre-formed Panel","Governance and Digital Health at Scale","In-person"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"Digital inequalities affect young people, women, people with disabilities and marginalised communities most, yet young people are underrepresented in digital health policy, implementation and evaluation. Convened by Transform Health, this panel brings together youth leaders and other stakeholders to share real examples of young people shaping digital health systems. It shows how the Youth Call to Action launched at GDHF 2025 is being put into practice, and discusses how governments, donors and organisations can involve young people meaningfully in digital health decisions.","sp":[{"n":"Caesar Kaba Kogoziga","a":"Transform Health","b":"Caesar is a Youth Policy Officer at Transform Health, working for the equitable digital transformation of health systems to advance Universal Health Coverage (UHC). He holds a Master’s degree in Health Economics and an Executive Diploma in Development Policies and Practices from the Geneva Graduate Institute. Caesar brings expertise in health systems strengthening, digital health, reproductive health programming, youth engagement and development,…"}]},{"id":"s222","t":"Discovery Stage: Strengthening frontline delivery","d":"2026-12-04","s":"9:00","e":"9:30","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Two short presentations on strengthening frontline delivery: facial recognition for workforce verification in malaria and Vitamin A campaigns in Bauchi State, Nigeria, and re-linking children with delayed immunisation to care through Ethiopia's national digital community health system.\n\nPresentations in this session:\n7954 - Finding the invisible: re-linking 88% of children with delayed immunization to care through a national digital community health system in Ethiopia (Dr. Bezawit Mesfin Hunegnaw)\n8592 - HWMS: Building Rwanda's National Digital Backbone for Health Workforce Lifecycle (Marie Elise Hortensia Ngabire Iradukunda, Alice Nsengiyumva)","sp":[{"n":"Marie Elise Hortensia Ngabire Iradukunda","a":"Ministry of Health Rwanda","b":"Dr. Marie Elise Ngabire is a medical doctor currently working in the Health Workforce development department in the Ministry of Health Rwanda, with experience in public health emergency response and health workforce development. Her work focuses on strengthening health systems and advancing digital transformation to improve how healthcare professionals are trained, employed, and supported. She is passionate about building resilient, equitable health and education systems by using digital innovation to improve emergency preparedness and expand access to healthcare. Driven by a commitment to sustainable impact, she seeks to contribute to solutions that strengthen local capacity and transform health service delivery across Africa."},{"n":"Alice Nsengiyumva","a":"Ministry of Health Rwanda","b":"Dr. Alice Nsengiyumva is a compassionate Medical Doctor and Global Health Delivery Specialist with multidisciplinary experience in clinical care, health systems strengthening, research, and workforce policy. Currently working in the Health Workforce development department, she is skilled in evidence synthesis, project coordination, and guideline development, with a proven ability to connect frontline clinical practice with strategic leadership. She is dedicated to advancing health equity, gender equality, and social justice through evidence-based decision-making in resource-constrained settings."},{"n":"Dorcas Essien","a":"Malaria Consortium","b":"Dorcas Essien is a Digital Health Manager at Malaria Consortium Nigeria, where she leads the design, implementation, and scale-up of digital solutions supporting large-scale public health interventions. She oversees digital health strategy and the deployment of digital platforms that strengthen programme delivery, workforce management, data use, and decision-making. With over eight years of experience in digital health and health informatics, she…"},{"n":"Dr. Bezawit Mesfin Hunegnaw","a":"JSI","b":"Bezawit M. Hunegnaw is the Deputy Projects Director at JSI Ethiopia, with over 15 years of experience in clinical and public health practice, programs leadership and research in RMNCH. She comes with expertise in strategic leadership, health systems strengthening and evidence-based practice. At JSI, she leads the design and implementation of interventions that aim to strengthen service delivery and quality of care in primary health care while also…"}]},{"id":"s115","t":"Advancing Global Interoperability through Standards Capacity Building and Regional Implementation: Experiences from  AeHIN, HELINA,RECAINSA and HL7 CAM","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Pre-formed Panel","Interoperability and Digital Public Infrastructure","In-person"],"fmt":"Pre-formed Panel","theme":"Interoperability and Digital Public Infrastructure","mode":"In-person","desc":"FHIR has become a cornerstone standard for health information exchange, but countries also need skilled staff, governance and leadership to use it sustainably. This panel brings together three regional networks, the Asia eHealth Information Network (AeHIN), the Pan African Health Informatics Association (HELINA) and RECAINSA in the Americas, along with HL7 Central America and the Dominican Republic and the World Bank. Speakers share how regional collaboration has built standards capacity, supported country implementations and sped up FHIR adoption across very different health systems.","sp":[{"n":"Sosthenes Bagumhe","a":"The Pan African Health Informatics Association (HELINA)","b":"Mr. Sosthenes Bagumhe is a dynamic, visionary, and results-oriented Global Digital Health leader with extensive experience in Health Information Systems (HIS) across Tanzania Mainland, Zanzibar and in African Region in the planning, design, implementation, and use of national and large-scale digital health systems. He possesses strong expertise in senior-level systems analysis, business process re-engineering, digital health leadership and governance,…"},{"n":"Daniel Otzoy","a":"HL7 Central America and Dominican Republic Affiliation (HL7-CAM)","b":"Daniel Otzoy-Garcia is CEO and Project Manager of HL7 Central America and the Dominican Republic. He has over 20 years of experience in digital health, health information systems, interoperability, and digital transformation across Latin America, the Caribbean, Africa, Asia, and the United States. His work focuses on standards-based health data exchange, governance, capacity building, and the responsible adoption of emerging technologies in health…"},{"n":"Joseline Carias-Galeano","a":"The Americas Health Informatics Network in Health Informatics (RECAINSA)","b":"Joseline Carías Galeano is an international consultant, speaker, mentor, and project management expert recognized for her leadership in digital health across the globe. She currently serves as Executive Director of RECAINSA, one of the region’s most influential digital health networks in LAC, leading initiatives that support the development and implementation of national and regional digital health strategies. She is also co-creator of innovative…"},{"n":"Jai Ganesh Udayasankaran","a":"Asia eHealth Information Network (AeHIN)","b":"Jai Ganesh Udayasankaran (Jai) is the Executive Director of the Asia eHealth Information Network (AeHIN). He brings over 20 years of experience in the planning, procurement, and implementation of digital health solutions, including web-based EMR, PACS, telehealth, and chronic disease management portals. Jai serves on several global bodies, including the Board of the Global Digital Health Network (GDHN), the eHealth Expert Committee of the Global South…"},{"n":"Matthew Hulse","a":"The World Bank Group","b":"Matthew Hulse (Matt) is the Program Manager for Digital Health and AI at the World Bank Group. With diverse experience in embedded devices and digital communication technologies, he bridges the worlds of public policy and technology investment. He has worked worldwide on digital health, telecommunications access issues expanding digital and economic development, equal and affordable access, and lifesaving information for humanitarian assistance. At the…"}]},{"id":"s114","t":"Designing inclusive AI-assisted qualitative data workflows with KoboToolbox","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Interactive Workshop","Workforce Capacity and Leadership for the Digital Future","In-person"],"fmt":"Interactive Workshop","theme":"Workforce Capacity and Leadership for the Digital Future","mode":"In-person","desc":"Open-ended responses capture community experiences and concerns that numbers alone miss, but collecting and analysing them at scale is slow, especially in multilingual settings and fast-moving emergencies. In this hands-on workshop, Kobo's health data and responsible AI team introduces KoboToolbox's AI-assisted tools for collecting, transcribing, translating and analysing audio responses. Participants build a short form with audio questions, collect responses on mobile devices and work through AI-assisted analysis, learning how to set up inclusive qualitative workflows for their own programmes.","sp":[{"n":"Salomé Garnier","a":"Kobo","b":"Salomé Garnier is a Research & Data Specialist at Kobo. With a Master's in Public Health, she brings advanced expertise in mixed-methods public health research, survey design, and digital data collection in complex settings. She has led end-to-end research projects across multiple regions, with a particular focus on social epidemiology and behavioral science applied to health, including vaccine hesitancy and reproductive health. At Kobo, she supports…"},{"n":"Joshua Beretta","a":"Kobo","b":"Joshua Beretta is the Humanitarian Project Coordinator at Kobo, where he supports the research and development of AI-enhanced data collection tools as a Solutions Architect. He specializes in humanitarian technology and information management in low-resource settings, with field deployment experience in emergency response and extensive work supporting humanitarian organizations in survey design workflows."}]},{"id":"s113","t":"Designing responsible data governance for sensitive digital health programs: a hands-on workshop from Francophone Africa","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Interactive Workshop","Governance and Digital Health at Scale","In-person"],"fmt":"Interactive Workshop","theme":"Governance and Digital Health at Scale","mode":"In-person","desc":"Many digital health teams collect data through KoboToolbox, spreadsheets, dashboards and partner forms but have no clear rules on which indicators matter, who validates them, who can see them and how they inform decisions. This hands-on workshop, using the experience of Centre ODAS / Ipas Francophone Africa, takes participants through a simple governance canvas for a fictional multi-country reproductive health programme. They identify where data is fragmented, choose priority indicators, map data flows, set privacy and access rules and sketch a decision dashboard. It is a design lab for implementers handling sensitive data, not a software demonstration.","sp":[{"n":"Noe Tanoh Ahoundjoueh","a":"Centre ODAS / Ipas Francophone Africa","b":"Noe Tanoh Ahoundjoueh is a Data Scientist and Monitoring, Evaluation, Data and IT Officer at Centre ODAS / Ipas Francophone Africa. He designs and maintains digital systems that connect KoboToolbox, Power BI dashboards, databases, VPS-hosted services, Moodle-based learning environments, and web platforms for reproductive health programs. His work focuses on data architecture, interoperability, digital learning, responsible data practices, and evidence…"}]},{"id":"s254","t":"Discovery Stage: Reaching the last mile","d":"2026-12-04","s":"9:40","e":"10:10","tags":["Discovery Stage","In-person"],"fmt":"Discovery Stage","theme":"","mode":"In-person","desc":"Two short presentations on reaching patients beyond the clinic: generative AI support for para-counsellors delivering community mental health care in Bangladesh, and using India's national NCD portal data to track cancer patients' journeys and continuity of care.\n\nPresentations in this session:\n8287 - AI-Assisted Counseling Support for Para-Counselors in Bangladesh (Abu Md. Akteruzzaman Bhuiyan)\n8173 - Making Every Cancer Patient Journey Visible: Leveraging Existing NP-NCD Portal Data for Longitudinal Pathway Tracking and Continuity of Care in India (Isha Dagar, Sanjay Dhir)","sp":[{"n":"Isha Dagar","a":"Indian Institute of Technology Delhi","b":"Isha Dagar is a Project Scientist at the Department of Management Studies, Indian Institute of Technology Delhi, working at the intersection of public health systems, digital health, programme implementation, and data-driven decision support. She holds a Master of Public Health degree and has experience in non-communicable disease research, tobacco cessation, cancer prevention, health systems strengthening, and public…"},{"n":"Sanjay Dhir","a":"Indian Institute of Technology Delhi","b":"Prof. Sanjay Dhir is Professor of Strategic Management and Area Chair at the Department of Management Studies, Indian Institute of Technology Delhi. His research and consulting work spans strategic innovation, public health systems, digital health, implementation research, healthcare equity, programme evaluation, and evidence-to-policy translation. He has led and contributed to several…"},{"n":"Abu Md. Akteruzzaman Bhuiyan","a":"mPower Social Enterprises Limited","b":"Dr. Akteruzzaman Bhuiyan is a digital health systems specialist who, since 2022, has served as Digital Health Advisor at mPower, following leadership roles at Pathfinder International and D.Net. His work centres on building country-owned, interoperable platforms that link OpenSRP, OpenMRS, DHIS2, SHR, and BRN/NID, translating policy goals into operational tools that extend reach, improve quality, and institutionalise data use. At mPower, he contributed…"},{"n":"Mridul Chowdhury","a":"mPower Social Enterprises Limited","b":"Mridul Chowdhury is the Founder and Chief Executive Officer of mPower Social Enterprises Ltd., a Bangladesh-based social enterprise founded in 2008 that leverages technology, data, and human-centered design to address complex development challenges across health, agriculture, education, and livelihoods. A pioneer in the field of ICT for Development (ICT4D), Mridul has over two decades of experience in designing and scaling digital solutions that…"}]},{"id":"s111","t":"Individual Presentations: AI That Works Locally: Validation, Language and Contextual Adaptation","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on making AI work in local contexts, including evaluation benchmarks for low-resource languages such as Burmese, open validation methods, language tools as public infrastructure, modular AI infrastructure and AI-assisted mapping to ICD-11.\n\nPresentations in this session:\n8275 - A Clinician-Built Benchmark and Framework for Evaluating Medical AI in Burmese, a Low-Resource Language (Kaung Khant Tin, Hein Thu)\n8232 - MOOVE - Massive Online Open Validation and Evaluation (Sahaj Vaidya)\n8049 - Bridging the Digital Divide: AI-Driven Linguistic Unification as Public Infrastructure for Equitable Health Governance (Gaston Alimasi)\n7508 - Integrate Once, Deploy Everywhere: A Modular Health AI Infrastructure for Scaling Clinically Validated AI across Vietnam and ASEAN (Francis Nguyen, Harald Braun)\n7861 - Bridging Local Data to ICD-11: AI-Assisted Semantic Mapping and the Central Role of Curated Interface Terminology (Jonathan Payne)","sp":[{"n":"Kaung Khant Tin","a":"FOC Teleclinic"},{"n":"Hein Thu","a":"National University of Singapore"},{"n":"Sahaj Vaidya","a":"Koita Centre for Digital Health, Ashoka University","b":"Sahaj Vaidya is a Senior Research Associate at the Koita Centre for Digital Health, Ashoka University, and a PhD scholar working at the intersection of artificial intelligence, governance, and public health systems. She is was a Visiting PhD Researcher at the LiGHT Lab (Laboratory for Intelligent Global Health and Humanitarian Response Technologies), EPFL, Lausanne, Switzerland, where her work focuses on participatory and continuous evaluation of large…"},{"n":"Gaston Alimasi","a":"The Drc Climate Change Network","b":"Gaston Sabuni Alimasi is a Research Manager at the DRC Climate Change Network (RCCRDC) and a development economist with a background in Management Information Systems. He specializes in bridging the gap between empirical econometric modeling and field-based digital innovation. Gaston’s work focuses on designing AI-powered frameworks for linguistic unification in Kiswahili, serving as a foundational digital public infrastructure (DPI) to enhance health…"},{"n":"Francis Nguyen","a":"OneMedic Joint Stock Company","b":"Francis Nguyen (Nguyễn Anh Tuấn) is the Founder and CEO of OneMedic, a Vietnamese health-technology company building a modular Health AI Infrastructure for Vietnam and ASEAN. Guided by the principle \"integrate once, deploy everywhere,\" OneMedic connects clinically validated diagnostic AI to a longitudinal patient-record substrate and deploys it from tertiary hospitals down to commune health stations. The company was selected into Mayo Clinic Platform…"},{"n":"Harald Braun","a":"OneMedic","b":"Prof. Dr. Harald Braun is the co-founder of OneMedic and the founder and creator of i5 Health AI. He leads the development of MedicAI — OneMedic's Layer 3 multimodal risk model and the evolution of i5 — including its work within the Mayo Clinic Platform Accelerate program (2026). Holding a PhD in Artificial Intelligence and Algorithms, he brings over 25 years in healthcare analytics and roughly 60 academic publications across predictive diagnosis,…"},{"n":"Jonathan Payne","a":"Open Concept Lab","b":"Jonathan Payne is the Founder and Executive Director of the Open Concept Lab (OCL), a recognized digital public good whose open-source terminology tools are foundational Digital Public Infrastructure (DPI) for health systems in multiple countries. An engineer turned global health informaticist, he has spent twenty years building digital health solutions across low- and middle-income countries, from mobile tools for community health workers with…"}]},{"id":"s224","t":"Individual Presentations: Beyond Pilots: Scaling Digital Solutions into Public Health Infrastructure","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on moving digital solutions from pilots into public health infrastructure, covering school-based disease surveillance, a malaria tool in Burundi's national strategy, AI for TB surveillance in Kenya, autonomous logistics in African health systems and open climate-health data infrastructure for mortality surveillance in Malawi.\n\nPresentations in this session:\n7764 - From Classrooms to Early Warning: Operationalizing the 7-1-7 Framework Through School-Based Digital Disease Surveillance in Antipolo City, Philippines, 2024-2026 (Daniel III Garcia)\n8541 - From Pilot to Policy: Embedding Malariya Pi in Burundi's National Digital Health Strategy (Dino Rech, Leila Kaza, Mathias NSABIMANA)\n7128 - Operationalizing AI for National TB Surveillance and Decision Support in Kenya: Lessons from the TIBU Ecosystem (MARTIN GITHIOMI)\n8206 - From Pilot to Public Health Infrastructure: Scaling Autonomous Logistics in African Health Systems (Tom White)\n7522 - Integrating Climate and Health Data in Malawi: An Open, Replicable Digital Infrastructure for Climate-Informed Mortality Surveillance (Dorothy Mailosi, Jay Greenfield, Letisha Najjemba)\n8447 - Making Labour-Room Data Actionable at Scale: MaNTrA, Uttar Pradesh’s State-Owned Maternal and Newborn Platform (Girdhari Bora)","sp":[{"n":"Daniel III Garcia","a":"City Government of Antipolo","b":"Field epidemiologist with over 11 years of experience as a Program Manager of Public Health Surveillance from the City Health Office - City Epidemiology, Health Statistics, Disaster, and Response Unit (CHO-CESDRU) of City Government of Antipolo. Skilled in conducting epidemiological investigations, analyzing data, and developing targeted interventions."},{"n":"Dino Rech","a":"Audere Africa","b":"Dino is the CEO of Audere and CEO/Founder of Audere Africa, an NGO pioneering global digital health equity leveraging AI. As a health systems delivery expert, published researcher, ER physician, and experienced global health leader having held roles at CHAPS, the Gates Foundation, and the Aurum Institute - Dino has deep experience with a variety of public and private health program domains and first-hand knowledge of how technology can both help and…"},{"n":"Leila Kaza","a":"PNLP (National Malaria Control Program), Burundi Ministry of Public Health","b":"Dr. Leila KAZE is a Medical Doctor with 5 years of experience in malaria control, policy design, monitoring, and evaluation within the National Malaria Control Program (NMCP). She earned her Doctor of Medicine from Xi’an Jiaotong University. She is proficient in multiple languages, including French and English, and is skilled in advanced tools like DHIS2, SurveyCTO, and MS Excel. She currently serves as the Head of Malaria Case Management for the…"},{"n":"Mathias NSABIMANA","a":"National Malaria Control Program (NMCP), Ministry of Public Health, Burundi","b":"Director of the National Malaria Control Program (NMCP) of Burundi."},{"n":"MARTIN GITHIOMI","a":"MOH Kenya","b":"Martin is software designer and digital health consultant with extensive experience in spearheading digital transformation initiatives within public health programs. He specializes in onboarding cutting-edge technology concepts to sustain patient-centric solutions, with a proven track record of designing and implementing impactful digital tools for tuberculosis and cancer control programs. Martin is also skilled in project management, data management,…"},{"n":"Tom White","a":"Zipline","b":"Tom White is Zipline's General Manager for Asia-Pacific, responsible for establishing the company's presence and operations across the region. He joined from Archer Aviation, an eVTOL manufacturer, where he led Asia-Pacific. Before that, he spent nine years at Uber in senior roles across Australia, Vietnam, Japan and Korea, including serving as General Manager for both Vietnam and Japan, and as the founding CEO of Uber's joint venture with SK Group…"},{"n":"Dorothy Mailosi","a":"CODATA","b":"Dorothy Mailosi is a data scientist and research assistant at CODATA and a master's candidate in data science at Deakin University. Her work spans climate and health analytics, FAIR data implementation, health informatics, and research data infrastructure development. She has contributed to mental health data harmonization projects and the implementation of the OMOP Common Data Model for population health research. Dorothy is currently leading the…"},{"n":"Jay Greenfield","a":"CODATA","b":""},{"n":"Letisha Najjemba","a":"CODATA","b":""},{"n":"Girdhari Bora","a":"Tattva Foundation","b":"Girdhari Bora is an ICT4D expert with 20 years of experience driving digital transformation and action research in rural communities. Currently the Chief Innovation Officer at Tattva Foundation, he has directly led the ideation, design, and development of digital solutions that enable over 1 million users, driving scalable impact for a population exceeding 240 million. A recognized thought leader in digital health, his work encompasses strategic…"}]},{"id":"s112","t":"Individual Presentations: Digital Innovation for Youth, Mental Health and Wellbeing","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Individual Presentation","In-person"],"fmt":"Individual Presentation","theme":"","mode":"In-person","desc":"Five presentations on digital tools for young people's mental health and wellbeing, including disability-inclusive AI, culturally adapted screening in Nigeria, school-based mental health in Thailand's border communities, an adolescent health chatbot in India and the cost-effectiveness of an app for childhood obesity.\n\nPresentations in this session:\n7344 - Closing the Data Gap: Building Disability-Inclusive AI for Mental Health in Sub-Saharan Africa (Christopher Harrison)\n7868 - LUMANA: Field Validation of a Culturally-Centered AI Mental Health Screening System in Sokoto State, Nigeria (Tahir Buhari)\n7899 - Strengthening a School-Based Digital Mental Health Ecosystem in Thailand's Border Communities: Co-design Process, Early Implementation, and Lessons Learned (Worarat Khuenpetch)\n8094 - Responsible AI in Action: Scaling the JustAsk! Chatbot to Advance Adolescent and Youth Health in India (SAHIL KAPOOR, Deepa Prasad)\n8688 - Cost-Effectiveness of a Mobile-Application Intervention for Childhood Obesity in Thailand: A Markov Model-Based Economic Evaluation (Nantikarn Yingrattanasuk)","sp":[{"n":"Christopher Harrison","a":"Next Step Foundation","b":"Christopher Harrison, J.D., Ph.D., is Co-Founder and Head of AI at the Next Step Foundation, where he leads the development of AI-enabled tools focused on mental health, disability inclusion, and workforce development in East Africa. His work combines technical deployment with a global systems and policy perspective, informed by his doctoral training in international relations. He is the co-creator of Tumaini, an AI-powered, WhatsApp-delivered mental…"},{"n":"Tahir Buhari","a":"eHealth Africa","b":"Tahir Buhari is a Senior Research Program Manager at eHealth Africa, based in Kano, Nigeria, where he leads AI and digital health research at the intersection of implementation science, frontline primary care, and health systems strengthening. He serves as Principal Investigator or Project Manager for a portfolio of AI studies funded by the Wellcome Trust, Bill & Melinda Gates Foundation, GAVI, and PharmAccess Foundation, with cumulative research…"},{"n":"Worarat Khuenpetch","a":"Mahidol Oxford Tropical Medicine Research Unit","b":"Worarat Khuenpetch (MSc, MPA) is a researcher focusing on health equity, digital health, mental health, and community-driven approaches to improving access to health services, particularly for children and vulnerable populations in remote and border communities in Thailand. She is based in the Epidemiology Department at the Mahidol Oxford Tropical Medicine Research Unit (MORU), where her work bridges field research, digital intervention design,…"},{"n":"SAHIL KAPOOR","a":"United Nations Population Fund (UNFPA)","b":"Sahil Kapoor leads the Innovation and Technology Unit at UNFPA India, bringing over 16 years’ experience in embedding innovation into programmes through emerging technologies such as AI and blockchain, and applying behavioral science to drive transformation in health, gender, education, and digital inclusion. He has collaborated with governments and private sector partners across Asia and Africa to design adaptive systems, scale innovation-led…"},{"n":"Deepa Prasad","a":"United Nations Population Fund (UNFPA)","b":"Dr. Deepa Prasad is a highly accomplished public health leader currently serving as the Chief of Programs and Technical Support Unit at the UNFPA India Country Office, a position she has held since April 2021. Bringing a wealth of expertise and 15 years of dedicated experience with UNFPA India, Dr. Prasad is a specialist in high-level policy design, comprehensive program management, multi-stake agency coordination, and influential leadership. Her…"},{"n":"Nantikarn Yingrattanasuk","a":"Roi Et Hospital, Ministry of Public Health Thailand","b":"I am a family physician and have practised at Roi Et Hospital, a provincial hospital in northeastern Thailand, since 2021. I earned my medical degree (second-class honours) from Khon Kaen University and hold board certification in Family Medicine. My interest in digital health led to roles at the Office of the Permanent Secretary, Ministry of Public Health(2024-2025), where I worked on primary care and digital health as Deputy Director of the Primary…"}]},{"id":"s108","t":"Integrated Digitization of Health Campaigns: Multi-Country M&E Results","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Pre-formed Panel","Governance and Digital Health at Scale","Hybrid Livestream"],"fmt":"Pre-formed Panel","theme":"Governance and Digital Health at Scale","mode":"Hybrid Livestream","desc":"Digitising health campaigns can improve data quality, allow mid-campaign corrections and strengthen worker management, but only when governments have the ownership, capacity and structures to act on the data. This panel presents results from a multi-country effort to digitise malaria, neglected tropical disease and immunisation campaigns at scale, measured against a shared framework adapted from WHO guidance. After a brief introduction from CHAI, teams from Nigeria's Kano State, Kenya and Mozambique share evidence on how digitisation affected data quality, data use, coverage and cost, and what made the difference.","sp":[{"n":"Sameen Babur","a":"Clinton Health Access Initiative","b":"Sameen Babur, Director, Digital Health, Malaria & NTDs: Sameen will provide strategic and technical oversight for components specific to digital health, including data systems (platforms and software), enterprise architecture, and interoperability. Sameen has 9 years’ of experience managing digital health initiatives end-to-end, including overseeing the design, development, deployment and implementation of multiple mobile tools and information systems.…"},{"n":"Mohammed Nura Yahaya","a":"Kano State Ministry of Health","b":"Mohammed Nura Yahaya is the Director of Planning, Research and Statistics at the Kano State Ministry of Health, with over 20 years of experience in public health leadership, health systems strengthening, disease surveillance, and primary healthcare. He has led the planning and implementation of major health programs across Kano State, including the Basic Health Care Provision Fund (BHCPF), malaria control, immunization, and COVID-19 response, where he…"},{"n":"Dickson Kioko","a":"Kenya Ministry of Health - Division of Vector-borne and Neglected Tropical Diseases","b":"Dickson Kioko is a Medical Entomologist and Public Health Specialist with over a decade of experience in Vector-Borne and Neglected Tropical Disease (NTD) Control at the Kenya National Public Health Institute, Ministry of Health. Currently serving as Assistant Director, Medical Entomologist in the Ministry of Health, he plays a pivotal national role as the focal person for Human African Trypanosomiasis, Guinea worm, and Snakebite Envenoming, in…"},{"n":"Mariana da Silva","a":"Mozambique Ministry of Health - National Malaria Control Programme","b":"Mariana has worked in various roles in Mozambique's malaria control space over the last 15 years in the Ministry of Health, both at the subnational and national level with a focus on surveillance, monitoring & evaluation and operational research within the National Malaria Control Programme. Over the last 5 years she has been involved on the establishment and institutionalization of the malaria data repository (NMDR) in the Ministry of Health and…"}]},{"id":"s110","t":"Who Pays for Digital Health? Rethinking Financing and Partnerships in a Post-ODA Era","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Pre-formed Panel","Financing for Sustainability","In-person"],"fmt":"Pre-formed Panel","theme":"Financing for Sustainability","mode":"In-person","desc":"As development assistance for health falls, countries need new ways to sustain digital health investments that have depended on short-term donor funding. The Pacific Healthy Islands Transformation (PHIT) Project, a US$239.5 million programme in Fiji, Kiribati, Tonga and Tuvalu, offers one model. Instead of funding standalone digital projects, it builds learning systems, workforce registries, telehealth, AI-enabled clinical tools and interoperability into wider primary healthcare reform, financed by international financial institutions and owned by governments. Speakers from UNICEF, the World Bank, the Pacific Community and Fiji's Ministry of Health share lessons on moving from grant-funded pilots to sustainable models.","sp":[{"n":"Naina Ahuja","a":"UNICEF"},{"n":"Margareta Norris Harrit","a":"World Bank"},{"n":"Agazi Ameha","a":"UNICEF"},{"n":"Rumanusina Maua","a":"SPC"},{"n":"Shaneel Prakash","a":"Fiji Ministry of Health"}]},{"id":"s223","t":"World Bank Sponsored Breakout: Cross-Region Lessons from Telemedicine Implementations","d":"2026-12-04","s":"9:40","e":"10:40","tags":["Sponsored Breakout","In-person","Sponsored Session"],"fmt":"Sponsored Session","theme":"","mode":"In-person","desc":"","sp":[{"n":"Ali Habib","a":"The World Bank","b":"Ali Habib is a Senior Digital Health Specialist in the World Bank Group's Global Digital Health and AI team. In this role he provides technical assistance to World Bank country teams and clients on the planning, designing, budgeting, and implementation of digital health aspects of World Bank-financed projects. Ali has led the development of knowledge products like the World Bank’s Digital Health Blueprint Toolkit, aimed at helping countries design, cost out, and implement standards-based national scale health information exchanges. He has twenty years of experience in the digital health space including in the development, adaptation, and implementation of global digital public goods in more than twenty countries."},{"n":"Tomas Svec","a":"Department of Digitalisation, Ministry of Health, Slovak Republic","b":""},{"n":"Maria Jose Letelier","a":"Digital Health Department, Ministry of Health, Republic of Chile","b":"Dr. María José Letelier Ruiz is a dental surgeon trained at the University of Chile. She holds a master’s degree in public health from Pompeu Fabra University in Barcelona, Spain, and is a candidate for a master’s degree in medical informatics at Hospital Italiano de Buenos Aires, Argentina. For the past seven years, she has served as Head of the Digital Health Department at Chile’s Ministry of Health, leading national digital health transformation initiatives and overseeing Chile’s Digital Hospital."},{"n":"Ma’ake Tupou","a":"Ministry of Health, Tonga","b":"Dr Ma’ake Tupou is the Medical Superintendent at Vaiola Hospital, Ministry of Health, Tonga, where he oversees hospital operations and the delivery of clinical services. He also leads the Ministry's digital health initiatives under the World Bank supported Pacific Healthy Islands Transformation (PHIT) Project, working to bring digital technologies into everyday healthcare services. His work focuses on strengthening clinical information systems, supporting the adoption of digital health solutions and exploring new ways technology can improve healthcare delivery. With his background in hospital operations and clinical services, Dr Tupou brings an important healthcare perspective to Tonga's digital health transformation, helping ensure that new technologies respond to the needs of health professionals and the communities they serve."}]},{"id":"s109","t":"Poster Presentations (Round 3)","d":"2026-12-04","s":"9:45","e":"11:15","tags":["Poster Presentation","In-person"],"fmt":"Poster Presentation","theme":"","mode":"In-person","desc":"The third poster round covers clinical language models, AI for diagnosis and humanitarian response, public views of AI health tools, digital identity and health coverage in Thailand, laboratory systems and health workforce registries. Presenters will be at their posters to discuss their work.\n\nPoster presentations in this session:\n7643 - AJCC Staging for Head and Neck Cancer Using RAG-Enhanced Open-Source Large Language Models: A Performance Benchmarking Study (Ekapob Sangariyavanich)\n8184 - Fully Open Meditron: An Auditable Pipeline for Clinical LLMs (Xavier Theimer-Lienhard, Trevor Brokowski)\n8457 - Multimodal for Cervical Cancer Histopathology Classification and Automated Diagnostic Report Generation (Rose Nakasi)\n8710 - AI-powered emergency reporting and information synthesis for humanitarian disaster response (Mila Dorji)\n8815 - \"UNDERSTANDING PUBLIC PERCEPTION OF AI-HEALTH TOOLS: A Focus Group Study in Thailand compared to Singapore (NITCHANUND TANTISIRIVIT)\n7761 - Assessing digital maturity for sexual and reproductive health and rights organizations: lessons from a multi-country cohort of IPPF Member Associations (Daniel Florez, Lorena Calderón)\n8089 - Beyond Digital Incentives: Lessons from Scaling Mobile Conditional Cash Transfers for Childhood Immunization (Mohammad Owais Siddiqui)\n8100 - Thailand Health Atlas: A National Geospatial Digital Health Platform for Area-Based Public Health Planning (Wachiraporn Arunothong, Warodom Sornsurin)\n8237 - Digitizing International Conveyance Health Declarations and Sanitation Certification: Lessons from Thailand's DDC Pass at Scale. (Thawabhorn Jannok)\n8402 - Scanning for Trust: Biometric Digital Identification and Migrant Acceptance in Thailand's Health System (Jitphanu Sridet, Siripa Puaksunteir)\n8814 - Mixed-Methods Evaluation of a Community-Based Integrated Care Model for DM & HT Using the \"Mor Na Ban\" Application and a Color-Coded Patient Classification System (JIRATTIKAN OUNSIRI, Thanisara Thitisiripong)\n8021 - From Excel to Alerts: Automating Sample Tracking and Result Dissemination in Kenya's National Public Health Intelligence Information System (Yusuf Ibrahim)\n8224 - Toward Zero Asthma Deaths: Bridging HL7-FHIR HIEs and the Pediatric Asthma Network Toward Zero Asthma Deaths: Bridging HL7-FHIR Registries (Thammasin Ingviya, Teerapat Kunsirawit, Khomkrit Chuaycrotha)\n8392 - From Biometric Identity to Universal Health Coverage: Lessons from Thailand's Digital Public Infrastructure for Undocumented Migrant Populations (Jitphanu Sridet)\n7507 - The Digital Competency Paradox: Mapping the Baseline Readiness of the Future Healthcare Workforce in Vietnam (Ngoc Tam Phuc Tran)\n8592 - HWMS: Building Rwanda's National Digital Backbone for Health Workforce Lifecycle (Marie Elise Hortensia Ngabire Iradukunda, Alice Nsengiyumva)","sp":[{"n":"Ekapob Sangariyavanich","a":"National Cancer Institute of Thailand","b":"Education 2000 Faculty of medicine. Chulalongkorn University ( Second honour ) 2006 Thai board of otolaryngology head and neck surgery 2025 Doctor of philosophy program in data science for healthcare and clinical informatics, Faculty of Medicine Ramathibodi Hospital, Mahidol Univeristy. Professional membership The Medical Association of Thailand Royal College of Otolaryngologists head and neck surgeons of Thailand"},{"n":"Xavier Theimer-Lienhard","a":"LiGHT","b":"Xavier Theimer-Lienhard is a PhD student at the Laboratory for Intelligent Global Health Technologies (LiGHT) at EPFL, where he leads Meditron, an initiative making clinical AI safer, more accurate, and more transparent. He is the lead author of Fully Open Meditron, the first fully open family of medical LLMs, developed and evaluated with clinicians across eleven countries, including blinded evaluations in Tanzania and Kenya. He was previously a…"},{"n":"Trevor Brokowski","a":"LiGHT","b":"Trevor Brokowski is the Director of Innovation at the Laboratory for Intelligent Global Health and Humanitarian Response Technologies (LiGHT), where he shapes the innovation strategy, identifies emerging opportunities to create measurable impact with AI, and translates advances in research into implementable applications for health adapted to the needs of resource constrained settings. He leads work from innovation to implementation, through…"},{"n":"Rose Nakasi","a":"Makerere AI Health Lab","b":"Dr. Rose Nakasi is an artificial intelligence researcher, lecturer at Makerere University, and Head of the Makerere University AI Health Lab in Uganda. Her work focuses on developing low-cost AI-powered diagnostic technologies to strengthen healthcare delivery, particularly for malaria, tuberculosis, cervical cancer, and intestinal parasites. She chairs the International Telecommunication Union (ITU), World Intellectual Property Organization (WIPO),…"},{"n":"Mila Dorji","a":"Direct Relief","b":"Mila Dorji is the lead Public Health Data Scientist at Direct Relief, one of the world's largest humanitarian medical aid organizations, where he builds the data methods behind decisions about where medical aid does the most good, using spatial analysis, prioritization modeling, and AI. Before Direct Relief, he worked on global health financing and cost-effectiveness at Pharos Global Health Advisors, alongside the Global Fund, UNAIDS, and country…"},{"n":"NITCHANUND TANTISIRIVIT","a":"Ministry of PUBLIC Health Thailand","b":"Dr. Nitchanund Tantisirivit, M.D., MPH (NUS) Current Positions: - Deputy Director, Digital Health Bureau, Office of the Permanent Secretary, Ministry of Public Health (MOPH), Thailand Profile Summary: Dr. Nitchanund is a visionary pediatrician and healthcare executive with extensive experience in clinical care, healthcare strategy, and digital health transformation in Thailand. She currently spearheads strategic planning at Nan Hospital and drives…"},{"n":"Mitali Ayyangar","a":"DataKind","b":"Mitali (Tali) is a data-for-social-impact leader working at the intersection of global development, data science and AI. She is the Director of Global Communities at DataKind, where she leads partnerships with NGOs, governments, and frontline organizations to co-create data and AI-driven solutions that strengthen health systems, improve humanitarian response, and progress sustainable, inclusive social change. Her work centers on translating data and…"},{"n":"Wanjiru Waruiru","a":"Director, Global Health Security","b":"Wanjiru Waruiru, MBA, MPH is a global health leader and epidemiologist. Her work focuses on pandemic preparedness, disease surveillance, and strengthening health systems in low- and middle-income countries. She has led multi-country programs in partnership with ministries of health, donors, NGOs, and academic institutions, including the University of California, San Francisco (UCSF) and the U.S. Centers for Disease Control and Prevention (CDC). Wanjiru…"},{"n":"Daniel Florez","a":"Profamilia","b":"Daniel Flórez Gil is Coordinator of the COLAB Digital Health Intervention Center at the International Planned Parenthood Federation and Profamilia. He is an economist with a master’s degree in technology project design and has over 15 years of experience in consulting, digital transformation, and innovation in the health sector across public and private organizations. His work focuses on the design, implementation, and scaling of digital solutions that…"},{"n":"Lorena Calderón","a":"Profamilia","b":"Business Administrator and prospective candidate for a Master’s degree in Peacebuilding, with over 10 years of experience across the academic, humanitarian, public and private sectors, and with national and international organisations. I currently work as a Knowledge Management Analyst at Colab, the Digital Health Interventions Centre of Profamilia (Colombia) and IPPF, where I support the systematisation, sharing and mobilisation of knowledge from…"},{"n":"Mohammad Owais Siddiqui","a":"IRD","b":"This session will be presented by Mohammad Owais Siddiqui, Senior Program Manager at IRD Pakistan, who led strategy, operations, monitoring, stakeholder engagement, donor reporting, and program close-out of the mCCT program. His field experience offers practical implementation lessons for designing equitable, people-centered digital health financing interventions in diverse settings."},{"n":"Wachiraporn Arunothong","a":"Office of the Permanent Secretary Ministry of Public Health","b":"Name Wachiraporn Arunothong. Nationality Thai Education Diploma in Clinical epidemiology and clinical statistic class of 2018-2019, Chiangmai University, Thailand Preventive Medicine, Community Mental Health, 2016-2017 Suanprung Hospital, Department of Mental Health, Thailand PhD, Biomedical and Health Informatics, 2011 – 2014 University of Wisconsin-Milwaukee, Milwaukee, USA Child and Adolescent Psychiatry Residency Training, 2004 - 2008 Siriraj…"},{"n":"Warodom Sornsurin","a":"Office of the Permanent Secretary Ministry of Public Health"},{"n":"Thawabhorn Jannok","a":"Department of Disease Control, Ministry of Public Health, Thailand","b":"I am a Public Health Technical Officer (Professional Level) and the Chief of the Digital Surveillance System Development Section within the Division of International Disease Control Port and Quarantine, Department of Disease Control, Ministry of Public Health, Thailand. In this role, I am responsible for developing digital systems for the sanitation inspection of various conveyances, including ships, aircraft, and ground vehicles. I also develop…"},{"n":"Jitphanu Sridet","a":"Department of Disease Control, Ministry of Public Health"},{"n":"Siripa Puaksunteir","a":"Office of International Cooperation, Department of Disease Control"},{"n":"JIRATTIKAN OUNSIRI","a":"NONGHIN HOSPITAL","b":"Pharmacist (Pharm.D) Master of Science Program in Digital and AI Technologies in Health Systems"},{"n":"Thanisara Thitisiripong","a":"NONGHIN HOSPITAL","b":"Director of Nonghin Hospital"},{"n":"Yusuf Ibrahim","a":"Kenya National Public Health Institute"},{"n":"Thammasin Ingviya","a":"Department of Clinical Research and Medical Data Science, Faculty of Medicine, Prince of Songkla University","b":"POSITION TITLE: Assistant Professor of Epidemiology Head of the Department of Clinical Research and Medical Data Science Vice Director of the Division of Digital Innovation and Data Analytics, Prince of Songkla University, Thailand EDUCATION/TRAINING INSTITUTION AND LOCATION DEGREE (if applicable) Completion Date MM/YYYY FIELD OF STUDY Prince of Songkla University, Thailand MD 06/10 Medicine Johns Hopkins Bloomberg School of Public Health, MD MHS 05/13…"},{"n":"Teerapat Kunsirawit","a":"Division of Digital Innovation and Data Analytics, Faculty of Medicine, Prince of Songkla University","b":"Teerapat Kunsirawit is a 28-year-old Computer Technical Officer currently working in the Division of Digital Innovation and Data Analytics at the Faculty of Medicine, Prince of Songkla University in Thailand. He is employed as a University Revenue Employee, a position he has held since his appointment on October 1, 2020. He earned his Bachelor of Science in Computer Science from Prince of Songkla University, graduating in 2019. With a scheduled…"},{"n":"Khomkrit Chuaycrotha","a":"Division of Digital Innovation and Data Analytics, Faculty of Medicine, Prince of Songkla University","b":"Mr. Khomkrit Chuaycrotha is a 28-year-old Computer Technical Officer at the Practitioner Level. He has been working as a government employee at the Office of Data Analysis and Digital Innovation, Faculty of Medicine, Hat Yai Campus, since August 1, 2022. He holds a Bachelor of Science (B.Sc.) in Computer Science from Rajamangala University of Technology Srivijaya, Thailand, which he completed in 2020."},{"n":"Ngoc Tam Phuc Tran","a":"Hanoi Medical University","b":"I'm Trần Ngọc Tâm Phúc, a fourth-year medical student at Hanoi Medical University. My background is heavily rooted in clinical and public health research. I've worked on a wide variety of projects. Lately, I've been focusing on how prepared future clinicians are for health technology, specifically researching the digital competency of early-stage medical students. I'm really excited to be at this forum to connect with others who are passionate about…"},{"n":"Marie Elise Hortensia Ngabire Iradukunda","a":"Ministry of Health Rwanda","b":"Dr. Marie Elise Ngabire is a medical doctor currently working in the Health Workforce developement department in the Ministry of Health Rwanda, with experience in public health emergency response and health workforce development. Her work focuses on strengthening health systems and advancing digital transformation to improve how healthcare professionals are trained, employed, and supported. She is passionate about building resilient, equitable health…"},{"n":"Alice Nsengiyumva","a":"Ministry of Health Rwanda","b":"Dr. Alice Nsengiyumva is as compassionate Medical Doctor and Global Health Delivery Specialist with multidisciplinary experience in clinical care, health systems strengthening, research, and workforce policy. Currently working in the Health Workforce development department she is skilled in evidence synthesis, project coordination, and guideline development. Proven ability to connect frontline clinical practice with strategic leadership. Dedicated to…"}]}]};
